window.POEM_DB=window.POEM_DB||{};POEM_DB["song_015"]={"n":"苏辙","dyn":"宋","poems":[{"t":"次韵毛君山房即事十首 其二","f":"七言绝句","c":["东晋仙人借旧山，定应天意许公閒。","郡人欲问史君处，笑指峰峦紫翠间。"]},{"t":"和毛国镇白云庄五咏 其五 白云庄偶题","f":"七言律诗","c":["归去携家住白云，云中猿鹤许同群。","陶公酒后诗偏好，疏傅金馀客屡醺。","芒屩潜行逐渔钓，壶浆时出劳耕耘。","却看人世应微笑，未熟黄粱昼梦纷。"]},{"t":"和文与可洋州园亭三十咏 其二十五 寒芦港","f":"五言绝句","c":["芦深可藏人，下有扁舟泊。","正似洞庭风，日莫孤帆落。"]},{"t":"补子瞻赠姜唐佐秀才","f":"七言律诗","c":["生长茅间有异芳，风流稷下古诸姜。","适从琼管鱼龙窟，秀出羊城翰墨场。","沧海何曾断地脉，白袍端合破天荒。","锦衣他日千人看，始信东坡眼力长。"]},{"t":"二月望日雪二绝 其一","f":"七言绝句","c":["玄冥留雪恼中春，损麦伤花病老人。","已典布裘捐衲袜，朝来酒尽乞比邻。"]},{"t":"二月望日雪二绝 其二","f":"七言绝句","c":["老翁衰病不忧花，百口唯须麦养家。","闻道田中犹要雪，兼收凝白试山茶。"]},{"t":"万蝶花","f":"七言绝句","c":["谁唱残春蝶恋花，一团粉翅压枝斜。","美人欲向钗头插，又恐惊飞鬓似鸦。"]},{"t":"三日上辛祈谷除日宿斋户部右曹元日赋三绝句寄呈子瞻兄 其三","f":"七言绝句","c":["北客南来岁欲除，灯山火急万人扶。","欲观翠辇巡游盛，深怯南宫锁钥拘。"]},{"t":"上元前雪三绝句 其一","f":"七言绝句","c":["腊中平地雪盈尺，嵩隗山田麦尚乾。","不管上元灯火夜，飞花处处作春寒。"]},{"t":"上元前雪三绝句 其二","f":"七言绝句","c":["闭门不问门前事，灯火薰天自不知。","闻道朝来雪又下，老人今岁未应饥。"]},{"t":"上元前雪三绝句 其三","f":"七言绝句","c":["天公似管人间事，近事传闻半是非。","但使麦田饶雨雪，饥人得饱未相违。"]},{"t":"大雨后咏南轩竹二绝句 其一","f":"七言绝句","c":["苦寒坏我千竿绿，好雨还催众笋长。","痛饮虽无嵇阮客，瓢尊一试午阴凉。"]},{"t":"大雨后咏南轩竹二绝句 其二","f":"七言绝句","c":["叶开翡翠才通日，节竦琅玕不怕风。","稍放西边深二丈，端如幽谷茂林中。"]},{"t":"大雪三绝句 其二","f":"七言绝句","c":["玄冥留雪付勾芒，桃李虽忧麦未伤。","膏泽较迟三十日，问天此意亦茫茫。"]},{"t":"大雪三绝句 其一","f":"七言绝句","c":["闰岁穷冬已是春，当寒却暖未宜人。","阴风半夜催飞霰，稍净天街一尺尘。"]},{"t":"大雪三绝句 其三","f":"七言绝句","c":["连岁金明不见冰，上春风雪气棱棱。","台中曾奏五行传，到此施行愧未曾。"]},{"t":"子瞻与长老择师相遇于竹西石塔之间屡以绝句赠之又留书邀辙同作遂以一绝继之","f":"七言绝句","c":["远老陶翁好弟兄，虎溪庐阜久逢迎。","何须更要经平子，清议从来贵士衡。"]},{"t":"子瞻赠岭上老人次韵代老人答","f":"七言绝句","c":["岭头卢老一炉灰，长短根茎各自栽。","轻贱已消先世业，知君海上去仍回。"]},{"t":"山橙花口号","f":"七言绝句","c":["故乡寒食荼蘼发，百和香浓村巷深。","漂泊江南春欲尽，山橙仿佛慰人心。"]},{"t":"五月园夫献红菊二绝句 其二","f":"七言绝句","c":["南阳白菊有奇功，潭上居人多老翁。","叶似皤蒿茎似棘，未宜放入酒杯中。"]},{"t":"五月园夫献红菊二绝句 其一","f":"七言绝句","c":["黄花九月傲清霜，百草满园无此香。","红紫无端盗名字，试寻本草细商量。"]},{"t":"以蜜酒送柳真公","f":"七言绝句","c":["床头酿酒一年馀，气味全非卓氏垆。","送与幽人试尝看，不应知是百花须。"]},{"t":"元老见访留坐具而去戏作一绝调之","f":"七言绝句","c":["石霜旧夺裴休笏，坐具只今君自留。","留放书房还会否，受降曾不费戈矛。"]},{"t":"元老和示小诗自谓非战之罪复作一绝并坐具还之","f":"七言绝句","c":["请君却领弥天具，不欲终收陷虎名。","莫道昏沉非战罪，何如不战屈人兵。"]},{"t":"东西京二绝 其二","f":"七言绝句","c":["犀箸金槃不暇尝，更须石上捣黄粱。","数钱未免河东旧，不识前朝大练光。"]},{"t":"东西京二绝 其一","f":"七言绝句","c":["亲祀甘泉岁一终，属车徐动不惊风。","宓妃何预词臣事，指点讥呵豹尾中。"]},{"t":"东轩长老二绝 其二","f":"七言绝句","c":["担头挑得黄州笼，行过圆通一笑开。","却到山前人已寂，亦无一物可担回。"]},{"t":"东轩长老二绝 其一","f":"七言绝句","c":["东轩正似虚空样，何处人家笼解盛。","纵使盛来无处著，雪堂自有老师兄。"]},{"t":"去年冬辙以起居郎入侍迩英讲不逾时迁中书舍人虽忝冒愈深而瞻望清光与日俱远追记当时所见作四绝句呈同省诸公 其二","f":"七言绝句","c":["铜瓶洒遍不胜寒，雨点匀圆冻未乾。","回首曈眬朝日上，槐龙对舞覆衣冠。"]},{"t":"去年秋扇二绝句 其一","f":"七言绝句","c":["箧中秋扇委尘埃，春晚炎风拂面来。","旧物不辞为世用，故人相见莫心猜。"]},{"t":"去年秋扇二绝句 其二","f":"七言绝句","c":["扇中秦女旧乘鸾，拂去浮尘色尚鲜。","未尽炎风早归去，不堪秋后乞哀怜。"]},{"t":"记梦","f":"七言绝句","c":["长鱼三尺困横盆，送入清流喜欲奔。","报我金匙仅盈寸，掷还聊喜不贪存。"]},{"t":"再赋葺居三绝 其一","f":"七言绝句","c":["谁将修竹寄邻家，秋斫长竿春食芽。","旋筑高墙护鸡犬，稍容嵇阮醉喧哗。"]},{"t":"再赋葺居三绝 其三","f":"七言绝句","c":["南北高堂本富家，百年梁柱半攲斜。","略教扶起犹堪住，西望吾庐已自奢。"]},{"t":"再赋葺居三绝 其二","f":"七言绝句","c":["短垣疏户略藏遮，翠竹长松夹径斜。","游宦归来四十载，粗成好事一田家。"]},{"t":"同外孙文九新春五绝句 其三","f":"七言绝句","c":["菊叶萱芽初出土，冻齑冷面欲宜人。","老人脾病难随汝，洗釜磨刀待晚春。"]},{"t":"同外孙文九新春五绝句 其五","f":"七言绝句","c":["雪覆西山三顷麦，一犁春雨祝天工。","麦秋幸与人同饱，昔日黄门今老农。"]},{"t":"同外孙文九新春五绝句 其四","f":"七言绝句","c":["筑室恨除千本竹，及春先补百株花。","隔年预与园夫约，春雨晴时问汝家。"]},{"t":"同外孙文九新春五绝句 其二","f":"七言绝句","c":["瓮中腊脚长忧冻，户外春风那得知。","酒熟定应花未动，举瓢先对柳千丝。"]},{"t":"同外孙文九新春五绝句 其一","f":"七言绝句","c":["佳人旋贴钗头胜，园父初挑雪底芹。","欲得春来怕春晚，春来会似出山云。"]},{"t":"孙宾叟道人","f":"七言绝句","c":["万里飘然不系舟，酒垆一笑便相投。","千金不换金丹诀，何事惟须一布裘。"]},{"t":"岁莫口号二绝 其二","f":"七言绝句","c":["两世相从今几人，回头强半已埃尘。","此心点检终如一，时事无端日日新。"]},{"t":"岁莫口号二绝 其一","f":"七言绝句","c":["六十年来又七年，眼昏头白意茫然。","逢人欲说平生旧，少有能知两世前。"]},{"t":"戏答","f":"七言绝句","c":["银瓶泻酒正霜天，玉麈生风夜更寒。","下客不辞投辖饮，好花犹恐隔帘看。"]},{"t":"戏题三绝 其一","f":"七言绝句","c":["懊恼嘉荣白发年，逢人依旧唱阳关。","渭城朝雨今谁听，砑鼓跳踉一破颜。"]},{"t":"戏题三绝 其二","f":"七言绝句","c":["谢傅凄凉已老年，胡琴羌笛怨遗贤。","使君于此虽不俗，挽断髭须谁见怜。"]},{"t":"戏题三绝 其三","f":"七言绝句","c":["遍地花钿叹百年，苍颜白发意凄然。","回头笑指此郎子，破贼将来知有天。"]},{"t":"戏赠李朝散","f":"七言绝句","c":["江雾霏霏作雪天，樽前醉倒不知寒。","后堂桃李春犹晚，试觅酥花子细看。"]},{"t":"次韵子瞻上元扈从观灯二首 其二","f":"七言绝句","c":["春来有意乞归耕，足痹三年久未平。","忽记上元銮辂出，起听前殿晓钟声。"]},{"t":"次韵子瞻上元扈从观灯二首 其一","f":"七言绝句","c":["虏去边城少奏章，雪残中禁罢焚香。","都人知有新年喜，争看雕舆金凤凰。"]},{"t":"次韵子瞻登望海楼五绝 其一","f":"七言绝句","c":["山色潮声四面来，城中金碧烂成堆。","不愁门外严扃锁，终日凭栏未拟回。"]},{"t":"次韵子瞻登望海楼五绝 其二","f":"七言绝句","c":["湖色苍苍日向斜，烟波万状不容誇。","画船人去浮红叶，石径僧归蹑白蛇。"]},{"t":"次韵子瞻登望海楼五绝 其三","f":"七言绝句","c":["楼观争高不计层，噰噰过雁自相应。","钱王旧业依稀在，岁久无人话废兴。"]},{"t":"次韵子瞻登望海楼五绝 其四","f":"七言绝句","c":["荷叶初乾稻穗香，惊雷急雨送微凉。","晚晴稍放秋山色，洗却浓妆作淡妆。"]},{"t":"次韵子瞻登望海楼五绝 其五","f":"七言绝句","c":["白酒倾浆脍斫红，昼游未厌月明中。","楼高只办听歌鼓，不见游人转似蓬。"]},{"t":"次韵毛君山房即事十首 其四","f":"七言绝句","c":["溪山付与醉中仙，美酒何曾斗十千。","就得江边贱鱼稻，闲官未用苦相怜。"]},{"t":"次韵毛君山房即事十首 其五","f":"七言绝句","c":["忘身先要解忘名，分别须臾起不平。","请看早朝霜入屦，何如卧听打衙声。"]},{"t":"次韵毛君山房即事十首 其六","f":"七言绝句","c":["禽哢秋来不复圆，桐阴霜后亦成穿。","黄花强欲招酣饮，白发偏工报老年。"]},{"t":"次韵毛君山房即事十首 其七","f":"七言绝句","c":["邂逅清欢屡不期，病来无奈羽觞飞。","醉乘篮舆江边去，长伴渔舟月下归。"]},{"t":"次韵毛君山房即事十首 其八","f":"七言绝句","c":["醉里题诗偏韵恶，秋来劝酒益杯深。","不才多病俱非敌，绿绮缘何得报金。"]},{"t":"次韵毛君山房即事十首 其三","f":"七言绝句","c":["蛩知秋候时鸣壁，香碍蒲帘不出门。","隐几无言心有得，南窗晴日暖侵轩。"]},{"t":"次韵毛君山房即事十首 其九","f":"七言绝句","c":["庵中独宿雨垂垂，永夜无人款竹扉。","灰冷铜炉香欲灭，床头一点葛灯微。"]},{"t":"次韵毛君见督和诗","f":"七言绝句","c":["新诗落纸一城传，顾我疏芜岂足编。","他日杜陵诗集里，韦迢略见两三篇。"]},{"t":"次韵王适春雪二首 其二","f":"七言绝句","c":["春雪飘摇旋不成，依稀履迹散空庭。","山藏复阁犹残白，日照南峰已半青。"]},{"t":"次韵冯弋同年","f":"七言绝句","c":["细雨濛濛江雾昏，坐曹聊且免泥奔。","卖盐酤酒知同病，一笑何劳赋北门。"]},{"t":"次韵刘贡父题文潞公草书","f":"七言绝句","c":["鹰扬不减少年时，墨作龙蛇纸上飞。","应笑学书心力尽，临池写遍未裁衣。"]},{"t":"次韵孙推官朴见寄二首 其一","f":"七言绝句","c":["蒙愠未能忧悄悄，得闲时复醉昏昏。","知君亦学无言语，岂悟维摩不二门。"]},{"t":"次韵张恕戏王巩","f":"七言绝句","c":["二君豪俊并侯家，歌舞争妍不受誇。","闻道肌肤如素练，更堪鬓发似飞鸦。"]},{"t":"次韵李逵见赠","f":"七言绝句","c":["太学群游经最明，青衫憔悴竟何成。","齑盐仍作当年味，名誉飞蝇过耳声。"]},{"t":"次韵贡父子开直宿","f":"七言绝句","c":["掷简摇毫气吐虹，兴馀庭药咏残红。","今宵文字知无几，鼾睡帘中笑二公。"]},{"t":"次韵黄庭坚学士猩毛笔","f":"七言绝句","c":["不悟身边一斗红，圣贤随世亦时中。","何人知有中书巧，缚送能书陈孟公。"]},{"t":"次韵答人幽兰","f":"七言绝句","c":["幽花耿耿意羞春，纫佩何人香满身。","一寸芳心须自保，长松百尺有为薪。"]},{"t":"次韵题画卷四首 其一 山阴陈迹","f":"七言绝句","c":["卧对郗人气已真，晚依丘壑更无伦。","不须复预清言侣，自是江东第一人。"]},{"t":"次韵题画卷四首 其二 雪溪乘兴","f":"七言绝句","c":["亟往遄归真旷哉，聋人不信有惊雷。","虽云不必见安道，已误扁舟犯雪来。"]},{"t":"次韵题画卷四首 其三 四明狂客","f":"七言绝句","c":["失脚来游九陌尘，故溪何日定抽身。","便同贺老扁舟去，已笑西山郑子真。"]},{"t":"次韵题画卷四首 其四 西塞风雨","f":"七言绝句","c":["雨细风斜欲暝时，淩波一叶去安归。","遥知夜宿蛟人室，浪卷波分不著衣。"]},{"t":"过兴教赠钊上人","f":"七言绝句","c":["四十年间此院留，临河看尽往还舟。","同来并是三年客，听说行藏各自羞。"]},{"t":"过豫章","f":"七言绝句","c":["白屋可能无孺子，黄圭不是欠陈蕃。","古人冷淡今人笑，湖水年年刺旧痕。"]},{"t":"两中秋绝句二首 其二","f":"七言绝句","c":["两逢重九尉佗城，蜑叟相从倒酒瓶。","十二年来均寂寞，此心南北两冥冥。"]},{"t":"两中秋绝句二首 其一","f":"七言绝句","c":["颍川城下两中秋，金气初凝火尚流。","脾病家人不教饮，官厨好酒亦难求。"]},{"t":"初至金陵","f":"七言绝句","c":["山川过雨晓光浮，初看江南第一州。","路绕匡庐更南去，悬知是处可忘忧。"]},{"t":"巫山庙乌","f":"七言绝句","c":["巫庙真人古列仙，高心独爱玉炉烟。","饥乌巧会行人意，来去纷纷噪客船。"]},{"t":"补种牡丹二绝 其一","f":"七言绝句","c":["野草凡花著地生，洛阳千叶种难成。","姚黄性似天人洁，粪壤埋根气不平。"]},{"t":"闰九月重九与父老小饮四绝 其四","f":"七言绝句","c":["尉佗城下两重阳，白酒黄鸡意自长。","卯饮下床虚已散，老年不似少年忙。"]},{"t":"闰九月重九与父老小饮四绝 其一","f":"七言绝句","c":["九日龙山霜露凝，龙川九日气如烝。","偶逢闰月还重九，酒熟风高喜不胜。"]},{"t":"闰九月重九与父老小饮四绝 其三","f":"七言绝句","c":["客主俱年六十馀，紫萸黄菊映霜须。","山深瘴重多寒势，老大须将酒自扶。"]},{"t":"闰九月重九与父老小饮四绝 其二","f":"七言绝句","c":["获罪清时世共憎，龙川父老尚相寻。","直须便作乡关看，莫起天涯万里心。"]},{"t":"和子瞻三游南山九首 传经台","f":"七言绝句","c":["轮扁不能令子巧，老聃虽智若为传。","遗经尚在台如故，弟子今无似喜贤。"]},{"t":"和子瞻濠州七绝 四望亭","f":"七言绝句","c":["唐史不闻刘嗣之，空传短李旧歌诗。","高亭毁尽唯存记，犹有区区父老知。"]},{"t":"和子瞻濠州七绝 观鱼台","f":"七言绝句","c":["庄子谈空惠子听，郢人斤斧俟忘形。","莫嗟质丧无知者，对石何妨自说经。"]},{"t":"和子瞻濠州七绝 浮山洞","f":"七言绝句","c":["洞府元依水面开，秋潮每到洞门回。","幽人燕坐门前石，长看长淮船去来。"]},{"t":"和子瞻濠州七绝 涂山","f":"七言绝句","c":["娶妇山中不肯留，会朝山下万诸侯。","古人辛苦今谁信，只见清淮入海流。"]},{"t":"和子瞻濠州七绝 逍遥堂","f":"七言绝句","c":["猖狂战国古神仙，曳尾泥涂老更安。","厌世乘云人不见，空坟聊复葬衣冠。"]},{"t":"和子瞻濠州七绝 彭祖庙","f":"七言绝句","c":["长说先师似老彭，共疑好学古书生。","不知亦解餐云母，白日登天万事轻。"]},{"t":"和子瞻濠州七绝 虞姬墓","f":"七言绝句","c":["布叛增亡国已空，摧残羽翮自令穷。","艰难独与虞姬共，谁使西来敌沛公。"]},{"t":"和文与可洋州园亭三十咏 其三 书轩","f":"五言绝句","c":["绿竹覆清渠，尘心日日疏。","使君遗癖在，苦要读文书。"]},{"t":"和文与可洋州园亭三十咏 其三十 北园","f":"五言绝句","c":["使君美且仁，遍地种桃李。","岂独放春花，行看食秋子。"]},{"t":"和文与可洋州园亭三十咏 其二十九 南园","f":"五言绝句","c":["官是劝农官，种桑亦其所。","安得陌上人，隔叶攀条语。"]},{"t":"和文与可洋州园亭三十咏 其十 待月台","f":"五言绝句","c":["夜色何苍苍，月明久未上。","不上倚城台，无奈东南嶂。"]},{"t":"和文与可洋州园亭三十咏 其六 荻浦","f":"五言绝句","c":["离披寒露下，萧索微风触。","摧折有馀青，从横未须束。"]},{"t":"和文与可洋州园亭三十咏 其二十一 禊亭","f":"五言绝句","c":["觞流无定处，客醉醒还酌。","毋令仲御歌，空使人惊愕。"]},{"t":"和文与可洋州园亭三十咏 其十四 霜筠亭","f":"五言绝句","c":["林高日气薄，竹色净如水。","寂历断人声，时有鸣禽起。"]},{"t":"和毛君州宅八咏 其一 凤凰山","f":"七言绝句","c":["山川蟠踞偶成形，威凤低回久未行。","更种梧桐真可致，高飞性似伯夷清。"]},{"t":"和毛君州宅八咏 其八 山房","f":"七言绝句","c":["岸帻携筇夜夜来，蒲团纸帐竹香台。","直须觅取僧为伴，更为开庵斸草莱。"]},{"t":"和毛君州宅八咏 其三 方沼亭","f":"七言绝句","c":["池上茅檐覆水低，早来秋雨尚虹霓。","败荷折苇飞鸿下，正忆渔舟泊故溪。"]},{"t":"和毛君州宅八咏 其五 李八百洞","f":"七言绝句","c":["洞府山川百里赊，洞门藤蔓锁烟霞。","神仙不与人间异，弟妹还应共一家。"]},{"t":"和毛君州宅八咏 其二 披仙亭","f":"七言绝句","c":["仙翁旧住蜀江边，千岁归来一鹤翩。","城郭已非人事改，凄凉遗迹但披仙。"]},{"t":"和毛君州宅八咏 其六 炼丹井","f":"七言绝句","c":["凿井烧丹八百年，尘缘消尽果初圆。","石床藓甃人安在，绿水团团一片天。"]},{"t":"和毛君州宅八咏 其四 翠樾亭","f":"七言绝句","c":["一夜飞霜点绿苔，晓庭黄叶扫成堆。","檐间翠樾彫疏尽，却放墙东好月来。"]},{"t":"和王晋卿都尉荼蘼二绝句 其一","f":"七言绝句","c":["春到都城曾未知，楸花时见万年枝。","多情赖有王公子，解剪金槃寄所思。"]},{"t":"和王晋卿都尉荼蘼二绝句 其二","f":"七言绝句","c":["后圃荼蘼手自栽，清于芍药酽于梅。","旧来诗客今无几，三臭馨香懒举杯。"]},{"t":"和李公择赴历下道中杂咏十二首 其二 梁山泊见荷花忆吴兴五绝","f":"七言绝句","c":["终日舟行花尚多，清香无奈着人何。","更须月出波光净，卧听渔家荡桨歌。"]},{"t":"和李公择赴历下道中杂咏十二首 其一 梁山泊见荷花忆吴兴五绝","f":"词","c":["南国家家漾綵?，芙蕖远近日微明。","梁山泊里逢花发，忽忆吴兴十里行。"]},{"t":"和李公择赴历下道中杂咏十二首 其四 梁山泊见荷花忆吴兴五绝","f":"七言绝句","c":["花开南北一般红，路过江淮万里通。","飞盖靓妆迎客笑，鲜鱼白酒醉船中。"]},{"t":"和李公择赴历下道中杂咏十二首 其五 梁山泊见荷花忆吴兴五绝","f":"七言绝句","c":["菰蒲出没风波际，雁鸭飞鸣雾雨中。","应为高人爱吴越，故于齐鲁作南风。"]},{"t":"和李公择赴历下道中杂咏十二首 其三 梁山泊见荷花忆吴兴五绝","f":"七言绝句","c":["行到平湖意自宽，繁花仍得就船看。","回头却向吴侬说，从此远游心未阑。"]},{"t":"和李公择赴历下道中杂咏十二首 下邳黄石公庙","f":"七言绝句","c":["圯下相逢南北人，三邀不倦识天真。","十年却见谷城下，寂寞同收一梦身。"]},{"t":"和李公择赴历下道中杂咏十二首 吕梁","f":"七言绝句","c":["出没悬流虽有道，凭陵险地本无心。","未能与物都无碍，咫尺清泉亦自深。"]},{"t":"和萧刓察推贺族叔司理登科还乡四首 其一","f":"七言绝句","c":["家声籍籍大江西，临老挥毫捧御题。","得意何殊少年乐，还家不惜醉如泥。"]},{"t":"和萧刓察推贺族叔司理登科还乡四首 其二","f":"七言绝句","c":["读尽家藏万卷书，萧然华发宦游初。","区区狱掾何须愧，聊把春秋试绪馀。"]},{"t":"和萧刓察推贺族叔司理登科还乡四首 其三","f":"七言绝句","c":["作官未减读书勤，簿领从今日日新。","汗简韦编谁付予，传家应有下帷人。"]},{"t":"和萧刓察推贺族叔司理登科还乡四首 其四","f":"七言绝句","c":["巷南诸子足才贤，邂逅相逢秀句传。","强作短章同寄与，异时见我一依然。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其一","f":"五言绝句","c":["决狱初迎雨，开仓旋取陈。","青黄今接夏，饥疫免忧春。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其二","f":"五言绝句","c":["帘密风时度，宫深日倍长。","纻罗随节赐，黍麦趁新尝。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其三","f":"五言绝句","c":["执热宁忘濯，清心自释烦。","东朝闻好语，畏日解馀暄。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其五","f":"七言绝句","c":["舟楫喧呼招屈处，禽鱼鼓舞放生中。","百官却拜枭羹赐，凶去方知舜有功。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其六","f":"七言绝句","c":["玉殿清虚过暑天，草庐烦促念民编。","外家近许迁新宅，不遣司农费一钱。"]},{"t":"学士院端午帖子二十七首 太皇太后阁六首 其四","f":"七言绝句","c":["出磨玉尘除旧廪，捧箱綵缕看新丝。","一年丰乐今将半，两殿欢声外得知。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其六","f":"七言绝句","c":["扬子江心泻镜龙，波如细縠不摇风。","宫中禁捧秋天月，长照人心助至公。"]},{"t":"学士院端午帖子二十七首 皇太妃阁五首 其一","f":"五言绝句","c":["晓起钟犹凝，朝回露欲乾。","逡巡下清跸，委曲问平安。"]},{"t":"奉使契丹二十八首 绝句二首 其二","f":"七言绝句","c":["日色映山才到地，雪花铺草不曾消。","晴寒不及阴寒重，揽箧犹存未著貂。"]},{"t":"奉使契丹二十八首 绝句二首 其一","f":"七言绝句","c":["乱山环合疑无路，小径萦回长傍溪。","仿佛梦中寻蜀道，兴州东谷凤州西。"]},{"t":"学士院端午帖子二十七首 夫人阁四首 其一","f":"五言绝句","c":["修厦欺晴日，重帘度细风。","群仙不烦促，长在广寒宫。"]},{"t":"学士院端午帖子二十七首 夫人阁四首 其二","f":"五言绝句","c":["寻芳空茂木，斗草得幽兰。","歌舞纤絺健，嬉游玉佩珊。"]},{"t":"学士院端午帖子二十七首 夫人阁四首 其三","f":"七言绝句","c":["新煮青筠稻米香，旋抽独茧薄罗光。","剩堆雕俎添崖蜜，争作轻衫荐寿觞。"]},{"t":"学士院端午帖子二十七首 夫人阁四首 其四","f":"七言绝句","c":["御沟绕殿细无声，飞洒彤墀晓气清。","开到石榴花欲尽，阴阴高柳一蝉鸣。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其一","f":"五言绝句","c":["寿康朝谒蚤，长信燕閒多。","不有图书乐，其如昼漏何。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其二","f":"五言绝句","c":["玉宇宜朱夏，壶冰生晚凉。","深心念行暍，清夜久焚香。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其三","f":"五言绝句","c":["蚕宫罢采撷，暴室献朱黄。","翕呷霜纨动，阑班綵缕长。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其四","f":"七言绝句","c":["六宫无事著嬉游，百药初成及早收。","菖歜还羞十二节，椿年自占八千秋。"]},{"t":"学士院端午帖子二十七首 皇太后阁六首 其五","f":"七言绝句","c":["万寿仍萦长命缕，虚心不著赤灵符。","民间风俗疑当共，天上清高定尔无。"]},{"t":"学士院端午帖子二十七首 皇太妃阁五首 其二","f":"五言绝句","c":["压蔗出寒浆，敲冰簇画堂。","人间正袢暑，天上绝清凉。"]},{"t":"学士院端午帖子二十七首 皇太妃阁五首 其三","f":"七言绝句","c":["九夏清斋奉至尊，消除疠疫去无痕。","太医争献天师艾，瑞雾长萦尧母门。"]},{"t":"学士院端午帖子二十七首 皇太妃阁五首 其四","f":"七言绝句","c":["纨扇新裁冰雪馀，清风不隔纻罗疏。","飞升漫写秦公子，荣谢应怜汉婕妤。"]},{"t":"学士院端午帖子二十七首 皇太妃阁五首 其五","f":"七言绝句","c":["渺渺金河入禁垣，渐台雨过碧波翻。","共传太液龙舟稳，不似南方竞渡喧。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其一","f":"五言绝句","c":["溽暑避华构，清风迎早朝。","枫槐高自舞，冰雪晚初消。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其二","f":"五言绝句","c":["南讹初应历，五日未生阴。","灵药收农录，薰风拂舜琴。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其三","f":"五言绝句","c":["皇心本夷旷，一气自炎凉。","不废荆吴旧，民风见未央。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其四","f":"七言绝句","c":["九门已散秦医药，百辟初颁凌室冰。","饮食祈君千万寿，良辰更上辟兵缯。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其五","f":"七言绝句","c":["雨迟麦粒尤坚好，日丽蚕丝转细长。","入夏民间初解愠，宫中时举万年觞。"]},{"t":"学士院端午帖子二十七首 皇帝阁六首 其六","f":"七言绝句","c":["汴上初无招屈亭，沅湘近在国南坰。","太官漫解供新粽，谏列犹应记独醒。"]},{"t":"画叹","f":"七言绝句","c":["武燕未远嗟谁识，赵董纷纷枉得名。","已矣孙陈旧人物，至今但数汉公卿。"]},{"t":"画枕屏","f":"七言绝句","c":["绳床竹簟曲屏风，野水遥山雾雨濛。","长有滩头钓鱼叟，伴人闲卧寂寥中。"]},{"t":"雨中招吴子野先生","f":"七言绝句","c":["柴门不出蓬生径，暑雨无时水及堂。","辟谷赖君能作客，暂来煎蜜饷桃康。"]},{"t":"南斋竹三绝 其二","f":"七言绝句","c":["旧山修竹半尘埃，谁种南林待我来。","新笋出墙秋雨足，闭门长与护苍苔。"]},{"t":"南斋竹三绝 其一","f":"七言绝句","c":["幽居一室少尘缘，妻子相看意自闲。","行到南窗修竹下，恍然如见旧溪山。"]},{"t":"南斋竹三绝 其三","f":"七言绝句","c":["里中佳客旧孙陈，我自疏慵不见人。","目倦细书长掩卷，心游法界四无邻。"]},{"t":"将游金山寄元长老","f":"七言绝句","c":["粗砂施佛佛欣受，怪石供僧僧不嫌。","空手远来还要否，更无一物可增添。"]},{"t":"施君既去复以事还戏赠","f":"七言绝句","c":["令尹西行去又回，西湖重把旧樽罍。","吏民再见鸡栖乘，犹道吾公挽不来。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 其五 洛阳试院楼上新晴五绝","f":"七言绝句","c":["前朝宫阙倚芒山，殿阁层层半岭间。","犹恐北来冈阜浅，太行东抱故孱颜。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 其二 洛阳试院楼上新晴五绝","f":"七言绝句","c":["嵩少犹藏薄雾中，前山迤逦夕阳红。","高楼一闭三十日，遥忆岩头种药翁。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 其三 洛阳试院楼上新晴五绝","f":"七言绝句","c":["伊阙遥临凤阙前，龙门女几气苍然。","唐朝御路依稀在，犹想东巡尘暗天。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 其一 洛阳试院楼上新晴五绝","f":"七言绝句","c":["缥缈危谯面面山，朝来云作雨潺潺。","忽然风卷归何处，百里阴晴反掌间。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 其四 洛阳试院楼上新晴五绝","f":"七言绝句","c":["天坛王屋北侵河，高比嵩丘一倍多。","小有清灵今尚在，俗缘深重奈成魔。"]},{"t":"洪休上人少年读书以多病出家居泐潭为马祖修塔以三绝句来谒答一首","f":"七言绝句","c":["早除郎将少年狂，祖塔结缘归故乡。","习气未消馀业在，逢人依旧琢诗章。"]},{"t":"逊自淮康酒官归觐逾旬而归送行二绝句 其二","f":"七言绝句","c":["乘田委吏责无多，旧学年来竟若何。","开卷新诗可人意，到官无复废吟哦。"]},{"t":"逊自淮康酒官归觐逾旬而归送行二绝句 其一","f":"七言绝句","c":["官期未满许宁亲，平日宦游无此恩。","雨遍公田及私亩，学书兼得问筠孙。"]},{"t":"唐相二绝 其二","f":"七言绝句","c":["朝中寂寂少名卿，晚岁雄猜气益横。","心怕无须少年士，可怜未识玉奴兄。"]},{"t":"唐相二绝 其一","f":"七言绝句","c":["杨王灭后少英雄，犹自澄思却月中。","已得惠妃欢喜见，方头笑杀曲江公。"]},{"t":"留题石经院三首 其三","f":"五言绝句","c":["孤绝山南寺，僧居无限清。","不知行道处，空听暮钟声。"]},{"t":"留题石经院三首 其二","f":"五言绝句","c":["盘曲山前路，流年向此消。","兴亡须一吊，范叟卧山腰。"]},{"t":"留题石经院三首 其一","f":"五言绝句","c":["岧峣山上寺，近在古城中。","苦恨河流远，长教眼力穷。"]},{"t":"秦虢夫人走马图二绝 其二","f":"七言绝句","c":["朱幩玉勒控飞龙，笑语喧哗步骤同。","驰入九重人不见，金钿翠羽落泥中。"]},{"t":"读乐天集戏作五绝 其五","f":"七言绝句","c":["乐天种竹自成园，我亦墙阴数百竿。","不共伊家斗多少，也能不畏雪霜寒。"]},{"t":"读乐天集戏作五绝 其一","f":"七言绝句","c":["乐天梦得老相从，洛下诗流得二雄。","自笑索居朋友绝，偶然得句与谁同。"]},{"t":"读乐天集戏作五绝 其三","f":"七言绝句","c":["乐天投老刺杭苏，溪石胎禽载舳舻。","我昔不为二千石，四方异物固应无。"]},{"t":"读乐天集戏作五绝 其四","f":"七言绝句","c":["乐天引洛注池塘，画舫飞桥映绿杨。","潩水隔城来不得，不辞策杖看湖光。"]},{"t":"读乐天集戏作五绝 其二","f":"七言绝句","c":["乐天得法老凝师，后院犹存杨柳枝。","春尽絮飞馀一念，我今无累日无思。"]},{"t":"读史六首 其一","f":"五言绝句","c":["留侯决成败，面折愧周昌。","垂老召商叟，鸿鹄自高翔。"]},{"t":"读史六首 其三","f":"五言绝句","c":["贾生料吴楚，竟毙大梁城。","一身不自保，痛哭空伤生。"]},{"t":"逍遥堂会宿二首 其一","f":"七言绝句","c":["逍遥堂后千寻木，长送中宵风雨声。","误喜对床寻旧约，不知漂泊在彭城。"]},{"t":"逍遥堂会宿二首 其二","f":"七言绝句","c":["秋来东阁凉如水，客去山公醉似泥。","困卧北窗呼不起，风吹松竹雨凄凄。"]},{"t":"郭尉惠古镜","f":"七言绝句","c":["凛如秋月照虚空，遇水留形处处同。","一瞬自成千亿月，精神依旧满胸中。"]},{"t":"高邮别秦观三首 其二","f":"七言绝句","c":["笔端大字鸦栖壁，袖里清诗句琢冰。","送我扁舟六十里，不嫌罪垢污交朋。"]},{"t":"高邮别秦观三首 其三","f":"七言绝句","c":["高安此去风涛恶，犹有庐山得纵游。","便欲携君解船去，念君无罪去何求。"]},{"t":"乾荔支","f":"七言绝句","c":["含露迎风惜不尝，故将赤日损容光。","红消白瘦香犹在，想见当年十八娘。"]},{"t":"寄龙井辩才法师三绝 其三","f":"七言绝句","c":["井水中藏东海鱼，侧盆翻雨洗凡夫。","隔山欲共公相见，莫道从来一滴无。"]},{"t":"寄龙井辩才法师三绝 其一","f":"七言绝句","c":["我兄教我过东吴，遗墨山间无处无。","忽报冬潮催出堰，俗缘深重道心粗。"]},{"t":"寇莱公","f":"七言绝句","c":["人知公惠在巴东，不识三朝社稷功。","平日孤舟已何处，江亭依旧傍秋风。"]},{"t":"郿坞","f":"七言绝句","c":["董公平昔甚纵横，晚岁藏金欲避兵。","当日英雄智相似，燕南赵北亦为京。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 登封道中三绝 其三 少林寺赠顿起","f":"七言绝句","c":["一径乔林下黄叶，三山翠壁绕禅居。","共君将住还归去，欲问安心知已疏。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 登封道中三绝 其一 缑山祠","f":"七言绝句","c":["飞仙不返周王子，重阜相连少室孙。","夜静笙声兼鹤下，回看惟有故山存。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 登封道中三绝 其二 轩辕道","f":"七言绝句","c":["青山欲上疑无路，涧道相萦九十盘。","东望嵩高分草木，回瞻原隰涌波澜。"]},{"t":"登郡谯偶见姜应明司马醉归","f":"七言绝句","c":["苍然莫色映楼台，江市游人夜未回。","何处酒仙无一事，肩舆鼾睡过桥来。"]},{"t":"答吴和二绝 其二","f":"七言绝句","c":["惯从李叟游都市，久伴蓝翁醉画堂。","不似苏门但长啸，一生留恨与嵇康。"]},{"t":"答吴和二绝 其一","f":"七言绝句","c":["三间浰水小茅屋，不比麻田新草堂。","问我秋来气如火，此间何事得安康。"]},{"t":"腊月九日雪三绝句 其二","f":"七言绝句","c":["去年家酿不须沽，秫米今年绝市无。","雪没前山薇蕨尽，谁怜无语独携锄。"]},{"t":"腊月九日雪三绝句 其一","f":"七言绝句","c":["天公留雪待嘉平，飞霰来时晓未明。","病士拥衾催暖酒，闭门不听扫瑶琼。"]},{"t":"腊月九日雪三绝句 其三","f":"七言绝句","c":["腊中得雪春宜麦，瓮里无糟寒恼人。","未暇樽罍伴佳客，先将饼饵许比邻。"]},{"t":"韩干二马","f":"七言绝句","c":["玉带胡奴骑且牵，银騣白鼻两争先。","八坊龙种知何数，乞与岐邠并锦鞯。"]},{"t":"蜀人旧食决明花耳颍川夏秋少菜崇宁老僧教人并食其叶有乡人西归使为父老言之戏作","f":"七言绝句","c":["秋蔬旧采决明花，三嗅馨香每叹嗟。","西寺衲僧并食叶，因君说与故人家。"]},{"t":"题李十八黄龙寺画壁","f":"七言绝句","c":["胸次峥嵘落笔端，壁题留与老夫看。","枯槎尚倚春风力，苍竹从来自岁寒。"]},{"t":"题李公麟山庄图 发真坞","f":"五言绝句","c":["山开稍有路，水放亦成川。","游人得所息，真意方澹然。"]},{"t":"题李公麟山庄图 延华洞","f":"五言绝句","c":["共恨春不长，逡巡就摇落。","一见洞中天，真知世间恶。"]},{"t":"题李公麟山庄图 垂云沜","f":"五言绝句","c":["未见垂云沜，其如归兴何。","路穷双足热，为我洗磐陀。"]},{"t":"题李公麟山庄图 建德馆","f":"五言绝句","c":["龙眠渌净中，微吟作云雨。","幽人建德居，知是清风主。"]},{"t":"题李公麟山庄图 栖云室","f":"五言绝句","c":["石室空无主，浮云自去来。","人间春雨足，归意带风雷。"]},{"t":"题李公麟山庄图 鹊源","f":"五言绝句","c":["溪深龟鱼骄，石瘦椿楠劲。","借子木兰船，宽我芒鞋病。"]},{"t":"题李公麟山庄图 墨禅堂","f":"五言绝句","c":["此心初无住，每与物皆禅。","如何一丸墨，舒卷化山川。"]},{"t":"题李公麟山庄图 澄元谷","f":"五言绝句","c":["石门日不下，潭镜月长临。","细细溪风渡，相看识此心。"]},{"t":"赠石台问长老二绝 其一","f":"七言绝句","c":["法达曾经见老卢，半生勤苦一朝虚。","心通口诵方无碍，笑把吴鸾细字书。"]},{"t":"赠石台问长老二绝 其二","f":"七言绝句","c":["蒲团布衲一绳床，心地虚明睡自亡。","长伴空中月天子，东方行道到西方。"]},{"t":"蹇师嵩山图","f":"七言绝句","c":["峻极登高二十年，汝州回望一依然。","君行亦是高秋后，试觅神清古洞天。"]},{"t":"七十三岁作","f":"七言律诗","c":["一生有志恨无才，久尔萧萧白发催。","力学当年真自信，初心到此未应回。","旧人化去浑无几，新障重生拨不开。","七十三年还住否，获麟后事转难裁。"]},{"t":"七十吟","f":"七言律诗","c":["年来霜雪上人头，俄尔相将七十秋。","欲去天公未遣去，久留敝宅恐难留。","六窗渐暗犹牵物，一点微明更著油。","近听老卢亲下种，满田宿草费锄耰。"]},{"t":"七夕","f":"五言律诗","c":["火流知节换，秋到喜身安。","林鹊真安往，河桥晚未完。","得闲心不厌，求巧老应难。","送酒谁知我，瓢樽昨暮乾。"]},{"t":"九日三首 其一","f":"五言律诗","c":["九日真佳节，年年长赋诗。","深惭鹤发老，每与菊花期。","帽落无人拾，酒狂聊自持。","丰年馀社瓮，天意念衰羸。"]},{"t":"九日三首 其三","f":"五言律诗","c":["从古重此日，今人那得违。","菊迟知岁闰，酒贵念人饥。","身安且自慰，家远不成归。","尚忆少年乐，惊呼人尽非。"]},{"t":"九日三首 其一","f":"五言律诗","c":["早岁寡欢意，衰年仍病缠。","客居逢九日，斗酒破千钱。","萸菊惊秋晚，儿孙慰目前。","登高懒不出，多酌任颓然。"]},{"t":"九日三首 其一","f":"五言律诗","c":["瓢尊空挂壁，九日若为欢。","白发逃无计，黄花开已阑。","酒悭惭对客，风起任飘冠。","赖有陶翁伴，贫居得自宽。"]},{"t":"九日三首 其一","f":"五言律诗","c":["昔忝衣冠旧，今从野老游。","篱根菊初绽，瓮面酒新刍。","不负重阳节，都无举世忧。","人生定谁是，万事本悠悠。"]},{"t":"九日三首 其三","f":"五言律诗","c":["河朔今将到，山阳近欲行。","老怀惊聚散，一酌慰平生。","陋巷连墙久，长淮照眼明。","到官纷讼牒，应忆此时情。"]},{"t":"九日三首 其二","f":"五言律诗","c":["我饮不为酒，黄花竞此时。","茱萸谩辟恶，曲糵助和脾。","浅酌何劳诉，独醒徒尔为。","来年我犹健，相对亦如斯。"]},{"t":"九日三首 其二","f":"五言律诗","c":["欲就九日饮，旋炊三斗醅。","今朝不一醉，坐客有空回。","白发何须吝，黄花恨晚开。","问知瓶未罄，相劝尽馀杯。"]},{"t":"九日三首 其二","f":"五言律诗","c":["解衣换村酒，酒薄不须嫌。","节到勿空过，杯行且强拈。","得闲身尚健，适意事难兼。","醉卧南窗日，谁知酸与甜。"]},{"t":"九日三首 其二","f":"五言律诗","c":["狂夫老无赖，见逐便忘归。","小酌还成醉，侨居不觉非。","妻孥应念我，风雨未缝衣。","忧患十年足，何时赋式微。"]},{"t":"九日三首 其三","f":"五言律诗","c":["黄菊与秋竞，白须随日添。","时人知不憙，野老未相嫌。","但酌清樽尽，犹存薄俸沾。","日西闻客至，更问酒家帘。"]},{"t":"九日阴雨不止病中把酒示诸子三首 其三","f":"五言律诗","c":["庭菊兼黄白，村醪杂圣贤。","微吟还自喜，不饮信徒然。","陶亮贫非病，孟嘉醒亦颠。","相看莫相笑，与尔各当年。"]},{"t":"九日阴雨不止病中把酒示诸子三首 其二","f":"五言律诗","c":["九日不能饮，呦呦觉胃寒。","妻孥劝把盏，萸菊正堆槃。","懒极久成病，年高终鲜欢。","道人嫌服药，心息自相安。"]},{"t":"九日阴雨不止病中把酒示诸子三首 其一","f":"七言律诗","c":["旱久翻成雾雨灾，老人腹疾强衔杯。","官醅菉豆适初熟，篱菊黄花终未开。","儿女共怜佳节过，鸡豚恐有故人来。","衰年此会真馀几，薄酒无多不用推。"]},{"t":"九日独酌三首 其三","f":"七言律诗","c":["平昔交游今几人，后生谁复款吾门。","茅檐适性轻华屋，黍酒忘形敌上樽。","东圃旋移花百本，西轩恨斫竹千根。","舍南赖有凌云柏，父老经过说二孙。"]},{"t":"九日独酌三首 其二","f":"七言律诗","c":["故国忘归懒问人，新居斫竹旋开门。","菊生墙下不知节，酒滴床头初满樽。","涨水骤来真有浪，浮云卷去自无根。","凡心漫作颍滨传，留与他年好事孙。"]},{"t":"九日独酌三首 其一","f":"七言律诗","c":["府县嫌吾旧党人，乡邻畏我昔黄门。","终年闭户已三岁，九日无人共一樽。","白酒近令沽野店，黄花旋遣折篱根。","老妻也说无生话，独酌油然对子孙。"]},{"t":"九月十一日书事","f":"七言律诗","c":["东墙瘦菊早开花，九日金钿已自嘉。","黍麦候迟初响瓮，米盐法细未还家。","泼醅昨夜惊泉涌，洗盏今晨听妇誇。","归采茱萸重一醉，不须怪问日时差。"]},{"t":"十一月一日作","f":"七言律诗","c":["昼短图书看不了，夜长鼓角睡难堪。","老怀骚屑谁为伴，心地空虚成妄谈。","酒少不妨邻叟共，病多赖有衲僧谙。","积阴深厚阳初复，一点灵光勤自参。"]},{"t":"十日二首 其二","f":"七言律诗","c":["忧患经怀沃漏卮，荣华过眼脱轻衣。","定心稍觉无来往，时事谁能问是非。","禄去身安常自喜，宅成囊竭可无讥。","交游散尽馀亲戚，酒熟时来一叩扉。"]},{"t":"十日二首 其一","f":"七言律诗","c":["酒经重九尚残卮，雨送初寒问箧衣。","养气安闲真得计，读书勤苦已知非。","谩存讲说传家学，深谢交游绝世讥。","筑室未成中自笑，何如茅屋对柴扉。"]},{"t":"十月二十九日雪四首 其四","f":"七言律诗","c":["鹞子一飞超涨海，蜂儿终日透晴窗。","心空莫著书千卷，客到长留酒半缸。","性命早知元有分，文章谁信旧无双。","何年结束寻归路，还看蟆颐下饮江。"]},{"t":"十月二十九日雪四首 其三","f":"七言律诗","c":["幽居漫尔存三径，燕坐何妨应六窗。","老忆旧书时展卷，病封药酒旋开缸。","小园摇落黄花尽，古桧飞鸣白鹤双。","珍重老卢留种子，养生不复问王江。"]},{"t":"十月二十九日雪四首 其二","f":"七言律诗","c":["龛灯照室久妨睡，雪气侵人不隔窗。","枕上诗成那起草，槽头酒滴暗鸣缸。","远来狂客应回去，高卧幽人未有双。","犹忆新滩泊船处，堆蓬积玉撼长江。"]},{"t":"十月二十九日雪四首 其一","f":"七言律诗","c":["床头唧唧糟鸣瓮，夜半萧萧雪打窗。","拥褐旋惊花著树，泼醅初喜酒盈缸。","邻翁晨乞米三斗，钓户暮留鱼一双。","自笑有无今粗足，遥怜逐客过重江。"]},{"t":"卜居","f":"七言律诗","c":["我归万里初无宅，凤去千年尚有台。","谁为绕池先种竹，可怜当砌已栽梅。","囊资只数腰金在，归计长遭鬓雪催。","欲就草堂终岁事，落成邻舍许衔杯。"]},{"t":"又次韵游小云居","f":"七言律诗","c":["溪上浮花片片轻，溯流登岸得山行。","僧房幽绝云居小，春日阴晴野色明。","永远林栖真有道，溺沮耕养亦忘情。","此身此意何年遂，空使常谈笑老生。"]},{"t":"上巳日久病不出示儿侄二首 其二","f":"七言律诗","c":["卧闻诸子到西湖，鹄鹭翩翩众客俱。","纨扇藤鞋试轻駃，只鸡斗酒助欢娱。","行歌久已饶渠辈，睡美犹应属老夫。","春服既成沂可浴，孔门世不乏迂儒。"]},{"t":"上巳日久病不出示儿侄二首 其一","f":"七言律诗","c":["春气侵脾久在床，开门桃李著泥香。","牛鸣颇觉西湖近，凤去长怜北榭荒。","欲出老人无伴侣，退归诸子解农桑。","南邻约卖千竿竹，拄杖穿林看笋长。"]},{"t":"上元","f":"七言律诗","c":["上元车马正喧喧，老病无聊长掩门。","不著繁灯眩双目，独邀明月上前轩。","跏趺默坐闻三鼓，寂寞谁来共一樽。","已觉城中尘土臭，急将清雨洗乾坤。"]},{"t":"上元不出","f":"七言律诗","c":["春寒未脱紫貂裘，灯火催人夜出游。","老厌歌钟空命酒，病嫌风露怯登楼。","拥袍坐睡曾无念，结客追欢久已休。","试问西邻传法老，此时情味似侬不。"]},{"t":"上元后一日观灯寄王四","f":"七言律诗","c":["城头月减一分圆，城里人家万炬然。","紫陌群游逢酒住，红裙醉舞向人妍。","且为行乐终今夕，共道重来便隔年。","遥想猖狂夜深处，河沙飞水湿归鞯。"]},{"t":"上元夜","f":"五言律诗","c":["新春收积雨，明月澹微云。","照水疏灯出，因风远乐闻。","天涯仍有节，人事竟何分。","卖酒真拘束，何时一醉醺。"]},{"t":"上元夜适劝至西禅观灯","f":"七言律诗","c":["三年不踏门前路，今夜仍看屋里灯。","照佛有馀长自照，澄心无法便成澄。","追欢狂客去忘返，入定孤僧唤不应。","更到西禅何所问，隔墙鱼鼓正登登。"]},{"t":"上元雪","f":"七言律诗","c":["上元灯火家家办，遍地琼瑶夜夜深。","衲被蒙头真老病，纱笼照佛本无心。","床头酒瓮恰三斗，山下麦田真百金。","乞我终年醉且饱，端能拥鼻作微吟。"]},{"t":"久不作诗呈王适","f":"七言律诗","c":["怜君多病仍经暑，笑我微官长坐曹。","落日东轩谈不足，秋风北棹意空劳。","懒将词赋占挂臆，频梦江湖把蟹螯。","笔砚生尘空度日，他年何用继《离骚》。"]},{"t":"亡伯母同安县君杨氏挽词","f":"五言律诗","c":["德盛诸杨族，贤宜伯父家。","周姜职蘋藻，歜母事桑麻。","大邑移封近，阴堂去日赊。","空馀镜奁在，时出旧笄珈。"]},{"t":"亡嫂靖安君蒲氏挽词二首 其二","f":"五言律诗","c":["宦游非不遂，流落自粗疏。","宗党半天末，存亡惊素书。","佳城东岭外，茂木故阡馀。","遥想千车送，临江涕满裾。"]},{"t":"亡嫂靖安君蒲氏挽词二首 其一","f":"五言律诗","c":["家风足图史，妇德俨蘋蘩。","汤沐从夫宠，冠衣席弟恩。","克家传众子，有后庆多孙。","追养心何极，增封礼尚存。"]},{"t":"大行太皇太后挽词二首 其二","f":"五言律诗","c":["约己心全小，宽民德有馀。","外家恩泽少，先后礼容虚。","原庙因前室，中朝避册书。","功名不胜纪，四谥叹犹疏。"]},{"t":"大行太皇太后挽词二首 其一","f":"五言律诗","c":["内治隆三世，尊临极九年。","神孙克负荷，大业付安全。","有道华夷靖，无心怨恶悛。","和熹盛东汉，从此不称贤。"]},{"t":"大行皇太后挽词二首 其二","f":"五言律诗","c":["家风承旧相，国体继皇姑。","定策从中禁，传声震海隅。","春风开闭蛰，朝露湿焦枯。","万里生还客，冠缨泪雨濡。"]},{"t":"大行皇太后挽词二首 其一","f":"五言律诗","c":["累朝宗内治，晚岁擅鸿勋。","立子得元圣，收帘奉长君。","一言消横逆，多难弭纷纭。","仙驭曾非远，长瞻巩洛云。"]},{"t":"子瞻见许骊山澄泥砚","f":"七言律诗","c":["长安新砚石同坚，不待书求遂许颁。","岂必魏人胜近世，强推铜雀没骊山。","寒煤舒卷开云叶，清露沾流发涕潸。","早与封题寄书案，报君湘竹笔身班。"]},{"t":"子瞻喜雨亭北隋仁寿宫中怪石","f":"七言律诗","c":["仁寿宫中稆谷生，太湖苍石草间横。","兴衰换世身犹在，南北从人事已轻。","累石作台秋藓上，凿汧通水细渠清。","三年此亦非公有，空使他年记姓名。"]},{"t":"小雪","f":"七言律诗","c":["小雪仅能消膈热，苦寒偏解恼衰翁。","年丰谁使百物贵，心净要令万事空。","老去禅功深自觉，生来滞运与人同。","闲中未断生灵念，清夜焚香处处通。"]},{"t":"山胡","f":"五言律诗","c":["山胡拥苍毳，两耳白茸茸。","野树啼终日，黔山深几重。","啄溪探细石，噪虎上孤峰。","被执应多恨，筠笼仅不容。"]},{"t":"己丑除日二首 其二","f":"七言律诗","c":["橘红安稳近谁传，鬓雪萧骚久已然。","梅柳任教修故事，蚕丝聊与祝新年。","敲门贺客辞多病，守岁诸孙听不眠。","粗有官酤供夜饮，一瓶浑浊且称贤。"]},{"t":"己丑除日二首 其一","f":"七言律诗","c":["阅遍时人身亦老，卷残旧历意茫然。","髭须白尽无添处，甲子重来又十年。","酒俭不容时一醉，堂成且喜夜安眠。","春秋似是平生事，屋壁深藏付后贤。"]},{"t":"不到东西二林","f":"五言律诗","c":["山北东西寺，高人永远师。","来游亦前定，回首独移时。","社散白莲尽，山空玄鹤悲。","何年陶靖节，溪上送行迟。"]},{"t":"中秋无月同诸子二首 其二","f":"五言律诗","c":["捲衣换斗酒，欲饮月明中。","坐看浮云合，遥怜四海同。","清光知未泯，来岁尚无穷。","且尽樽中渌，高眠听雨风。"]},{"t":"中秋无月同诸子二首 其一","f":"五言律诗","c":["风雨来无定，泥涂日向深。","直埋今夜月，真失众人心。","云外天衢净，人间浊雾侵。","幽人久不寐，起坐夜愔愔。"]},{"t":"中秋新堂看月戏作","f":"七言律诗","c":["年年看月茅檐下，今岁堂成月正圆。","自笑吾人强分别，不应此月倍婵娟。","虚窗每怯高风度，碧瓦频惊急雨悬。","七十老翁浑未惯，安居始觉贵公贤。"]},{"t":"予初到筠即于酒务庭中种竹四丛杉二本及今三年二物皆茂秋八月洗竹培杉偶赋短篇呈同官","f":"七言律诗","c":["种竹成丛杉出檐，三年慰我病厌厌。","剪除乱叶风初好，封植孤根笋自添。","高节不知尘土辱，坚姿试待雪霜沾。","属君留取障斜日，仍记当年此滞淹。"]},{"t":"予昔在京师画工韩若拙为予写真今十三年矣容貌日衰展卷茫然叶县杨生画不减韩复令作之以记其变偶作","f":"七言律诗","c":["白发苍颜日日新，丹青犹是旧来身。","百年迅速何曾住，方寸空虚老更真。","一幅萧条寄衰朽，异时仿佛见精神。","近存八十一章注，从道老聃门下人。"]},{"t":"五月一日同子瞻转对","f":"七言律诗","c":["羸病不堪金束腰，永怀江海旧渔樵。","对床贪听连宵雨，奏事惊同朔旦朝。","大耿功名元自异，中茅服食旧相要。","一封同上怜狂直，诏许昌言赖有尧。"]},{"t":"元绛参政挽词","f":"七言律诗","c":["吴越朝天功在民，当年卿相亦仁人。","曾孙终与元丰政，故老犹知异代因。","吏治清明开白日，文词俊发吐青春。","邺都从事堂中客，涕洒高原柏子新。"]},{"t":"劝子瞻修无生法","f":"七言律诗","c":["除却灵明一一空，年来丹灶漫施功。","掌中定有庵摩在，云际悬知雾雨濛。","已赖信心留掣电，要须净戒拂昏铜。","谁言逐客江南岸，身世虽穷心不穷。"]},{"t":"午寝","f":"七言律诗","c":["食饱年来幸有秋，倒床清梦百无忧。","忍饥终愧首阳客，睡足何须云梦州。","冰酒黄封生不喜，春芽紫笋向谁求。","平生尚有书魔在，一卷还堪作枕头。"]},{"t":"壬辰生日儿侄诸孙有诗所言皆过记胸中所怀亦自作","f":"五言律诗","c":["生日今朝是，匆匆又一年。","读书真已矣，闭目但茫然。","下种言非妄，开花果定圆。","驱羊旧有法，视后直须鞭。"]},{"t":"孔平仲著作江州官舍小庵","f":"七言律诗","c":["近山不作看山计，引水新成照水庵。","闭口忘言中自饱，安心度日更谁参。","简编围绕穿书蠹，窗户低回作茧蚕。","我亦一轩容膝住，敝裘粗饭有馀甘。"]},{"t":"孔君亮郎中新葺阙里西园弃官而归","f":"七言律诗","c":["宦情牢落苦思归，君侧无人留子思。","手种松筠须灌溉，亲修寝庙忆烝祠。","定应此去添桃李，还似旧茔无棘茨。","他日东游访遗烈，因公导我谒先师。"]},{"t":"开窗","f":"五言律诗","c":["绿竹琅玕色，红葵旌节花。","开窗风细细，窥户月斜斜。","活计无多子，文章自一家。","一床方病卧，随意上三车。"]},{"t":"文氏外孙入村收麦","f":"七言律诗","c":["欲收新麦继陈谷，赖有诸孙替老人。","三夜阴霪败场圃，一竿晴日舞比邻。","急炊大饼偿饥乏，多博村酤劳苦辛。","闭廪归来真了事，赋诗怜汝足精神。"]},{"t":"木山引水二首 其一","f":"七言律诗","c":["引水穿墙接竹梢，谷藏峰底大容瓢。","将流旋滴庐山瀑，已尽还来海上潮。","乱点落池惊睡觉，半山含润沃心焦。","瓦盆一斛何胜满，溢去犹能浸菊苗。"]},{"t":"木山引水二首 其二","f":"七言律诗","c":["檐下枯槎拂荻梢，山川迤逦费公瓢。","幽泉细细流岩鼻，盆水瀰瀰涨海潮。","但爱坚如湖上石，谁怜收自灶中焦。","苍崖寒溜须佳荫，尚少冬青石茧苗。"]},{"t":"王子立与迟等游陈家园桥败几不成行晚自酒务往见之明日雨作偶尔成咏","f":"七言律诗","c":["桃李城东近不遥，偶闻花发喜相邀。","断桥似欲妨佳思，好雨犹能借此朝。","随分开樽依绿草，偶然信马及馀瓢。","重来莫道无闲暇，紫燕黄鹂日渐娇。"]},{"t":"王子难龙图挽词","f":"七言律诗","c":["帝子乘鸾已列仙，遗芳留得众孙贤。","俊科蚤与寒儒竞，禁从终偿白发年。","辇路联镳惊往事，圃田回首泣新阡。","旧闻推历知天命，看熟黄粱定洒然。"]},{"t":"王仲仪尚书挽词","f":"七言律诗","c":["谢公德业久弥新，幼度英奇也绝伦。","父子俱贤真不朽，功名自致岂相因。","边兵屡动思良将，廷论萧条忆诤臣。","青史世家它日事，新阡宿草倍沾巾。"]},{"t":"王度支陶挽词二首 其一","f":"五言律诗","c":["风迹殊不昧，声名岂偶然。","长途催騄骥，爽气激鹰鹯。","薏苡成遗恨，松楸卜远年。","凄凉故吏尽，谁泣鬣封前。"]},{"t":"王度支陶挽词二首 其二","f":"五言律诗","c":["京尘昔倾盖，江国见佳城。","零落旧冠剑，艰难孝弟兄。","存亡看世俗，意气忆平生。","晓铎知人恨，幽音亦未平。"]},{"t":"车浮","f":"七言律诗","c":["寒鱼得汕便为家，两两方舟载小车。","谋食旋遭芳饵误，求安仍值积薪遮。","情存未免人先得，欲尽要令物莫加。","身似虚舟任千里，世间何处有罦罝。"]},{"t":"冬日即事","f":"七言律诗","c":["寒日初加一线长，腊醅添浸隔罗光。","新年只愿多新酒，旧疾微令变旧方。","自昔杯棬元窄小，得闲筋力尚康强。","买田种秫贫无计，自有人家为插秧。"]},{"t":"冬至日","f":"七言律诗","c":["阴阳升降自相催，齿发谁教老不回。","犹有髻珠常照物，坐看心火冷成灰。","酥煎陇坂经年在，柑摘吴江半月来。","官冷无因得官酒，老妻微笑泼新醅。"]},{"t":"冬至雪二首 其二","f":"七言律诗","c":["佳节萧条陋巷中，雪穿窗户有颜风。","出迎过客知非病，归对先师喜屡空。","黍酝盈瓢终寡味，石薪烘灶信奇功。","颇嫌半夜欺毛褐，却喜年来麦定丰。"]},{"t":"冬至雪二首 其一","f":"七言律诗","c":["一气潜萌九地中，雪花微落四无风。","初阳便有回天力，宿瘴徐看卷地空。","家酿再投犹恨薄，官酤多取定无功。","时人浅陋终无益，径就天公借一丰。"]},{"t":"召伯埭上斗野亭","f":"五言律诗","c":["细雨添春色，微风净闸流。","徂年半今世，生计一扁舟。","饮食随鱼蟹，封疆入斗牛。","江波方在眼，转觉此生浮。"]},{"t":"司马温公挽词四首 其一","f":"五言律诗","c":["白发三朝旧，青山一布衾。","封章留帝所，德泽在人心。","未起讴吟切，来归顾托深。","杨公不久住，天意定难忱。"]},{"t":"司马温公挽词四首 其二","f":"五言律诗","c":["决策传贤际，危言变法初。","纷纷看往事，一一验遗书。","富贵终何有，清贫只自如。","西州不忍过，行哭便回车。"]},{"t":"司马温公挽词四首 其三","f":"五言律诗","c":["区区非为己，恳恳欲忘生。","力尽心终在，身亡势亦成。","遗民抛剑戟，故老半公卿。","魏丙生前友，俱传汉相名。"]},{"t":"司马温公挽词四首 其四","f":"五言律诗","c":["少年真狷浅，射策本粗疏。","欲广忠言地，先收众弃馀。","流离见更化，邂逅捧除书。","赵孟终知厥，他人恐骂予。"]},{"t":"外孙文骥与可学士之孙也予亲教之学作诗俊发犹有家风喜其不坠作诗赠之","f":"五言律诗","c":["已矣石室老，奄然三十年。","遗孙生不识，妙理定谁传。","孔伋仍闻道，贾嘉终象贤。","文章犹细事，风节记高坚。"]},{"t":"戊子正旦","f":"七言律诗","c":["百岁行来已七分，筋骸转觉不如人。","法传心地初投种，雨过花开不待春。","识路一时如有得，到家诸事本非新。","旧陈刍狗今无用，付与时人藉两轮。"]},{"t":"正月十六日","f":"七言律诗","c":["上元已过欲收灯，城郭游人一倍增。","陌上红尘霏似雾，云间明月冷如冰。","谁言世上驱驰客，老作庵中寂定僧。","漏水半消灯火冷，长空无滓色澄澄。"]},{"t":"生日","f":"七言律诗","c":["扶杖今年见国人，悬弧早岁忆兹晨。","佛身三世归依地，邻寺百僧清净因。","蘧子知非惭已晚，白公起定惜馀春。","舞雩一濯平湖水，乡党惊呼白发新。"]},{"t":"甲子日雨","f":"七言律诗","c":["一冬无雪麦方病，细雨迎春岁有望。","愁见积阴连甲子，复令父老念耕桑。","瘦田未足终年计，浊酒谁供清旦尝。","赖有真人不饥渴，闭门却扫但焚香。"]},{"t":"白菊","f":"七言律诗","c":["白菊长先黄菊开，年年九日泛新醅。","犹存古历摽花候，不奈时人信手栽。","得势从教盈九畹，俯眉聊复引三杯。","愈风明目须真物，能使神农为尔回。"]},{"t":"白鹇","f":"五言律诗","c":["白鹇形似鸽，摇曳尾能长。","寂寞怀溪水，低回爱稻粱。","田家比鸡鹜，野食荐杯觞。","肯信朱门里，徘徊占玉塘。"]},{"t":"石盆种菖蒲甚茂忽开八九华或言此华寿祥也远因生日作颂亦为赋此","f":"七言律诗","c":["石盆攒石养菖蒲，沮洳沙泉韭叶铺。","世说华开难值遇，天将寿考报勤劬。","心中本有长生药，根底暗添无限须。","更尔屈蟠增瘦硬，他年老病要相扶。"]},{"t":"石鼻城","f":"七言律诗","c":["千山欲尽垂为鼻，百战皆空但有城。","虎闯穴中秦地恐，龙飞渭上汉江倾。","雍人未有章邯怨，魏将犹存仲达精。","睥睨陵迟春草满，白羊无数向风鸣。"]},{"t":"示诸子","f":"五言律诗","c":["诸子才不恶，功名旧有言。","穷愁念父母，心力尽田园。","志在要须命，身闲且养源。","游鱼脱渊水，何处有飞翻。"]},{"t":"示诸子","f":"七言律诗","c":["老去惟堪一味闲，坐令诸子了生缘。","般柴运水皆行道，挟策读书那废田。","兄弟躬耕真尽力，乡邻不惯枉称贤。","裕人约己吾家世，到此相承累百年。"]},{"t":"示诸孙","f":"五言律诗","c":["少年真力学，玄月闭书帷。","老去浑无赖，心空自不知。","交游谁识面，文字略存诗。","笑向诸孙说，疏慵非汝师。"]},{"t":"立秋后","f":"七言律诗","c":["伏中苦热焦皮骨，秋后清风濯肺肝。","天地不仁谁念尔，身心无著偶能安。","诗书久为消磨日，毛褐还须准拟寒。","谩许百年知到否，相从一日且盘桓。"]},{"t":"立秋偶作","f":"七言律诗","c":["十年忧患本谁知，惭愧仙翁有旧期。","度岭还家天许我，斸山种粟我尤谁。","秋风欲践故人约，春气潜通病树滋。","心似死灰须似雪，眼看多事亦奚为。"]},{"t":"仲夏始雷","f":"七言律诗","c":["阳气溟濛九地来，经春涉夏始闻雷。","麦禾此去或可望，桃李向来谁使开。","号令迍邅人共怪，阴阳颠倒物应猜。","一声震荡虽惊耳，遍地妖氛未易回。"]},{"t":"兴州新开古东池","f":"七言律诗","c":["山绕兴州万叠青，池开近郭百泉并。","昔年种柳人安在，累岁开花藕自生。","波暖跳鱼闻乐喜，人来野鸭望船鸣。","西还过此须终日，为问使君行未行。"]},{"t":"再次前韵四首 其一","f":"七言律诗","c":["城头栋宇恰三间，楚望凄凉吊屈原。","雨洗山川百里净，风吹语笑一城喧。","乡书莫问经时绝，岁事初惊片叶翻。","南近清淮鲈鳜好，钓筒时问有潜吞。"]},{"t":"再次前韵四首 其二","f":"七言律诗","c":["谬将疏野托交游，平日论心亦有由。","科第联翩叨旧契，利名疏阔少新忧。","清谈已觉忘朱夏，浊酒先防虐素秋。","多病无聊唯有睡，频频诗句未嫌不。"]},{"t":"再次前韵四首 其三","f":"七言律诗","c":["野鹤应疑凫雁苦，夏虫未惯雪霜寒。","隐居颜氏终安巷，垂钓严生自有滩。","破宅不归尘可扫，下田初种水应漫。","退耕尚作悠悠语，拙宦犹须步步看。"]},{"t":"再次前韵四首 其四","f":"七言律诗","c":["欲作彭城数月留，溪山劝我暂忘忧。","城头准拟中秋望，台上迁延九日游。","岚气雨馀侵近郭，江声风送隐危楼。","汀洲聚散知谁怪，且学漂浮水上鸥。"]},{"t":"再和二首 其一","f":"七言律诗","c":["病起江南力未匀，强将冠剑拂埃尘。","木鸡自笑真无用，刍狗何劳收已陈。","行从銮旗风日细，侧听庙乐管弦新。","谁知四载勤劳后，并举成功祚泣辛。"]},{"t":"再和二首 其二","f":"七言律诗","c":["宸心恻恻念污莱，南籞西池闭不开。","长乐鸣鞘千乘出，顾成荐鬯万方来。","从臣暗泣新宫柳，父老行依辇路槐。","双阙影斜朱户启，都人留看属车回。"]},{"t":"再和三首 其一","f":"七言律诗","c":["穴鼠何须窭数衔，粗官不用苦高谈。","夜倾绿蚁风吹竹，昼拥黄紬雪覆庵。","每作微词还自笑，偶渐馀润亦成酣。","公诗精绝非伦拟，自古骚人尽在南。"]},{"t":"再和三首 其二","f":"七言律诗","c":["燕窠泥土一春衔，惭愧封侯止立谈。","旧隐尚闻存竹径，归休但要葺茅庵。","钓船梦想沿溪泛，酒盏遥思向日酣。","强欲迟留依幕府，吴公行恐召河南。"]},{"t":"再和三首 其三","f":"七言律诗","c":["天教穷困欲谁衔，生事那须一一谈。","自笑丰年尘满甑，不堪雨后菌生庵。","士师憔悴经三黜，陶令幽忧付一酣。","他日归耕若相忆，尺书频寄北山南。"]},{"t":"再游庐山三首 其一","f":"七言律诗","c":["当年五月访庐山，山翠溪声寝食间。","藤杖复随春色到，寒泉顿与客心闲。","岩头悬布煎茶足，峡口惊雷泛叶悭。","待得前村新雨遍，扁舟应逐好风还。"]},{"t":"再游庐山三首 其二","f":"七言律诗","c":["忆自栖贤夜入城，道边兰若一僧迎。","偶然不到终遗恨，特地来游慰昔情。","海外声闻安至此，堂中天鼓为谁鸣。","匆匆复向深山去，一盏醍醐饱粟罂。"]},{"t":"再游庐山三首 其三","f":"七言律诗","c":["此山岩谷不知重，赤眼浮图自一峰。","芒蹻随僧践黄叶，晓光消雪堕长松。","石泉试饮先师锡，午饭归寻下寺钟。","胜处转多浑恐忘，出山惟见白云浓。"]},{"t":"同迟赋千叶牡丹","f":"七言律诗","c":["未换中庭三尺土，漫种数丛千叶花。","造物不违遗老意，一枝颇似洛人家。","名园不放寻芳客，陋巷希闻载酒车。","未忍画瓶修佛供，清樽酌尽试山茶。"]},{"t":"同迟赋春晚","f":"七言律诗","c":["池塘春旱欲生尘，一雨能令草木新。","脾病不嫌樱笋薄，廪空偏喜麦禾匀。","白须照水湖光净，渌酒留人鸟哢频。","但恐少年嫌老丑，眼前无复一时人。"]},{"t":"同陈述古舍人观芍药","f":"七言律诗","c":["蔼蔼堂西十亩园，晚凉迎步绿阴繁。","共惊春去已多日，争看花开最后番。","未许狂风催烂熳，故将青幄强安存。","请公作意勤欢赏，趁取残红照酒樽。"]},{"t":"后省初成直宿呈子瞻二首 其二","f":"七言律诗","c":["射策当年偶一时，对床夜雨失前期。","庐间还往无多地，梦里追寻亦自疑。","螭墨屡乾朝已久，囊封希上出犹迟。","茅檐半破松筠老，归念萧然欲语谁。"]},{"t":"后省初成直宿呈子瞻二首 其一","f":"七言律诗","c":["掖垣初罢斧斤响，栋宇犹闻松桂香。","江海暂来俱野客，云霄并直愧华堂。","月明似与人烟远，风细微闻禁漏长。","谏草未成眠未稳，始知天上极清凉。"]},{"t":"回寄圣寿聪老","f":"七言律诗","c":["五年依止白莲社，百度追寻丈室游。","睡待磨茶长展转，病蒙煎药久迟留。","赞公夜宿诗仍作，巽老堂成记许求。","回首万缘俱一梦，故应此物未沉浮。"]},{"t":"守岁","f":"七言律诗","c":["岁云莫矣谁能守，唯有此心初不移。","宇宙随流任尔去，虚空对面即吾师。","三杯醉倒聊从俗，一点灵明欲语谁。","来日日新无限事，归根一笑彼安知。"]},{"t":"岁莫二首 其二","f":"七言律诗","c":["文章习气消未尽，般若初心老渐明。","粗有春秋传旧学，终凭止观定无生。","维摩晚亦谐生事，弥勒初犹重世名。","须发来年应更白，莫留尘滓溷澄清。"]},{"t":"岁莫二首 其一","f":"七言律诗","c":["岭南万里归来客，颍上六年多病身。","未死谁言犹有命，长闲岂复更尤人。","眼看世事知难了，手注遗编近一新。","点检平生无几恨，浊醪初熟正逢春。"]},{"t":"戏次前韵寄王巩二首 其一","f":"七言律诗","c":["白马貂裘锦羃䍦，离觞潋滟手亲持。","头风欲待歌词愈，肺病甘从酒力欺。","不分归心太匆草，更怜人事苦萦縻。","相逢借问空长叹，便舍灵龟看朵颐。"]},{"t":"戏次前韵寄王巩二首 其二","f":"七言律诗","c":["细竹寒花出短䍦，故山耕耒手曾持。","宦游暂比凫鹥集，归计长遭句偻欺。","歌舞梦回空历记，友朋飞去自难縻。","悠悠后会须经岁，冉冉霜髭渐满颐。"]},{"t":"成都僧法舟为其祖师宝月求塔铭于惠州还过高安送归","f":"七言律诗","c":["少年能讲大乘经，法施堂中不出扃。","为许先师传后世，径从西海集南溟。","忘身直犯黄茅瘴，满意初成白塔铭。","寄我泪痕归万里，遥知露滴涧松青。"]},{"t":"扬州五咏 其二 平山堂","f":"七言律诗","c":["堂上平看江上山，晴光千里对凭栏。","海门仅可一二数，云梦犹吞八九宽。","檐外小棠阴蔽芾，壁间遗墨涕汍澜。","人亡坐使风流尽，遗构仍须子细观。"]},{"t":"扬州五咏 其三 蜀井","f":"七言律诗","c":["信脚东游十二年，甘泉香稻忆归田。","行逢蜀井恍如梦，试煮山茶意自便。","短绠不收容盥濯，红泥仍许置清鲜。","早知乡味胜为客，游宦何须更着鞭。"]},{"t":"扬州五咏 其一 九曲池","f":"七言律诗","c":["嵇老清弹怨广陵，隋家水调继哀音。","可怜九曲遗声尽，惟有一池春水深。","凤阙萧条荒草外，龙舟想像绿杨阴。","都人似有兴亡恨，每到残春一度寻。"]},{"t":"扬州五咏 其五 僧伽塔","f":"七言律诗","c":["山头孤塔閟真人，云是僧伽第二身。","处处金钱追晚供，家家蚕麦保新春。","欲求世外无心地，一扫胸中累劫尘。","方丈近闻延老宿，清朝留客语逡巡。"]},{"t":"扬州五咏 其四 摘星亭","f":"七言律诗","c":["阙角孤高特地迷，迷藏浑忘日东西。","江流入海情无限，莫雨连山醉似泥。","梦里兴亡应未觉，后来愁思独难齐。","只堪留作游观地，看遍峰峦处处低。"]},{"t":"杀麦二首 其二","f":"五言律诗","c":["雨后麦多病，庾中蛾欲飞。","不辞终日暑，幸脱半年饥。","潦水来何暴，秋田望已微。","农夫愚可念，此报定谁非。"]},{"t":"次王适韵送张耒赴寿安尉二首 其一","f":"七言律诗","c":["绿发惊秋半欲黄，官居无处觅林塘。","浮生已是尘劳侣，病眼犹便锦绣章。","羞见故人梁苑废，梦寻归路蜀山长。","怜君顾我情依旧，竹性萧疏未受霜。"]},{"t":"次王适韵送张耒赴寿安尉二首 其二","f":"七言律诗","c":["魏红深浅配姚黄，洛水家家自作塘。","游客贾生多感概，闲官白傅足篇章。","山分少室云烟老，宫废连昌草木长。","路出蒿高应少驻，孱颜新过一番霜。"]},{"t":"次迟韵千叶牡丹二首 其二","f":"七言律诗","c":["老人无力年年懒，世事如花种种新。","百巧从来知是妄，一机何处定非真。","园夫漫接曾无种，物化相乘岂有神。","毕竟春风不拣择，随开随落自匀匀。"]},{"t":"次迟韵千叶牡丹二首 其一","f":"七言律诗","c":["潩上名园似洛滨，花头种种斗尖新。","共传青帝开金屋，欲遣姚黄比玉真。","秦岭犹应篆诗句，杜鹃直恐降天神。","老人发少花头重，起舞攲斜酒力匀。"]},{"t":"次前韵","f":"五言律诗","c":["闭门何所事，毛发日青青。","齿折登山屐，尘生贳酒瓶。","调心开贝叶，救病读《难经》。","定起无人见，寒灯一点星。"]},{"t":"次前韵示杨明二首 其二","f":"五言律诗","c":["甘井元依庙，平湖亦近城。","幅巾朝食罢，芒屩雨中行。","扰扰初何事，悠悠毕此生。","欲邀东郭叟，烦子作郊迎。"]},{"t":"次前韵示杨明二首 其一","f":"五言律诗","c":["晚岁有馀乐，天教一向闲。","嵩阳百口住，岭外七年还。","卜宅先邻晏，携瓢欲饮颜。","吴僧来不久，相约叩禅关。"]},{"t":"次韵子瞻二月十日雪","f":"七言律诗","c":["春雪漫天密又稀，勾芒失据走灵威。","故欺贫窭冬裘尽，巧助遨游酒盏飞。","林下细花添百草，阶前轻素剪新机。","老农先解忧桑柘，九月家人当授衣。"]},{"t":"次韵子瞻十一月旦日锁院赐酒及烛","f":"七言律诗","c":["铜镮玉锁闭空堂，腕脱初惊笔札忙。","红烛遥怜风雪暗，黄封微泻桂椒香。","光明坐觉幽阴破，温暖深知覆育长。","明日白麻传好语，曼声微绕殿中央。"]},{"t":"次韵子瞻与安节夜坐三首 其一","f":"七言律诗","c":["前山积雪暮峥嵘，燕坐微闻落瓦声。","共对一尊通夜语，相看万里故乡情。","信归岭上寒梅远，恨极江南春草生。","明日青铜添白发，且须醉睡倒灯檠。"]},{"t":"次韵子瞻与安节夜坐三首 其二","f":"七言律诗","c":["少年高论苦峥嵘，老学寒蝉不复声。","目断家山空记路，手披禅册渐忘情。","功名久已知前错，婚嫁犹须毕此生。","家世读书难便废，漫留案上铁灯檠。"]},{"t":"次韵子瞻与安节夜坐三首 其三","f":"七言律诗","c":["谪官似我无归计，落第怜渠有屈声。","握手天涯同一笑，倚门岁晚不胜情。","黄冈俯仰成陈迹，白首蹉跎畏后生。","归去且安南巷乐，莫看歌舞醉长檠。"]},{"t":"次韵子瞻太白山下早行题崇寿院","f":"五言律诗","c":["山下晨光晚，林梢露滴升。","峰头斜见月，野市早明灯。","树暗犹藏鹊，堂开已馔僧。","据鞍应梦我，联骑昔尝曾。"]},{"t":"次韵子瞻延生观后山上小堂","f":"七言律诗","c":["谢公游意未能厌，踏尽登山屐齿尖。","古殿神仙深杳杳，香炉烟翠起纤纤。","岩花寂历飘琼片，庭桧萧疏漏玉蟾。","帝子莫归人不见，微风细雨自开帘。"]},{"t":"次韵子瞻有美堂夜归","f":"七言律诗","c":["饮阑钟虡欲移轩，香雾犹残金博山。","明月飞来松岭外，游人散落马蹄间。","城严画鼓初传角，路暗山花自落鬟。","清境暂时都不见，夜深人尽始来还。"]},{"t":"次韵子瞻初出颍口见淮山","f":"七言律诗","c":["清淮此日见沧浪，始觉南来道路长。","窗转山光时隐见，船知水力故轩昂。","白鱼受钓收寒玉，红稻堆场列远冈。","波浪连天东近海，乘桴直恐渐茫茫。"]},{"t":"次韵子瞻寿州城东龙潭","f":"七言律诗","c":["东行取次阅三州，击鼓清晨复解舟。","车骑纷纭追过客，歌钟凄咽动潜虬。","宦游底处非巢燕，归计何嫌诮沐猴。","赖有故人怜远适，慇勤屡劝酒行周。"]},{"t":"次韵子瞻杜介供奉送鱼","f":"七言律诗","c":["天街雪霁初通驷，禁籞冰开渐跃鱼。","十尾烦君穿细柳，一杯劝我芼青蔬。","寒樽独酌偶逢客，佳句相酬不用书。","江海归来叨禁近，空令同巷往来疏。"]},{"t":"次韵子瞻连雨江涨二首 其二","f":"七言律诗","c":["客到炎陬喜暂凉，江吹虚阁雨侵廊。","回看野寺山溪隔，卧觉晨炊稻饭香。","荔饷深红陋樱枣，桂醅淳白比琳琅。","思移峤北应非晚，未省南迁日月长。"]},{"t":"次韵子瞻连雨江涨二首 其一","f":"七言律诗","c":["南过庾岭更千山，烝润由来共一天。","云塞虚空雨翻瓮，江侵城市屋浮船。","东郊晚稻须重插，西舍原蚕未及眠。","独棹扁舟趁申卯，米盐奔走笑当年。"]},{"t":"次韵子瞻饮道者院池上","f":"五言律诗","c":["雨气凉侵殿，河流渗入池。","黄粱瀹鱼子，白酒泻鹅儿。","风细初生袖，尘清免污眉。","郊行不易得，拂壁看题诗。"]},{"t":"次韵子瞻夜坐","f":"七言律诗","c":["月入虚窗疑欲旦，香凝幽室久犹薰。","清风巧为吹馀瘴，疏雨时来报断云。","南海炎凉身已惯，北方毁誉耳谁闻。","遥知挂壁瓢无酒，归舶还将一酌分。"]},{"t":"次韵子瞻招王蘧朝请晚饮","f":"七言律诗","c":["矫矫公孙才不贫，白驹冲雪喜新春。","忽过银阙迷归路，误认瑶台寻故人。","访我不嫌泥正滑，留君深愧酒非醇。","归时九陌铺寒月，清绝空教仆御颦。"]},{"t":"次韵子瞻祈雨","f":"七言律诗","c":["世故纷纷谁复闲，蛟龙不雨独安眠。","人间已厌三秋旱，涧底犹悭一掬泉。","庙令酒肴时醉饱，田家糠秕久安便。","忧心未已谁知恤，更把炉香试一燃。"]},{"t":"次韵子瞻雨中督役夜宿水陆寺二首 其一","f":"七言律诗","c":["云气连山雨泻盆，莫投僧舍欲关门。","暂时洒扫宽行役，终夕崎岖入梦魂。","烦热暗消秋簟冷，烝濡未解夜灯昏。","二年游宦多劳苦，何日相从得细论。"]},{"t":"次韵子瞻雨中督役夜宿水陆寺二首 其二","f":"七言律诗","c":["野寺萧条厌客喧，雨披修竹乱纷然。","已因无食聊从仕，深悟劳生不问禅。","未至莫忧明日事，偷闲且就此宵眠。","天明归去芒鞋滑，虽有藤舆懒上肩。"]},{"t":"次韵子瞻南溪微雪","f":"七言律诗","c":["南溪夜雪晓来霁，有客晨游酒未消。","风泛馀花来逐马，光浮断涧不知桥。","山寒冻合行人息，醉熟宾欢舞意嚣。","归骑相将踏瑶玉，嗅林闲认早梅条。"]},{"t":"次韵子瞻相送使胡","f":"七言律诗","c":["朔雪胡沙试此身，青罗便面紫狐巾。","拥旃代北随飞雁，顿足江东有卧麟。","欺酒壶冰将送腊，照溪梅萼定先春。","汉家五饵今方验，更愧当年叹息人。"]},{"t":"次韵子瞻闻不赴商幕三首 其三","f":"七言律诗","c":["埙动篪鸣只自知，忧轻责少幸官卑。","声名谩作耳中瑱，科第空收颔底髭。","西鄙猖狂犹将将，中朝闲暇自师师。","近成新论无人语，仰羡飞鸿两翅差。"]},{"t":"次韵子瞻闻不赴商幕三首 其二","f":"七言律诗","c":["南商西洛曾虚署，长吏居民怪不来。","妄语自知当见弃，远人未信本非才。","厌从贫李嘲东阁，懒学谀张缓两腮。","知有四翁遗迹在，山中岂信少人哉。"]},{"t":"次韵子瞻闻不赴商幕三首 其一","f":"七言律诗","c":["怪我辞官免入商，才疏深畏忝周行。","学从社稷非源本，近读诗书识短长。","东舍久居如旧宅，春蔬新种似吾乡。","闭门已学龟头缩，避谤仍兼雉尾藏。"]},{"t":"次韵子瞻病中游虎跑泉僧舍二首 其一","f":"七言律诗","c":["扫地开门松桧香，僧家长夏亦清凉。","公庭多事久来厌，净处安眠计甚长。","修竹填窗藤簟绿，白莲当户石盆方。","香厨晚饭红粳熟，忽忆烹鸡田舍尝。"]},{"t":"次韵子瞻病中游虎跑泉僧舍二首 其二","f":"七言律诗","c":["涧谷新晴草木香，野情萧散自生凉。","雨添山色翠将溜，日转松阴晚更长。","病客独来唯有睡，游僧相见亦它方。","还家烦热都消尽，不信医王与药尝。"]},{"t":"次韵子瞻寄眉守黎希声","f":"七言律诗","c":["眼看狂澜倒百川，孤根漂荡水无边。","思家松菊荒三径，回首讴歌沸二天。","簿领沉迷催我老，春秋废格累公贤。","邻居屈指今谁在，一念伤心十五年。"]},{"t":"次韵子瞻游富阳普照寺","f":"五言律诗","c":["尘埃日已远，斗薮更无馀。","寺到逢门入，诗成信手书。","山深僧自乐，路远客终疏。","访尽前朝景，它年一告予。"]},{"t":"次韵子瞻赋雪二首 其二","f":"七言律诗","c":["点缀偏工乱鹄鸦，淹留欲解恼船车。","乘春已觉矜馀力，骋巧时能作细花。","僵雁堕鸱谁得罪，败墙破壁若为家。","天公爱物遥怜汝，应是门前守夜叉。"]},{"t":"次韵子瞻新城道中","f":"七言律诗","c":["春深溪路少人行，时听田间耒耜声。","饥就野农分饷黍，迎嫌尉卒闹金钲。","闲花开尽香仍在，白酒沽来压未清。","此味暂时犹觉胜，问兄何日便归耕。"]},{"t":"次韵子瞻题长安王氏中隐堂五首 其一","f":"五言律诗","c":["秦中胜岷蜀，故国不须归。","甲第春风满，巴山昼梦非。","竹深啼鸟乱，花落晚蜂飞。","我欲西还去，敲门慎勿违。"]},{"t":"次韵子瞻题长安王氏中隐堂五首 其二","f":"五言律诗","c":["唐朝卿相宅，此外更应无。","请看庭前树，曾攀屋里姝。","流传渐失实，遗老不禁徂。","试问归登物，林间翠石孤。"]},{"t":"次韵子瞻题长安王氏中隐堂五首 其三","f":"五言律诗","c":["爱君高堂上，有似蜀江壖。","墙外终南近，檐西太白偏。","晚梅晴自媚，老竹暗相迁。","未到遥闻说，吾庐安得然。"]},{"t":"次韵子瞻题长安王氏中隐堂五首 其四","f":"五言律诗","c":["官去空留鹤，山浮不见鳌。","竹林迎日净，槐木拥亭高。","乌噪知人至，蝉鸣觉口劳。","谁能饮堂上，解带不穿袍。"]},{"t":"次韵子瞻题长安王氏中隐堂五首 其五","f":"五言律诗","c":["君看原上墓，坟尽但馀碑。","谁见生前贵，尘生带下龟。","高堂幸有酒，一饮岂论赀。","勉强行乐耳，古人良可悲。"]},{"t":"次韵子瞻题仙游潭中兴寺","f":"七言律诗","c":["潭边沙水不成泥，潭上孤禽挂崄啼。","缭绕飞桥能试客，蒙茸翠蔓巧藏溪。","云为绛帐马融室，石作屏风玉女闺。","仙果知君今未足，临潭脚战怕长梯。"]},{"t":"次韵子瞻题扶风道中天花寺小亭","f":"五言律诗","c":["客车来不息，辙迹知成沟。","莫怪慵登寺，犹宜赏举头。","独游知忆弟，望远胜登楼。","处处题诗遍，篇篇谁为收。"]},{"t":"次韵子瞻题泗州监仓东轩二首 其一","f":"七言律诗","c":["肩舆袅袅渡浮梁，吏隐知君寄一仓。","十里遥看飞皂盖，小轩相对有壶浆。","清霄往往投车辖，永日霏霏散篆香。","留滞淮南久仍乐，莫年何意复为郎。"]},{"t":"次韵子瞻题泗州监仓东轩二首 其二","f":"七言律诗","c":["万斛尘飞日为霾，无心退食自成斋。","梅生红粟初迎腊，鱼跃银刀正出淮。","卧病空看帆度碛，诵诗犹记雪填阶。","夹河南北俱形胜，且借高城作两崖。"]},{"t":"次韵子瞻赠张憨子","f":"七言律诗","c":["得罪南来正坐言，道人闭口意深全。","天游本自有真乐，羿彀谁知定不贤。","构火暾暾初吐日，飞流滚滚旋成川。","此心此去如灰冷，肯更逢人问复然。"]},{"t":"次韵广州陈绎谏议和陈荐宋敏求二龙图二首 其二 和彦升赴上醴泉","f":"七言律诗","c":["琳宫清净思悠哉，颇似山林未肯回。","五日趋朝真自适，一樽无事得频开。","董狐执笔何时易，马援征蛮未遽来。","奔走安闲谁定是，都门携手一徘徊。"]},{"t":"次韵广州陈绎谏议和陈荐宋敏求二龙图二首 其一 和彦升寓定力","f":"七言律诗","c":["曾送飞龙白日翔，未应中路许还乡。","鹤归仍有当年伴，松老知经几度霜。","城下宝坊聊寄榻，朝中振鹭旧成行。","相逢出处何须问，五岭清平十月凉。"]},{"t":"次韵门下刘侍郎直宿寄苏左丞","f":"七言律诗","c":["雷雨连年起卧龙，穆然台阁有清风。","一时画诺虽云旧，此日都俞本自公。","松竹经霜俱不改，盐梅共鼎固非同。","一篇和遍东西府，六律更成十二宫。"]},{"t":"次韵门下吕相公车驾视学","f":"七言律诗","c":["未识吾君龙凤章，诸儒望幸久南庠。","辇回原庙初移跸，鹭集西雍已著行。","执爵稍前疑问道，献琛不日数来王。","从官始悟熙宁意，遗我亲临见肯堂。"]},{"t":"次韵门下吕相公同访致政冯宣猷","f":"七言律诗","c":["懒从朝谒事骖騑，此去高眠罢倒衣。","诏许敲门访耆旧，天教筑室俟来归。","肩舆尚肯追春色，鼓缶何妨傲夕晖。","所至成家即安隐，武昌谁乞钓鱼矶。"]},{"t":"次韵仇池冬至日见寄","f":"七言律诗","c":["身如草木顺阴阳，附火重裘百日强。","渐喜微和解凝烈，半酣起舞意仓忙。","吾兄去我行三腊，千里今宵共一觞。","世事只今人自解，苦寒须尽酒如汤。"]},{"t":"次韵孔武仲到官后见寄","f":"五言律诗","c":["举楫同千里，系舟时一言。","共嗟蓬作屋，愿就席为门。","行役身先困，征商思益昏。","仅同登垄断，何止服车辕。"]},{"t":"次韵毛君九日","f":"七言律诗","c":["山脚侵城尽是台，登高处处喜崔嵬。","手拈霜菊香无奈，面拂江风酒自开。","幕府尊罍云里集，民家歌吹静中来。","定知胜却陶彭泽，怅望篱边白日颓。"]},{"t":"次韵毛君上书求归未报","f":"七言律诗","c":["白发忧民带减围，频闻慷慨赋将归。","近传道士连三咽，久悟禅门第一机。","夜永庵中诗自得，日高门外客来稀。","此心素定谁能劝，祗有丁宁诏莫违。"]},{"t":"次韵毛君见赠","f":"七言律诗","c":["江国骚人不耐秋，夜吟清句晓相投。","锋藏岂愿囊中脱，尾断终非俎上羞。","择地何年真得意，餔糟是处可同游。","南迁尚有公知我，人事何须更预谋。"]},{"t":"次韵毛君经旬不用鞭扑","f":"七言律诗","c":["共喜秋深酒未醇，官曹休假不须旬。","政宽境内棠阴合，讼去庭中草色新。","不惜牛刀时一割，已因鼷鼠发千钧。","岁终谁为公书考，岂止江西第一人。"]},{"t":"次韵毛君将归","f":"七言律诗","c":["疏傅思归不待时，孟轲出昼苦行迟。","新诗尚许留章句，故事谁从问典彝。","金马尚应堪避世，石泉未信可忘饥。","不才似我真当去，零落衡茅隔雍岐。"]},{"t":"次韵毛君留别","f":"七言律诗","c":["问天乞得不訾身，屈指人间今几人。","鱼纵江潭真窟宅，鹤飞松岭倍精神。","清风吹雨停归骑，旧圃留花送晚春。","自号白云知有意，便从丹灶拂埃尘。"]},{"t":"次韵毛君病中菊未开","f":"七言律诗","c":["病肺秋深雾雨伤，旧缯故絮喜清凉。","菊花金粟未曾吐，桂酒鹅儿空自黄。","草木亦知年有闰，风霜渐近月方阳。","得诗闻道维摩病，欲到毗耶言已忘。"]},{"t":"次韵毛君偶成","f":"七言律诗","c":["年来衰病正相兼，薄宦奔驰尚未厌。","诗句空多浑漫兴，俗缘已重不须添。","聱牙向物知难合，疏懒怜公独未嫌。","时听渊明咏归去，犹应为我故迟淹。"]},{"t":"次韵毛君清居探菊","f":"七言律诗","c":["眼前黄叶畏秋霜，耳畔啼蛩怨夜长。","佳节欣闻近萸菊，清商试为奏伊凉。","疏狂久笑谋生拙，贫病应怜为口忙。","今日共君拚一醉，从教人道亦高阳。"]},{"t":"次韵毛君游陈氏园","f":"七言律诗","c":["增筑园亭草木新，损花风雨怨频频。","筼筜似欲迎初暑，芍药犹堪送晚春。","薄暮出城仍有伴，携壶藉草更无巡。","归轩有喜知谁见，道上从横满醉人。"]},{"t":"次韵毛君感事书怀","f":"七言律诗","c":["种棠经岁便成科，秋雨调匀气渐和。","才力有馀嫌事少，风情无限觉诗多。","长松更老仍添节，古井虽深自不波。","宴坐山房人岂识，一尊聊且慰蹉跎。"]},{"t":"次韵王巩九日同送刘莘老","f":"七言律诗","c":["头上黄花记别时，樽中渌酒慰清悲。","画船牵挽故不发，红粉留连未遽离。","小雨无端添别泪，遥山有意助颦眉。","十分酒盏从教劝，堆案文书自此辞。"]},{"t":"次韵王巩见寄","f":"七言律诗","c":["池上轻冰暖却开，迎春送腊仰衔杯。","君家有酒能无事，客醉连宵遣不回。","诗就滴消盘上蜡，信来飘尽岭头梅。","商丘冷坐君知否，瓶罄应须有耻罍。"]},{"t":"次韵王巩见寄","f":"七言律诗","c":["日永官闲自在慵，门前客到未曾通。","怜君避世都门里，劝我忘忧酒盏中。","城下柳阴新过雨，湖边荷叶自翻风。","早须命驾追清赏，大字新诗事事工。"]},{"t":"次韵王巩见寄","f":"七言律诗","c":["触事如棋一一低，昏然一睡更何知。","贾生流落南迁后，陶令衰迟归去时。","去住由人真水母，箪瓢粗足亦山雌。","年来未省谈尧舜，一吷粗疏岂足吹。"]},{"t":"次韵王巩代书","f":"七言律诗","c":["去年河上送君时，我醉看君倒接篱。","一笑便成经岁隔，扁舟重到满城知。","旧传北海偏怜客，新怪东方苦诉饥。","应笑长安居不易，空吟原上草离离。"]},{"t":"次韵王巩同饮王廷老度支家戏咏","f":"七言律诗","c":["白鱼紫蟹早霜前，有酒何须问圣贤。","上客远来工缓颊，双鬟为出小垂肩。","新传大曲皆精绝，忽发狂言亦可怜。","莫怪贫家少还往，自须先办买花钱。"]},{"t":"次韵王巩廷评招饮","f":"七言律诗","c":["病忆故乡同越舄，性安田野似裨谌。","都城岁晚不归去，客舍夜寒犹独吟。","樽酒怜君偏好客，诗篇寄我谬知音。","会须雪里相从饮，履迹旋平无处寻。"]},{"t":"次韵王巩怀刘莘老","f":"七言律诗","c":["两都来往太频频，真是人间自在人。","十载读书同白屋，千金为客买朱唇。","结交京邑倾心肺，寓思禅宗离垢尘。","为问西归天禄客，何时同看洛川神。"]},{"t":"次韵王巩留别","f":"七言律诗","c":["决策归田岂世情，网罗从此脱馀生。","请君速治鸡黍具，待我同为沮溺耕。","秋社相从醵钱饮，日高时作叩门声。","茅庐但恐非君处，籍籍朝中望已倾。"]},{"t":"次韵王巩欲往徐州见子瞻以事不成行","f":"七言律诗","c":["河水南来绕郡城，银刀空复衒衙兵。","交情旧许鸡为具，客信那知鹊妄鸣。","为妇迟留应未怪，还家仓卒定何营。","不关秦女筝声怨，自趁招贤浚上旌。"]},{"t":"次韵王巩游北禅","f":"七言律诗","c":["萧萧黄叶下城头，顿作野田风日秋。","粗有樽罍随处好，暂无敲扑便能幽。","人稀野鸟应同乐，水涸游鱼似欲愁。","客去知君欢未已，绕城携手更迟留。"]},{"t":"次韵王君北都偶成三首 其三","f":"五言律诗","c":["禁籞封金殿，清河贯石门。","时平馀古木，兵散有空屯。","形胜山围阔，蕃宣海内尊。","川原不论顷，云梦可胜吞。"]},{"t":"次韵王君北都偶成三首 其一","f":"五言律诗","c":["河转金堤近，天高魏阙新。","千夫奉儒将，百兽伏麒麟。","校猎沙场莫，谈兵玉帐春。","关南知不远，谁试问蕃邻。"]},{"t":"次韵王君北都偶成三首 其二","f":"五言律诗","c":["天宝乱已定，河壖兵更多。","故城埋白骨，遗俗喜长戈。","卧兽常思肉，奔鲸不受罗。","纵横竟安在，唯见冢嵯峨。"]},{"t":"次韵王君贶尚书会六同年","f":"七言律诗","c":["有美佳宾贤主人，布衣曾共脱京尘。","欢来未觉岁华晚，醉后能令秋气春。","发誉早同初宦日，收功终藉老成身。","他年此会应图画，传入谁家屏障新。"]},{"t":"次韵王定民宣德","f":"七言律诗","c":["彭城寺壁看诗来，颜氏瓢樽偶共开。","茅屋未完先凿沼，竹林成后想宜梅。","新诗妙绝难为继，高论微低得共陪。","第一词人生不识，兹行尚喜揖君才。"]},{"t":"次韵王定国见赠","f":"七言律诗","c":["枯木无枝不记年，寒灰谁遣强吹然。","南迁不折知非妄，未老求閒愈觉贤。","屡出诗章新管籥，偶开画卷小山川。","簿书填委惭君甚，拨去归来粗了眠。"]},{"t":"次韵王临太博马上","f":"五言律诗","c":["冬晚霜露重，城遥鞍马劳。","徒知事奔走，曾未补毫毛。","水旱嗟嚬蹙，疮痍费抑搔。","莫归何暇食，堆桉簿书高。"]},{"t":"次韵王荐推官见寄","f":"七言律诗","c":["可怜衰病孰为媒，私喜邻邦得俊才。","玉案愧无酬锦绣，木瓜却用报琼瑰。","风流似欲传诸谢，格律犹应学老梅。","始信山川出才士，扁舟新自宛溪来。"]},{"t":"次韵王适上元夜二首 其一","f":"七言律诗","c":["灯光欲凝不惊风，月色初晴若发蒙。","羁客不眠诗未就，游人半醉夜方中。","荒城熠耀相明灭，野水芙蓉乱白红。","知欲访僧同寂寂，应怜病懒畏爞爞。"]},{"t":"次韵王适上元夜二首 其二","f":"七言律诗","c":["宿雨初乾试火城，端居无计伴游行。","厌看门外繁星动，想见僧窗一点明。","老罢逢春无乐事，梦回孤枕有乡情。","重因佳句思樊口，一纸家书百镒轻。"]},{"t":"次韵王适州学新修水阁","f":"七言律诗","c":["黄钟巨挺两舂容，何幸幽居近学宫。","坐对江山增浩气，力追齐鲁欲同风。","颂诗闻道求何武，家法行看试左雄。","欲伴少年游矍相，奔军惭愧恐词穷。"]},{"t":"次韵王适春雨","f":"七言律诗","c":["久遭客禁往还稀，风雨萧条只自知。","春色有情犹入眼，客愁无赖巧侵眉。","山僧寄语收茶日，野老留人供社时。","久住不须嫌寂寞，此间偏与拙相宜。"]},{"t":"次韵王适春雪二首 其一","f":"七言律诗","c":["江南春候寒犹剧，细雨风吹作雪花。","中夜窗扉初晃漾，平明草木半低斜。","润催江柳排金绿，光杂山茶点绛葩。","老病不堪乘晓出，纷纷能使发增华。"]},{"t":"次韵王适食茅栗","f":"七言律诗","c":["相从万里试南餐，对案长思苜蓿盘。","山栗满篮兼白黑，村醪入口半甜酸。","久闻牛尾何曾试，窃比鸡头意未安。","故国霜蓬如碗大，夜来弹剑似冯驩。"]},{"t":"次韵王适留别","f":"七言律诗","c":["远谪劳君两度行，复将文字试平衡。","干时岂为斗升禄，闻道应忘宠辱惊。","未了新书谁与读，重留佳句不胜情。","决科事毕知君喜，俗学消磨意自清。"]},{"t":"次韵王适梅花","f":"七言律诗","c":["江梅似欲竞新年，照水窥林态愈妍。","霜重清香浑欲滴，月明素质自生烟。","未成细实酸犹薄，半落南枝意可怜。","谁写江西风物样，徐家旧有数枝传。"]},{"t":"次韵王适游陈氏园","f":"七言律诗","c":["宿雨晴来春已晚，众花飘尽野犹香。","舞雩便可同沂上，饮禊何妨似洛阳。","新圃近闻穿沼阔，涨江初喜放舟长。","年来簿领萦人甚，何计相随入醉乡。"]},{"t":"次韵王钦臣秘监集英殿井","f":"五言律诗","c":["碧甃涵云液，铜瓶响玉除。","汲花攒点罢，洒雾唤班初。","龙饼煎无数，螭研滴有馀。","从官方醉饱，一酌解清虚。"]},{"t":"次韵发运路昌衡淮南见山堂","f":"七言律诗","c":["叠石初成得赐环，未应苔藓上苍颜。","据鞍华岳旌旄里，回首淮山梦想间。","烽火日传西塞静，丘陵应伴壮心闲。","终南太白皆公有，肯向庭中更作山。"]},{"t":"次韵任遵圣见寄","f":"七言律诗","c":["故国老成谁复先，壮心空记语当年。","灌夫失意贫无友，梅福辞官晚作仙。","诗句清新非世俗，退居安稳卜江天。","它年我亦从君隐，多买黄鱼煮复煎。"]},{"t":"次韵光庭省中书事","f":"七言律诗","c":["放浪江湖久惰慵，安排谁置从官中。","粗疏空与延和对，开纳初还贞观风。","二鄙兵消真帝力，四方雨足自天功。","时将一勺倾沧海，漫使人知达四聪。"]},{"t":"次韵刘贡父从驾","f":"七言律诗","c":["一经空记弟传兄，旧德终惭比长卿。","扈驾联翩来接武，登科先后忆题名。","竹林共集连诸子，棣萼相辉赖友生。","它日都门俱引去，不应广受独华荣。"]},{"t":"次韵刘贡父西掖种竹","f":"七言律诗","c":["竹迷谁定知迷否，趁取滂沱好雨初。","栽向凤池吹律处，斸从芸阁杀青馀。","迎风一啸朝回早，弄月相差直宿疏。","应怪籍咸林下客，相看不饮作除书。"]},{"t":"次韵刘贡父省上示同会二首 其一","f":"七言律诗","c":["流落江湖东复西，归来未洗足间泥。","偶随鹏翼培风上，时得衙香满袖携。","落笔逡巡看儤直，醉吟清绝许分题。","相望鲁卫虽兄弟，终畏邻封大国齐。"]},{"t":"次韵刘贡父省上示同会二首 其二","f":"七言律诗","c":["掖垣不复限东西，宾客来冲雾雨泥。","白酒黄封开潋滟，朱樱青笼落提携。","五花愧我连书判，三道高君免试题。","谁遣松蒿同一谷，凌云他日恐难齐。"]},{"t":"次韵刘贡父省中独直","f":"七言律诗","c":["帘深巧为隔朝暾，竹密时能引雀喧。","朝罢宿酲还续梦，静中诸妄稍归根。","坐曹闻道仍分省，出沐谁当与比轩。","竹簟茅檐它日事，重因遗咏记君恩。"]},{"t":"次韵刘敏殿丞送春","f":"七言律诗","c":["春去堂堂不复追，空馀草木弄晴晖。","交游归雁行将尽，踪迹鸣鸠懒不飞。","老大未须惊节物，醉狂兼得避危机。","东风虽有经旬在，芳意从今日日非。"]},{"t":"次韵孙户曹朴柳湖","f":"七言律诗","c":["疏慵非敢独违时，野性颠狂不受羁。","犹有曲湖容笑傲，谁言与物苦参差。","水乾生草曾非恶，鹤舞因风忽自怡。","最爱柳阴迟日暖，幅巾轻屦肯相随。"]},{"t":"次韵孙推官朴见寄二首 其二","f":"七言律诗","c":["病懒近来全废学，宦游唯是苦思乡。","粗知会计犹堪仕，贪就功名有底忙。","怀旧暗听秋雁过，梦归偏爱晓更长。","故人知我今何念，拟向东山赋首章。"]},{"t":"次韵朱光庭司谏喜雨","f":"五言律诗","c":["焦枯连夏火，洗濯待秋霖。","都邑沟渠净，郊原黍豆深。","流膏侵地轴，晴意动风琴。","谁似臣居易，先成喜雨箴。"]},{"t":"次韵讲律李司理宪见赠","f":"七言律诗","c":["强将羔雁聘黄晞，破褐疏巾倚夕晖。","礼律纵横开卷尽，齑盐冷落待贤非。","日高几案弦歌罢，夜永窗扉灯火微。","犹喜江边莫春近，舞雩风雨得同归。"]},{"t":"次韵吴兴李行中秀才见寄并求醉眠亭诗二首 其一 和见寄","f":"七言律诗","c":["才堪簿领更无馀，赢得十年闲读书。","宠辱何须身自试，穷愁不待酒驱除。","故人归去无消息，佳句新来屡卷舒。","前日使君今在此，不妨时复置双鱼。"]},{"t":"次韵吴兴李行中秀才见寄并求醉眠亭诗二首 其二 醉眠亭","f":"七言律诗","c":["是非一醉了无馀，唯有胸中万卷书。","已把人生比蘧传，更将江浦作阶除。","欲眠宾客从教去，倒卧氍毹岂暇舒。","京洛旧游真梦里，秋风无复忆鲈鱼。"]},{"t":"次韵吴厚秀才见寄","f":"七言律诗","c":["壮心摧折渐无馀，早岁为文老不如。","登木求鱼知我拙，循窠觅兔笑君疏。","清尊独酌夜方半，白发潜生岁欲除。","久恐交亲还往绝，床头犹喜数行书。"]},{"t":"次韵吴厚秀才见赠三首 其一","f":"七言律诗","c":["骚人思苦骨岩岩，百里携诗相就谈。","故作微词挑迁客，不嫌春雨湿归衫。","少年旧喜登高赋，老病今成见敌惭。","问我近来谁复可，对君聊拟诵《周南》。"]},{"t":"次韵吴厚秀才见赠三首 其二","f":"七言律诗","c":["久欲归田计未成，羡君负郭足为生。","躬耕不用千钟禄，高卧谁知万里征。","已觉安闲真乐事，可怜辛苦尽浮名。","隐居便作江南计，为觅佳山早寄声。"]},{"t":"次韵吴厚秀才见赠三首 其三","f":"七言律诗","c":["一卷新诗锦一端，掉头吟讽识芳酸。","哀歌永夜悲牛角，朗咏扁舟笑杏坛。","间发笙簧犹可拟，弃捐斤斧定知难。","继君高韵君应笑，咀嚼归途久据鞍。"]},{"t":"次韵宋构朝请归守彭城","f":"七言律诗","c":["得郡迎亲愿不违，书来无复寄当归。","马驰未觉西南远，乌哺何辞日夜飞。","湖水欲平官舍好，茶征初复讼氓稀。","平反闻道加餐饭，五裤应须换破衣。"]},{"t":"次韵张去华院中感怀","f":"七言律诗","c":["登朝已老似王阳，脱叶何堪雾雨凉。","案上细书憎蚁黑，禁中新酒爱鹅黄。","临阶野菊偏能瘦，倚槛青松解许长。","仕宦不由天禄阁，坐曹终日漫皇皇。"]},{"t":"次韵张问给事喜雨","f":"七言律诗","c":["已收蚕麦无多日，旋喜山川同一云。","禾黍趁时青覆垄，池塘流润渌生文。","两宫尚废清晨集，中禁初消永夜薰。","仓粟半空民望足，深耕疾耨肯忘君。"]},{"t":"次韵张君病起二首 其一","f":"七言律诗","c":["壮年得疾势能支，不废霜螯左手持。","渐喜一杯留好客，未应五斗似当时。","口中舌在时闻句，雪里心安不问师。","去卧淮阳从病守，功名他日许君期。"]},{"t":"次韵张君病起二首 其二","f":"七言律诗","c":["老去生经废不行，镜中白发见空惊。","解将冲气通枯指，易甚新阳发旧茎。","一悟少年难久恃，不妨多病却长生。","文章缪忝追前辈，服食从来亦强名。"]},{"t":"次韵张昌言给事省中直宿","f":"七言律诗","c":["还家未暇拂尘衣，携被重来趁落晖。","省户鸣驺久分散，宫槐栖鹊共翻飞。","周庐见月风霾静，斜汉横空星斗稀。","多病心身怯清禁，故山依约梦西归。"]},{"t":"次韵张恕九日寄子瞻","f":"七言律诗","c":["无限黄花簇短篱，浊醪霜蟹正堪持。","坐曹漫尔誇勤瘁，割肉何妨诮诋欺。","世外樽罍终自放，俗间簿领莫相縻。","茱萸插遍知人少，谈笑须公一解颐。"]},{"t":"次韵张恕春莫","f":"七言律诗","c":["祇言城市无佳处，亦有南湖几度游。","好雨晴时三月尽，啼莺到后百花休。","老猿好饮常连臂，野马依人自络头。","不肯低回池上醉，试看生灭水中沤。"]},{"t":"次韵李公择九日见约以疾不赴","f":"五言律诗","c":["它年逢九日，杯酒逐英豪。","渐老经秋病，独醒何处高。","床头添药裹，坐上减牛毛。","寂寞知谁问，烦公置浊醪。"]},{"t":"次韵李公择寄子瞻","f":"七言律诗","c":["青蒲一下复东来，拥扇西风满面埃。","击柝自营何择地，餔糟同醉未须回。","孤高振鹭瞻初下，淡泊婴儿及未孩。","我亦漂流家万里，年来羞上望乡台。"]},{"t":"次韵李抚辰屯田修州门","f":"七言律诗","c":["六月江涛壁垒颓，苍崖翠甓就新台。","咄嗟双阙还依旧，咫尺群山信有材。","画戟风生两衙退，飞桥日出万人来。","不因毁圮催兴筑，谁见雍容治剧才。"]},{"t":"次韵李豸秀才来别子瞻仍谢惠马","f":"七言律诗","c":["小床卧客笑元龙，弹铗无舆下舍中。","五马不辞分后乘，轻裘初许敝诸公。","随人射虎气终在，徒步白头心颇同。","遥想据鞍横槊处，新诗一一建安风。"]},{"t":"次韵李昭叙供备宴别湖亭","f":"七言律诗","c":["池亭雨过一番凉，云髻罗裙客两旁。","不觉行人离恨远，贪看积水照筵光。","满堂樽俎欢方剧，极目江湖意自长。","归去伊川潇洒地，不须遗念属清湘。"]},{"t":"次韵李曼朝散得郡西归留别二首 其一","f":"七言律诗","c":["风波定后得西归，乌鹊喧呼里巷知。","未熟黄粱惊破梦，相看白发信乘危。","豚肩尚有冬深味，蚕器应逢市合时。","父老为公留腊酒，不须犹唱式微诗。"]},{"t":"次韵李曼朝散得郡西归留别二首 其二","f":"七言律诗","c":["怀印徒行尚故衣，邸中掾史见犹疑。","千人上冢乡关动，五马行春雨泽随。","醉里坠车初未觉，道中破甑复谁悲。","西行漫遣亲朋喜，早赋陶翁归去诗。"]},{"t":"次韵李朝散游洞山二首 其一","f":"七言律诗","c":["古寺依山占几峰，精庐仿佛类天宫。","三年欲到官为碍，百里相望意自通。","无事佛僧何处著，人群鸟兽不妨同。","眼前簿领何时脱，一笑相看丈室中。"]},{"t":"次韵李朝散游洞山二首 其二","f":"七言律诗","c":["僧老经时不出山，法堂延客未曾关。","心开宝月婵娟处，身寄浮云出没间。","休夏巾瓶谁与共，迎秋水石不胜闲。","近来寄我《金刚》颂，欲指胸中无所还。"]},{"t":"次韵李简夫因病不出","f":"七言律诗","c":["十五年来一味闲，近来推病更安眠。","鹤形知瘦非关老，僧定端居不计年。","坐上要须长满客，杖头何用出携钱。","未嫌语笑妨清静，闲暇陪公几杖前。"]},{"t":"次韵李简夫秋园","f":"五言律诗","c":["秋色岂相负，小园仍有花。","绕栏吟落日，拾径得残葩。","菊细初藏蝶，桐疏不庇鸦。","游观须作意，霜雪仅留槎。"]},{"t":"次韵杨褒直讲揽镜","f":"七言律诗","c":["鬓发年来日向衰，相宽不用强裁诗。","壮心付与东流去，霜蟹何妨左手持。","花发黄鹂巧言语，池开杨柳斗腰肢。","劝君行乐还听否，即是南风苦热时。"]},{"t":"次韵汪琛监簿见赠","f":"七言律诗","c":["连宵暑雨气如秋，过客不来谁与游。","赖有澹台肯相顾，坐令彭泽未能休。","琴疏不办弹新曲，学废谁令致束修。","惭愧邑人怜病懒，共成清净劝迟留。"]},{"t":"次韵迟初入宣河","f":"五言律诗","c":["远客安长道，低蓬称小溪。","云添湿帆雨，舟滞没篙泥。","草绿耕牛健，村深候鸟啼。","陶翁方作令，归去未成题。"]},{"t":"次韵陈师仲主簿见寄","f":"五言律诗","c":["朽株难刻画，枯叶任凋零。","旧友频相问，村酤独未醒。","山牙收细茗，江实得流萍。","颇似申屠子，都忘足被刑。"]},{"t":"次韵知郡贾蕃大夫思归","f":"七言律诗","c":["江城漂泊最多时，邂逅谁令长者期。","得坎浮槎应有命，投林惊鹊且安枝。","何年笑语还留客，终日勤劳数问儿。","铃阁清虚非此比，秋风归兴恐非宜。"]},{"t":"次韵范景仁侍郎移竹","f":"五言律诗","c":["双桧生南户，丛筠种北墙。","交阴奉君子，为伴老中堂。","露洗秋阶绿，风含夏簟凉。","栽花知已误，新上一番霜。"]},{"t":"次韵侯宣州利建招致政汪大夫","f":"七言律诗","c":["社瓮壶浆接四邻，肩舆拄杖试红尘。","惯眠林下三竿日，来看城中万井春。","世上升沉无限事，樽前强健不资身。","经过已足知公政，长见车中有老人。"]},{"t":"次韵侯宣城题叠嶂楼","f":"五言律诗","c":["小邑来时路，宣城最近邻。","楼台百年旧，花竹一番新。","登览春深日，凝思病后身。","何时对樽酒，重为洗埃尘。"]},{"t":"次韵姚孝孙判官见还岐梁唱和诗集","f":"七言律诗","c":["伯氏文章岂敢知，岐梁偶有往还诗。","自怜兄力能兼弟，谁肯埙终不听篪。","西虢春游池百顷，南溪秋入竹千枝。","恨君曾是关中吏，属和追陪失此时。"]},{"t":"次韵姜应明黄檗山中见寄","f":"七言律诗","c":["垂老闲居味更深，此身随世任浮沉。","北窗未厌曲肱卧，西洛能传拥鼻吟。","疋马徬徨犹寄食，敝裘安乐信无心。","我今漂泊还相似，同愧高僧支道林。"]},{"t":"次韵柳子玉见赠","f":"七言律诗","c":["壮心衰尽愧当年，刻意为文日几千。","老去读书聊度岁，春来多睡苦便毡。","梦归似雁长飞去，才短如蚕只自缠。","唯有闻诗尚思和，可能时寄最高篇。"]},{"t":"次韵柳子玉郎中见寄","f":"七言律诗","c":["新年始是识君初，顾我尘埃正满裾。","谈辩未容朝夕听，情亲空愧往还书。","久闻笔阵无前敌，更拟诗坛托后车。","待得入城应少暇，相从有约定何如。"]},{"t":"次韵柳见答","f":"七言律诗","c":["桂酒无人寄豫章，羁愁牢落遣谁当。","烹煎崖蜜真牵强，惭愧山蜂久蓄藏。","江上鲙鲈橙正熟，山头吹帽菊初香。","漂流异日俱陈迹，笑说过从想未忘。"]},{"t":"次韵柳真公闲居春日","f":"七言律诗","c":["春寒渐欲减衣绵，雨势冥冥水拍天。","一局无言消日永，新诗得意许人传。","惜花田地应慵扫，护笋藩篱可细编。","好事报君知我喜，同官欲到得闲眠。"]},{"t":"次韵洞山克文长老","f":"五言律诗","c":["无地容锥卓，年来转觉贫。","偶知珠在手，一任甑生尘。","窜逐非关性，颠狂却甚真。","此心谁复识，试语洞山人。"]},{"t":"次韵赵至节推首夏","f":"七言律诗","c":["首夏寻芳也未迟，绕园红紫尚菲菲。","无心与物真皆可，有酒逢人劝莫违。","梦逐杨花无限思，身惭啼鸟不如归。","官居寂寞如僧舍，海燕怜贫故入扉。"]},{"t":"次韵唐觐送姜应明谒新昌杜簿","f":"七言律诗","c":["夫子虽穷气浩然，轻蓑短笠傲江天。","薄游到处唯耽酒，归去无心苦问田。","泮上讲官殊不俗，山中老簿亦疑仙。","相从未足还辞去，欲向曹溪更问禅。"]},{"t":"次韵徐正权谢示闵子庙记及惠纸","f":"七言律诗","c":["西溪秋思日盈笺，幕府拘愁学久骞。","记庙终惭无好句，酹坟犹喜有前篇。","屏除笔砚真良计，写寄交游畏妄传。","吴纸赠君君莫怪，耕耘废罢有闲田。"]},{"t":"次韵偶成","f":"七言律诗","c":["交情淡泊久弥新，吏役萦缠日益纷。","香火社中真避世，簿书丛里强论文。","樽罍正及明蟾夜，舟楫来随早雁群。","世俗如君今有几，真将富贵等浮云。"]},{"t":"次韵黄大临秀才见寄","f":"七言律诗","c":["故人聚散霜前叶，往事眇茫风际烟。","游宦一生非有己，隐居万事不由天。","崎岖槛阱方谋食，啸傲山林肯计年。","赖已将心问卢老，相逢他日笑风颠。"]},{"t":"次韵傅宏推官义方亭","f":"七言律诗","c":["居近古城心自幽，箪瓢足用更何求。","莺飞旋趁春风出，龙卧终闻莫雨搜。","科第联翩收甲乙，乡闾惊怪问因由。","隐君淡泊无人识，长夏一衫冬一裘。"]},{"t":"次韵景仁饮宋温之南轩二首 其一","f":"五言律诗","c":["白发迎新岁，皤然国老更。","感时能细说，对酒任徐行。","画轴高分品，诗词妙入评。","疏狂先醉倒，应许恃乡情。"]},{"t":"次韵景仁饮宋温之南轩二首 其二","f":"五言律诗","c":["饮阑瓶已罄，话久仆须更。","高会良难得，危言岂易行。","归休便老计，得失任台评。","犹有青编在，它年不世情。"]},{"t":"次韵景仁招宋温之职方小饮","f":"五言律诗","c":["高人两无事，相见辄倾怀。","时以酒相命，何妨心自斋。","灯期飞雪乱，春候苦寒乖。","不就颓然醉，难堪风且霾。"]},{"t":"次韵曾子开舍人四月一二日扈从二首 其一","f":"七言律诗","c":["万人齐仗足声匀，翠辇徐行不动尘。","夹道欢呼通老稚，从官杂遝数徐陈。","旌旗稍放龙蛇卷，旒冕初看日月新。","天遣雨师先洒道，农夫不复误占辛。"]},{"t":"次韵曾子开舍人四月一二日扈从二首 其二","f":"七言律诗","c":["衣冠双日款蓬莱，帘脱琼钩扇不开。","清晓逮惊三殿启，翠华遥自九天来。","晨光稍稍侵黄盖，瑞雾霏霏著禁槐。","千两翟车观礼罢，归时满载德风回。"]},{"t":"次韵温守李钧见寄兼简毛大夫","f":"七言律诗","c":["梁苑相从簿领中，清风相逐画船东。","婆娑江海凌云鹤，饮啄笼樊失渚鸿。","别后丹砂迷旧诀，愁来白发变衰翁。","此间诗老仍勍敌，正忆高吟酒盏空。"]},{"t":"次韵程相公以柳湖久涸辄引蔡水溉注感而成咏二首 其二","f":"七言律诗","c":["老鱼呴鬣困无津，凿破灵河涨旧濆。","明月还从沙渚见，红尘却傍柳堤分。","急泉垂下长虹尾，駴浪飞来白鹭群。","范蠡如闻应更爱，解摇双桨入西曛。"]},{"t":"次韵程相公以柳湖久涸辄引蔡水溉注感而成咏二首 其一","f":"七言律诗","c":["鳞鳞沙脚出平湖，一喷珠玑碧有馀。","依旧镜中横紫阁，却从天外望仙闾。","粉花又结青莲子，金尾还跳赤鲤鱼。","自惜支离苦为病，重来应共酒杯疏。"]},{"t":"次韵答人见寄","f":"七言律诗","c":["对案青山云气腾，天将隙地养无能。","窗扉迎署梅将溜，虚市无人冷欲冰。","寂默忘言惭社燕，毰毸困睡比春鹰。","深知大府容衰病，复值年来蚕麦登。"]},{"t":"次韵答人槛竹","f":"五言律诗","c":["猗猗元自直，落落不须扶。","密节风吹展，清阴月共铺。","丛长傲霜雪，根瘦耻泥涂。","更种愁无地，应须剪碧芦。"]},{"t":"次韵答孔武仲","f":"七言律诗","c":["白发青衫不记年，相逢一笑暂欣然。","诵诗亹亹锯木屑，展卷骎骎下水船。","未肯尺寻分枉直，日知凿枘有方圆。","闲官更似扬州学，犹得昏昏昼日眠。"]},{"t":"次韵道潜见寄","f":"七言律诗","c":["萧萧华发映衰容，惭愧高僧叹不逢。","游宦终身空处处，尘埃何日退重重。","已甘憔悴鸡群鹤，犹胜劬劳旱岁龙。","回首不堪膏火热，试求甘露洒青松。"]},{"t":"次韵道潜南康见寄","f":"七言律诗","c":["一叶追随鱼与龙，红粳白酒幸年丰。","也知山色遥相待，苦畏君诗欲见攻。","乘兴风帆终日去，寻幽蜡屐及春同。","请君先入开先寺，待濯清溪看玉虹。"]},{"t":"次韵韩宗弼太祝送游太山","f":"七言律诗","c":["羡君官局最优游，笑我区区学问囚。","今日登临成独往，终年勤苦粗相酬。","春深绿野初开绣，云解青山半脱裘。","回首红尘读书处，煮茶留客小亭幽。"]},{"t":"次韵筠守毛维瞻司封观修城三首 其一","f":"七言律诗","c":["北垣荆棘旧成堆，留待公来次第开。","车马已通城下路，榛芜尽付冶家灰。","异时碧瓦千门合，应记红旌百度来。","自笑裨谌便旷野，肩舆飞盖许追陪。"]},{"t":"次韵筠守毛维瞻司封观修城三首 其二","f":"七言律诗","c":["拨弃案头文字堆，晓晴山色四门开。","究怀民事老虽壮，俯首山城心已灰。","荆棘烧残桑柘出，狐狸去尽犬鸡来。","规模先遣通蹊隧，后乘应容众客陪。"]},{"t":"次韵筠守毛维瞻司封观修城三首 其三","f":"七言律诗","c":["山脚侵城起阜堆，绕城徼道斩新开。","闉阇半坏惊潮信，隍壑初深见劫灰。","蚁聚千夫曾几日，鳞差万瓦看将来。","史君才力轻山郡，朝论行闻急召陪。"]},{"t":"汝南示三子","f":"七言律诗","c":["此生赖有三男子，到处来看老病翁。","饮食粗便鱼稻足，音尘不隔马牛风。","道场莫问何方是，舍宅元依毕竟空。","且尔不归归亦得，汝曹免复走西东。"]},{"t":"江州五咏 其一 射蛟浦","f":"五言律诗","c":["万骑巡游遍，千帆破浪轻。","射蛟江水赤，教战越人惊。","山转楼船影，岸摧连弩声。","祈招无为赋，酣寝尽平生。"]},{"t":"江州五咏 其三 庾楼","f":"五言律诗","c":["元规情不薄，上客有殷生。","夜半酒将罢，公来坐不惊。","舞翻江月迥，谈落麈毛轻。","尘世风流尽，高楼空此名。"]},{"t":"池州萧丞相楼二首 其一","f":"七言律诗","c":["绕郭青峰睥睨屯，入城流水縠文翻。","楼成始觉江山胜，人去方知德业尊。","坐久浮云霾后岭，酒醒飞雪变前村。","我来邂逅公归国，犹喜登临共一樽。"]},{"t":"池州萧丞相楼二首 其二","f":"七言律诗","c":["丞相风流直至今，朱栏仍对旧山林。","奔驰轩冕终何有，跌宕图书意最深。","松绕城头风瑟缩，江浮山外气阴森。","三年不起南迁想，应有前人识此心。"]},{"t":"自黄州还江州","f":"七言律诗","c":["身浮一叶返湓城，凌犯风涛日夜行。","把酒独斟从睡重，还家渐近觉身轻。","岸回樊口依稀见，日出庐山紫翠横。","家在庾公楼下泊，舟人遥指岸如赪。"]},{"t":"至池州赠陈鼎秀才","f":"七言律诗","c":["淮阳学舍旧相依，常诵曹溪第一机。","却到江西心有悟，回看过去事皆非。","孤舟远适身如寄，二顷躬耕道自肥。","欲看齐山君去否，闲中徒侣近来稀。"]},{"t":"西成","f":"五言律诗","c":["野老端相庆，西成仅十分。","寒来多酿酒，客过预留饙。","近事姑求饱，远忧要浪闻。","一壶真有理，终日得醺醺。"]},{"t":"观大阅","f":"七言律诗","c":["承平郡国减兵屯，唯有留都一万人。","票姚将军思出塞，从横幕府讳和亲。","旌旗不动风将转，部曲无声马亦驯。","八阵且留遗法在，未须亲试革车尘。"]},{"t":"过毛国镇夜饮","f":"七言律诗","c":["风格照人华省郎，江山绕郭古仙乡。","漫传铅鼎八百岁，未比金钗十二行。","不动歌声人已醉，旋闻诗句夜初长。","簿书拨尽知馀力，道院清虚顷未尝。"]},{"t":"过王介同年墓","f":"七言律诗","c":["平生使气坐生风，徐叩方知学有功。","应奉读书无复忘，虞翻忤物自甘穷。","埋根射策久弥奋，投老为邦悍莫攻。","坟木未须惊已拱，少年我亦作衰翁。"]},{"t":"过侄寄椰冠","f":"七言律诗","c":["衰发秋来半是丝，幅巾缁撮强为仪。","垂空旋取海棕子，束发装成老法师。","变化密移人不悟，坏成相续我心知。","茅檐竹屋南溟上，亦似当年廊庙时。"]},{"t":"问蔡肇求李公麟画观音德云","f":"五言律诗","c":["好事桓灵宝，多才顾长康。","何尝为人画，但可设奇将。","久聚要当散，能分慰所望。","清新二大士，畀我夜烧香。"]},{"t":"阴晴不定简唐觐秘校并敖吴二君五首 其五","f":"五言律诗","c":["二子薪中楚，相携泮上游。","齑盐聊度日，爻象久忘忧。","寂寞君何病，驱驰我自羞。","何时采芹处，永日看凫鸥。"]},{"t":"阴晴不定简唐觐秘校并敖吴二君五首 其四","f":"五言律诗","c":["西邻豫章客，病骨瘦栾栾。","清夜眠孤枕，终朝饱一箪。","雨多愁不出，讲罢未应餐。","约我晴相过，门前泥欲乾。"]},{"t":"阴晴不定简唐觐秘校并敖吴二君五首 其三","f":"五言律诗","c":["涨江方断渡，小棹信轻生。","贫贱谁怜汝，漂浮空自惊。","一官终窃食，何计早归耕。","忽发骚人恨，凄凉久未平。"]},{"t":"阴晴不定简唐觐秘校并敖吴二君五首 其二","f":"五言律诗","c":["蚕眠初上簇，麦熟正磨镰。","云气重重合，江流夜夜添。","荐饥人甚困，多病我仍兼。","欲就桥南宿，单衣莫雨沾。"]},{"t":"阴晴不定简唐觐秘校并敖吴二君五首 其一","f":"五言律诗","c":["积雨春连夏，新晴忽复阴。","江痕涨犹在，梅气润相侵。","蕉纻还须脱，图书渐不禁。","江南旧风俗，愁绝北来心。"]},{"t":"余居高安三年每晨入莫出辄过圣寿访聪长老谒方子明浴头笑语移刻而归岁月既久作一诗记之","f":"七言律诗","c":["朝来卖酒江南市，日莫归为江北人。","禅老未嫌参请数，渔舟空怪往来频。","每惭菜饭分斋钵，时乞香泉洗病身。","世味渐消婚嫁了，幅巾绛褐许相亲。"]},{"t":"初成遗老斋二首 其二","f":"七言律诗","c":["旧说颍川宜老人，朱樱斑笋养闲身。","无心已绝衣冠念，有眼不遭车马尘。","青简自书遗老传，白须仍写去年真。","斋成谩作笑谈主，已是萧然一世宾。"]},{"t":"初成遗老斋二首 其一","f":"七言律诗","c":["花时懒出伴游人，暑雨深藏养病身。","新宅丁丁厌斤斧，旧书寂寂卷埃尘。","久将生事累诸子，顿敛浮根付一真。","遗老斋成谋宴坐，澹然无语接来宾。"]},{"t":"初成遗老斋待月轩藏书室三首 其一 遗老斋","f":"七言律诗","c":["老人身世两相遗，绿竹青松自蔽亏。","已喜形骸今我有，枉将名字与人知。","往还但许邻家父，问讯才通说法师。","燕坐萧然便终日，客来不识我为谁。"]},{"t":"初成遗老斋待月轩藏书室三首 其二 待月轩","f":"七言律诗","c":["轩前无物但长空，孤月忽来东海东。","圆满定从何处得，清明许与众人同。","怜渠生死未能免，顾我盈亏略已通。","夜久客寒要一饮，油然细酌意无穷。"]},{"t":"初成遗老斋待月轩藏书室三首 其三 藏书室","f":"七言律诗","c":["读书旧破十年功，老病茫然万卷空。","插架都将付诸子，闭关犹得养衰翁。","案头萤火从乾死，窗里飞蝇久未通。","自见老卢真面目，平生事业有无中。"]},{"t":"初到绩溪视事三日出城南谒二祠游石照偶成四小诗呈诸同官 汪王庙","f":"七言律诗","c":["石门南出众山巅，沃壤清溪自一川。","老令旧谙田事乐，春耕正及雨晴天。","可怜鞭挞终无补，早向丛祠乞有年。","归告仇梅省文字，麦苗含穗欲蚕眠。"]},{"t":"初到绩溪视事三日出城南谒二祠游石照偶成四小诗呈诸同官 梓桐庙","f":"七言律诗","c":["行年五十治丘民，初学催科愧庙神。","无限青山不容隐，却看黄卷自怜贫。","雨馀岭上云披絮，石浅溪头水蹙鳞。","指点县城如手大，门前五柳正摇春。"]},{"t":"初得南园","f":"七言律诗","c":["倒囊仅得千竿竹，扫地初开一亩宫。","千里故园魂梦里，百年生事寂寥中。","晏家不愿诸侯赐，颜氏终成陋巷风。","洗竹移花吾事了，子孙他日记衰翁。"]},{"t":"初葺遗老斋二首 其二","f":"七言律诗","c":["为留十步南墙竹，莫怪门前鸟雀多。","陋巷何妨似颜子，势家应未夺萧何。","诗书懒惰何曾读，气息调匀不用呵。","多病从来少宾客，杜门今复几人过。"]},{"t":"初葺遗老斋二首 其一","f":"七言律诗","c":["髭须浑白已经岁，腰痛春来日又多。","一味安闲犹有碍，却令朝谒拟如何。","筑居定作子孙计，好事久遭僧佛呵。","尤愧白家履道宅，十年成就饱经过。"]},{"t":"县中诸花多交代江君所栽牡丹已过芍药方盛偶寄小诗","f":"七言律诗","c":["偶来山邑便成家，惭愧潘生满县花。","想见清樽槛边饮，尚留佳句壁间誇。","根株未老年年好，艳色方秾日日加。","闻道北游无意味，春深河上足风沙。"]},{"t":"吴冲卿夫人秦国挽词二首 其二","f":"五言律诗","c":["雅颂成章早，春秋发论长。","风规留叔向，文采似中郎。","览古明兴废，临危喜激昂。","南迁初不恨，李杜得从滂。"]},{"t":"吴冲卿夫人秦国挽词二首 其一","f":"五言律诗","c":["国老相随尽，家风慨独存。","见夫成相业，听子得忠言。","气节惭多士，声华盛一门。","平生高义重，未易俗人论。"]},{"t":"宋城宰韩秉文惠日铸茶","f":"七言律诗","c":["君家日铸山前住，冬后茶芽麦粒粗。","磨转春雷飞白雪，瓯倾锡水散凝酥。","溪山去眼尘生面，簿领埋头汗匝肤。","一啜更能分幕府，定应知我俗人无。"]},{"t":"张公洞","f":"七言律诗","c":["乱山深处白云堆，地坼中空洞府开。","茧瓮有天含宇宙，瑶台无路接蓬莱。","金芝春暖青牛卧，珠树月明黄鹤回。","此日登临兴何限，春风吹绽碧桃腮。"]},{"t":"张文裕侍郎挽词","f":"七言律诗","c":["持节西南二十年，华堂遗像已苍然。","归来侍从三朝旧，老去雍容平地仙。","落笔纵横题壁处，诵诗清壮举杯前。","东游邂逅迎归旐，泪落城南下马阡。"]},{"t":"怀黾池寄子瞻兄","f":"七言律诗","c":["相携话别郑原上，共道长途怕雪泥。","归骑还寻大梁陌，行人已渡古崤西。","曾为县吏民知否，旧宿僧房壁共题。","遥想独游佳味少，无言骓马但鸣嘶。"]},{"t":"李公麟阳关图二绝 其一","f":"七言绝句","c":["百年摩诘阳关语，三叠嘉荣意外声。","谁遣伯时开缟素，萧条边思坐中生。"]},{"t":"李邦直见邀终日对卧南城亭上二首 其一","f":"七言律诗","c":["一径坡陀草木间，孤亭胜绝俯川原。","青天图画四山合，白昼雷霆百步喧。","烟柳萧条渔市远，汀洲苍莽白鸥翻。","客舟何事来匆草，逆上波涛吐复吞。"]},{"t":"李邦直见邀终日对卧南城亭上二首 其二","f":"七言律诗","c":["东来无事得遨游，奉使清闲亦自由。","拨弃簿书成一饱，留连语笑失千忧。","旧书半卷都如梦，清簟横眠似欲秋。","闻说归朝今不久，尘埃还有此亭不。"]},{"t":"李邦直出巡青州余不久将赴南都比归不及见矣作诗赠别","f":"七言律诗","c":["东道初来托故人，南楼频上泗河漘。","江山尚有留人意，樽俎宁当厌客贫。","顾我及秋行不久，问君触热去何因。","西归凉冷霜风后，浊酒清诗谁与亲。"]},{"t":"泛潩水","f":"七言律诗","c":["早岁南迁恨舳舻，归来平地忆江湖。","半篙春水花千片，八尺轻船酒一壶。","徐转城阴平野阔，稍通竹径小亭孤。","前朝宰相终难得，父老咨嗟今亦无。"]},{"t":"秀州僧本瑩净照堂","f":"七言律诗","c":["有僧访我携诗卷，自说初成净照堂。","求得篇章书壁素，不论尘土渍衣黄。","故山别后成新岁，归梦春来绕旧房。","看取盈编定何益，客来无语但循墙。"]},{"t":"赤壁怀古","f":"七言律诗","c":["新破荆州得水军，鼓行夏口气如云。","千艘已共长江崄，百胜安知赤壁焚。","觜距方强要一斗，君臣已定势三分。","古来伐国须观衅，意突成功所未闻。"]},{"t":"迎寄王适","f":"七言律诗","c":["投窜千山恨不深，扁舟夏涉气如烝。","重来疋马君何事，归去飞鸿我未能。","养气经年惟脱粟，读书终夜有寒灯。","安心且作衰慵伴，海底鲲鱼会化鹏。"]},{"t":"连雨不出寄张恕","f":"七言律诗","c":["麦熟蚕缫热似烝，雨倾三尺未为淫。","洗清沟浍蚊虻静，没尽蒲莲沼沚深。","遗秉满田惊朽腐，移床避漏畏侵寻。","高闲祇有张公子，卧听萧萧打叶音。"]},{"t":"邵武游氏老人三清堂紫芝","f":"七言律诗","c":["黑龟赤凤早逢师，白发苍颜老不衰。","丹鼎一丸深自秘，紫芝三叶却先知。","烟熏晴日云容薄，色凝秋霜玉性奇。","何日刀圭救羸病，尽芟荆棘种交梨。"]},{"t":"闰八月二十五日菊有黄花园中粲然夺目九日不忧无菊而忧无酒戏作","f":"七言律诗","c":["年年九日忧无菊，今岁床空未有糟。","世事何尝似人意，天公端解恼吾曹。","金龟解去瓶应满，玉液倾残气尚豪。","门外白衣还到否，今时好事恐难遭。"]},{"t":"和子瞻三游南山九首 楼观","f":"七言律诗","c":["神仙避世守关门，一世沉埋百世尊。","旧宅居人无姓尹，深山道士即为孙。","天寒游客常逢雪，日暮归鸦自识村。","君欲留身记幽寂，直将山外比羌浑。"]},{"t":"和子瞻三游南山九首 五郡","f":"七言律诗","c":["蜀人不信秦川好，食蔗从梢未及甘。","当道沙尘类河北，依山水竹似江南。","观形随阜饮溪鹿，云气侵山食叶蚕。","犹有道人迎客笑，白须黄袖岂非聃。"]},{"t":"和子瞻三游南山九首 大秦寺","f":"五言律诗","c":["大秦遥可说，高处见秦川。","草木埋深谷，牛羊散晚田。","山平堪种麦，僧鲁不求禅。","北望长安市，高城远似烟。"]},{"t":"和子瞻三游南山九首 仙游潭五首 其四 马融石室","f":"五言律诗","c":["扶风贵公子，早岁伴山家。","吹笛堕秋叶，读书随晓鸦。","业成心自叛，学苦我长嗟。","石室非人住，穷山雪似沙。"]},{"t":"和子瞻三游南山九首 仙游潭五首 其一 潭","f":"五言律诗","c":["潭深不可涉，潭小不通船。","路断游人止，龙藏白沫旋。","剪藤量水短，插石置桥坚。","桥外居民少，躬耕不用钱。"]},{"t":"和子瞻三游南山九首 仙游潭五首 其五 玉女洞","f":"五言律诗","c":["洞门苍藓合，逼仄不容身。","传有虚明处，中藏窈窕人。","吹笙桥上月，拾翠洞南春。","往往来山下，萧然雨洒尘。"]},{"t":"和子瞻三游南山九首 仙游潭五首 其二 南寺","f":"五言律诗","c":["澄潭下无底，将渡又安能。","惯上横空木，轻生此寺僧。","晓鱼闻考考，石塔见层层。","不到殊非恶，他年记未曾。"]},{"t":"和子瞻过岭","f":"七言律诗","c":["山林瘴雾老难堪，归去中原荼亦甘。","有命谁令终返北，无心自笑欲巢南。","蛮音惯习疑伧语，脾病萦缠带岭岚。","手挹祖师清净水，不嫌白发照毵毵。"]},{"t":"和子瞻新居欲成二首 其二","f":"七言律诗","c":["山连上帝朱明府，心是南宗无尽灯。","过此攲危空比梦，年来瘴毒冷如冰。","图书一笑宁劳客，音信频来尚有僧。","梨枣功夫三岁办，不缘忧患亦何曾。"]},{"t":"和子瞻新居欲成二首 其一","f":"七言律诗","c":["老罢子卿还属国，功成定远恨阳关。","漂流岂必风波际，颠沛何妨枕席间。","伏腊便应随俚俗，室庐闻似胜家山。","因缘宿世非今日，赖有阴功许旋还。"]},{"t":"和子瞻题风水洞","f":"七言律诗","c":["风送江湖满洞天，洞门可听入无缘。","土囊郁怒声初散，石齿聱牙势未前。","乐奏洞庭真跌宕，歌传帝所亦清便。","何人隐几观遗韵，重使颜成问嗒然。"]},{"t":"和孔武仲金陵九咏 其五 高斋","f":"七言律诗","c":["金陵佳处自无穷，使宅幽深即故宫。","楼殿六朝遗烬后，江山百里旧城中。","雨馀尚有金钿落，月出长窥粉堞空。","看尽一城怀古地，兹游恨不与君同。"]},{"t":"和孔武仲金陵九咏 其三 凤凰台","f":"五言律诗","c":["凤鸟久不至，斯台空复高。","何年种梧竹，特地剪蓬蒿。","白水来无际，青山转几遭。","南游且未返，江海共滔滔。"]},{"t":"和孔武仲金陵九咏 其四 天庆观","f":"五言律诗","c":["兴废不可必，冶城今静祠。","松声闻道路，竹色净轩墀。","江近风云改，亭深草木滋。","孤坟吊遗直，狂闇闵元规。"]},{"t":"和孔武仲金陵九咏 其七 见江亭","f":"五言律诗","c":["江水信浩渺，连山巧蔽亏。","端能上崄绝，故自识津涯。","灭没樯竿度，飘摇鹭羽迟。","何人倚舟望，亦爱此峰危。"]},{"t":"和孔武仲金陵九咏 其一 白鹭亭","f":"五言律诗","c":["白鹭洲前水，奔腾乱马牛。","亭高疑欲动，船去似无忧。","汹涌山方坏，澄清练不收。","中秋谁在此，明月满城头。"]},{"t":"和孔武仲金陵九咏 其六 此君亭","f":"五言律诗","c":["绿竹不可数，孤亭一倍幽。","色分岩石润，梢出涧松修。","雪节寒方见，春萌旱不抽。","故山多此物，长恨未归休。"]},{"t":"和孔武仲金陵九咏 其二 览辉亭","f":"五言律诗","c":["城里最高处，坡陀见一城。","山多来有绪，江远静无声。","歌吹风前度，楼台雨后明。","风光同楚蜀，聊此慰平生。"]},{"t":"和孔教授武仲济南四咏 其二 北渚亭","f":"七言律诗","c":["西湖已过百花汀，未厌相携上古城。","云放连山瞻岳麓，雪消平野看春耕。","临风举酒千钟尽，步月吹笳十里声。","犹恨雨中人不到，风云飘荡恐神惊。"]},{"t":"和孔教授武仲济南四咏 其一 环波亭","f":"七言律诗","c":["南山迤逦入南塘，北渚岧峣枕北墙。","过尽绿荷桥断处，忽逢朱槛水中央。","凫鹥聚散湖光净，鱼鳖浮沉瓦影凉。","清境不知三伏热，病身唯要一藤床。"]},{"t":"和孔教授武仲济南四咏 其三 鹊山亭","f":"七言律诗","c":["筑台临水巧安排，万象轩昂发瘗埋。","南岭崩腾来不尽，北山断续意尤佳。","平时战伐皆荒草，永日登临慰病怀。","更欲留诗题素壁，坐中谁与少陵偕。"]},{"t":"和孔教授武仲济南四咏 其四 槛泉亭","f":"七言律诗","c":["连山带郭走平川，伏涧潜流发涌泉。","汹汹秋声明月夜，蓬蓬晓气欲晴天。","谁家鹅鸭横波去，日暮牛羊饮道边。","滓秽未能妨洁净，孤亭每到一依然。"]},{"t":"和毛国镇白云庄五咏 其二 平溪堂","f":"七言律诗","c":["清溪似与隐君谋，故入堂前漫不收。","盥手从今休汲井，浮觞取意便临流。","花漂涧谷来应远，石激琴筝久未休。","莫把朱栏强围绕，山家事事要清幽。"]},{"t":"和毛国镇白云庄五咏 其一 掬泉轩","f":"七言律诗","c":["卜筑高深已有山，起居清润可无泉。","穿墙白练秋声细，照屋清铜晓色鲜。","已放鱼虾嫌跳掷，更除蘋藻任漪涟。","只应明月中霄下，长共禅心相向圆。"]},{"t":"和毛国镇白云庄五咏 其三 眺远台","f":"七言律诗","c":["山似高人长远人，不登高处见无因。","筑台土石无多子，照眼峰峦得许新。","阵马奔腾时绝远，风涛舒卷忽无垠。","白云自是逃名处，犹恐此中藏隐沦。"]},{"t":"和毛国镇白云庄五咏 其四 濯缨庵","f":"七言律诗","c":["临池濯足惜泉清，缨上无尘且强名。","横木为桥便独往，结茅依岛类天成。","往还渐少人谁识，寝食无为身转轻。","有似三吴朱处士，钓鱼谁与话西征。"]},{"t":"和王定国寄刘贡父","f":"七言律诗","c":["度岭当年惜远行，过淮今日似前生。","留连秋思江侵海，摇荡春心花满城。","欲寄尺书慵把笔，偶闻佳句独含情。","何时复看清虚会，醉听秦筝促柱声。"]},{"t":"和王适新葺小室","f":"七言律诗","c":["向日堂东一室存，竹为窗壁席为门。","心如白月光长照，气结丹砂体自温。","饭软莫嫌红米贱，酒香故取泼醅浑。","他年一笑同谁说，伴我三年江上村。"]},{"t":"和李公择赴历下道中杂咏十二首 泛清河","f":"五言律诗","c":["南北无多水，崎岖未舍船。","何时好霖雨，是处有通川。","坟垄看书卷，兴亡指道边。","苍茫半秋草，犹复较愚贤。"]},{"t":"和李公择赴历下道中杂咏十二首 将至桃园阻浅且风不得进","f":"七言律诗","c":["卷帆倚棹浅河津，忆泛长江步步新。","未免生涯寄风浪，不堪舟楫委埃尘。","往来欲就沙囊堰，深浅时看举策频。","一望云霓百忧集，应思平地隐居人。"]},{"t":"和李公择赴历下道中杂咏十二首 桃园阻浅将易小舟一夜水大至复乘便风顷刻百里","f":"七言律诗","c":["此生与物妄相仇，欲往长嫌苦见留。","浅濑何知向人恶，涨溪岂复为公流。","雨痕忽到工催客，风信初来转打头。","举目汀洲都未改，忽添清兴满行舟。"]},{"t":"和李公择赴历下道中杂咏十二首 宿迁项羽庙","f":"七言律诗","c":["尺箠西来垄亩中，驱驰力尽众兵冲。","旧封独守君臣义，故国长修俎豆容。","平日军声同破竹，少年心事喜摧锋。","锦衣眷恋多乡思，肯顾田家社酒醲。"]},{"t":"和李公择赴历下道中杂咏十二首 梁山泊","f":"七言律诗","c":["近通沂泗麻盐熟，远控江淮粳稻秋。","粗免尘泥污车脚，莫嫌菱蔓绕船头。","谋夫欲就桑田变，客意终便画舫游。","愁思锦江千万里，渔蓑空向梦中求。"]},{"t":"和青州教授顿起九日见寄","f":"七言律诗","c":["岁月飘然风际烟，紫萸黄菊又霜天。","莫思太室杉松外，且醉青州歌舞前。","杯酒追欢真一梦，天涯回望正三年。","近来又欲东观海，听说毛诗雅颂篇。"]},{"t":"和柳子玉共城新开御河过所居墙下","f":"七言律诗","c":["卜筑共山功欲成，新河入县巧相萦。","谁将畚锸千夫力，添上园林一倍清。","生长鱼虾供晚馔，浮沉鹅鸭放春声。","为邻有意非今日，丐我馀波伴濯缨。"]},{"t":"和柳子玉地炉","f":"七言律诗","c":["凿地泥床不费功，山深炭贱火长红。","拥衾熟睡朝衙后，抱膝微吟莫雪中。","宠辱两忘轻世味，冰霜不到傲天工。","遥知麻步无人客，寒夜清樽谁与同。"]},{"t":"和柳子玉纸帐","f":"七言律诗","c":["夫子清贫不耐冬，书斋还费纸重重。","窗明晓日从教入，帐厚霜飙定不容。","京兆牛衣聊可藉，公孙布被旋须缝。","吴绫蜀锦非嫌汝，简淡为生要易供。"]},{"t":"和胡教授蒙太守策试诸生","f":"七言律诗","c":["著籍初同阙里多，采芹先致鲁风和。","欲将大策观胸胆，尽召中堂列雁鹅。","终日正言何忌讳，几人馀力尚委蛇。","岂惟太守知为政，仍见先生善设科。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 和顿主簿起见赠二首 其二","f":"七言律诗","c":["一锁楼中暗度秋，微官黾勉未能休。","笑谈容我聊纾放，文字凭君便去留。","杯酒淋漓已非敌，清诗窈眇更难酬。","东归犹得联征骑，同上嵩高望九州。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 和顿主簿起见赠二首 其一","f":"七言律诗","c":["声病消磨只古文，诸儒经术斗纷纭。","不知旧学都无用，犹把新书强欲分。","老病心情愁见敌，少年词气动干云。","搜贤报国吾何敢，欲补空疏但有勤。"]},{"t":"和强君瓦亭","f":"七言律诗","c":["君为魏博三年客，日有江湖万里心。","暂得野亭留马足，强循疏柳步堤阴。","无人携手共吴语，得意摇头时越吟。","何日东郊过微雨，并骑鞍马去同寻。"]},{"t":"咏竹二首 其二","f":"五言律诗","c":["南邻竹甚茂，门巷不容宾。","悬印君当往，囊金我患贫。","翠旌稍乱起，犀角笋初匀。","不惜图书卖，端来作主人。"]},{"t":"咏竹二首 其一","f":"五言律诗","c":["湖滨宜草木，修竹可三寻。","廛居多野思，移种近墙阴。","及尔迷未醒，方予热正侵。","无嫌不逮本，地薄肯成林。"]},{"t":"咏霜二首 其一","f":"五言律诗","c":["江南雪不到，霜露满山村。","纸被欺毡厚，茅檐笑瓦温。","何曾凝沼渌，有意隔朝暾。","底日身无事，高眠不出门。"]},{"t":"咏霜二首 其二","f":"五言律诗","c":["清霜欺客病，乘夜逼窗扉。","坐睡依炉暖，细声闻叶飞。","蕉絺空满箧，砧杵旋催衣。","起看庭前草，松筠未觉非。"]},{"t":"奉使契丹二十八首 十日南归马上口占呈同事","f":"七言律诗","c":["南辕初喜去龙庭，入塞犹须阅月行。","汉马亦知归意速，朝旸已作故人迎。","经冬舞雪长相避，屈指新春旋复生。","想见雄州馈生菜，菜盘酪粥任纵横。"]},{"t":"奉使契丹二十八首 过杨无敌庙","f":"七言律诗","c":["行祠寂寞寄关门，野草犹知避血痕。","一败可怜非战罪，太刚嗟独畏人言。","驰驱本为中原用，尝享能令异域尊。","我欲比君周子隐，诛彤聊足慰忠魂。"]},{"t":"奉使契丹二十八首 古北口道中呈同事二首 其一","f":"七言律诗","c":["独卧绳床已七年，往来殊复少萦缠。","心游幽阙乌飞处，身在中原山尽边。","梁市朝回尘满马，蜀江春近水浮天。","枉将眼界疑心界，不见中宵气浩然。"]},{"t":"奉使契丹二十八首 古北口道中呈同事二首 其二","f":"七言律诗","c":["笑语相从正四人，不须嗟叹久离群。","及春煮菜过边郡，赐火煎茶约细君。","日暖山蹊冬未雪，寒生胡月夜无云。","明朝对饮思乡岭，夷汉封疆自此分。"]},{"t":"奉使契丹二十八首 次莫州通判刘泾韵二首 其一","f":"七言律诗","c":["北国亦知岐有夷，何尝烽火报惊危。","拥旃绝漠闻嘉语，缓带临边出好诗。","约我一樽迎嗣岁，待君三馆已多时。","从今无事唯须饮，文字声名人自知。"]},{"t":"奉使契丹二十八首 次莫州通判刘泾韵二首 其二","f":"七言律诗","c":["平世功名路甚夷，不劳谈说更骑危。","早年拭目看成赋，近日收心闻琢诗。","古锦屡开新得句，敝貂方竞苦寒时。","南还欲向春风饮，塞柳凋枯恐未知。"]},{"t":"奉使契丹二十八首 春日寄内","f":"七言律诗","c":["春到燕山冰亦消，归骖迎日喜嫖姚。","久行胡地生华发，初试东风脱敝貂。","插髻小幡应正尔，点槃生菜为谁挑。","附书勤扫东园雪，到日青梅未满条。"]},{"t":"奉使契丹二十八首 奚君","f":"五言律诗","c":["奚君五亩宅，封户一成田。","故垒开都邑，遗民杂汉编。","不知臣仆贱，漫喜杀生权。","燕俗嗟犹在，婚姻未许连。"]},{"t":"奉使契丹二十八首 惠州","f":"七言律诗","c":["孤城千室闭重闉，苍莽平川绝四邻。","汉使尘来空极目，沙场雪重欲无春。","羞归应有李都尉，念旧可怜徐舍人。","会逐单于渭桥下，欢呼齐拜属车尘。"]},{"t":"奉使契丹二十八首 赠右番赵侍郎","f":"七言律诗","c":["霜须顾我十年兄，朔漠陪公万里行。","骈马貂裘寒自暖，连床龟息夜无声。","同心便可忘苛礼，异类犹应服至诚。","行役虽劳思虑少，会看梨枣及春生。"]},{"t":"奉使契丹二十八首 赠知雄州王崇拯二首 其一","f":"七言律诗","c":["赵北燕南古战场，何年千里作方塘。","烟波坐觉胡尘远，皮币遥知国计长。","胜处旧闻荷覆水，此行犹及蟹经霜。","使君约我南来饮，人日河桥柳正黄。"]},{"t":"官居即事","f":"七言律诗","c":["官局纷纭簿领迷，生缘琐细老农齐。","偷安旋种十年木，肉食还须五母鸡。","对酒不尝怜酤榷，钓鱼无术漫临溪。","此身已分长贫贱，执爨缝裳愧老妻。"]},{"t":"官舍小池有鸂鶒遗二小雏二首 其一","f":"七言律诗","c":["半亩清池藻荇香，一双鸂鶒竞悠扬。","来从碧涧巢安在，飞过重城母自将。","野鸟似非官舍物，宰君昔是钓鱼郎。","直言愧比奇章老，得县无心更激昂。"]},{"t":"官舍小池有鸂鶒遗二小雏二首 其二","f":"五言律诗","c":["清池定谁至，鸂鶒自来驯。","知我无伤意，怜渠解托身。","桥阴栖息稳，岛外往来频。","勿食游鱼子，从交长细鳞。"]},{"t":"宛丘二咏 其二","f":"七言律诗","c":["古殿山花丛百围，故园曾见色依依。","凌寒强比松筠秀，吐艳空惊岁月非。","冰雪纷纭真性在，根株老大众园希。","山中草木谁携种，潦倒尘埃不复归。"]},{"t":"放榜后次韵毛守见招","f":"七言律诗","c":["饱食安眠愧不材，疏帘翠帟幸相陪。","深居正厌银袍乱，失喜初闻铁锁开。","佳句径蒙探古锦，小槽仍报滴新醅。","诸人欲见风流伯，不用招呼亦自来。"]},{"t":"欧阳太师挽词三首 其一","f":"五言律诗","c":["雄文元命世，直气早成风。","受任衰迟后，安邦反侧中。","回天深有力，扈圣耻言功。","事已身随去，惊嗟柱石空。"]},{"t":"欧阳太师挽词三首 其二","f":"五言律诗","c":["唐弊文初丧，书成法至今。","雍容趋圣处，深切可人心。","气力知难继，风流喜不淫。","悬知公欲谢，异说勇交侵。"]},{"t":"欧阳太师挽词三首 其三","f":"五言律诗","c":["推毂诚多士，登龙盛一时。","西门行有恸，东阁见无期。","念昔先君子，尝蒙国士知。","旧恩终未报，感叹不胜悲。"]},{"t":"河上莫归过南湖二绝 其一","f":"七言绝句","c":["西来白水满南池，走马池边日落时。","桥底荷花无限思，清香乞与路人知。"]},{"t":"河冰复结复次前韵","f":"七言律诗","c":["懊恼河冰散复生，徂年近已失峥嵘。","身留短舫厌厌睡，目送飞鸿一一轻。","引纤低徊疑上坂，打凌辛苦甚攻城。","东风怜我归心速，稍变杨梢百里迎。"]},{"t":"河冰稍解喜呈王适","f":"七言律诗","c":["留滞江湖白发生，西归犹苦冻峥嵘。","春风未到冰先解，河水初深船自轻。","去国偶然经昼梦，逢人稍欲问都城。","羁鸿共有成行喜，双鲤应将尺素迎。"]},{"t":"范丞相尧夫挽词二首 其二","f":"五言律诗","c":["南迁头已白，北返病初加。","君意知无罪，天心许到家。","同朝曾忝旧，握手一长嗟。","时事纷无已，还应付棣华。"]},{"t":"范丞相尧夫挽词二首 其一","f":"五言律诗","c":["持身守忠恕，临事耻浮沉。","直道更三黜，平生惟一心。","家风来自远，国论老弥深。","令德真如玉，泥沙枉见侵。"]},{"t":"试院唱酬十一首 次韵吕君丰城宝气亭","f":"七言律诗","c":["紫气飞空不自谋，谁怜黾勉匣中留。","西山猛兽横行甚，北海长鲸何日收。","星斗不堪供醉舞，蛟龙会看反重湫。","功成变化无踪迹，望断中原百尺楼。"]},{"t":"试院唱酬十一首 戏呈试官","f":"七言律诗","c":["只隔墙东便是家，悁悁还似在天涯。","客心不耐听松雨，归信犹堪饮菊花。","剪烛看书良寂寞，披沙见玉忽喧哗。","自惭空馆难留客，试问姮娥稍驻车。"]},{"t":"试院唱酬十一首 戏呈试官吕防","f":"七言律诗","c":["新秋风月正凉天，空馆相看学坐禅。","满榻诗书愁病眼，隔墙砧杵思高眠。","霜飞一叶凋琼玉，风绕双松奏管弦。","闻道熊罴归梦数，侵天闱棘漫森然。"]},{"t":"试院唱酬十一首 次前韵三首 其一","f":"七言律诗","c":["老去在家同出家，《楞伽》四卷即生涯。","粗诗怪我心犹壮，细字怜君眼未花。","霜落初惊衾簟冷，酒酣犹喜笑言哗。","归心知有三秋恨，莫学匆匆下坂车。"]},{"t":"试院唱酬十一首 次前韵三首 其二","f":"七言律诗","c":["门前溪水似渔家，流浪江湖归未涯。","邂逅高人来说法，支离枯木旋开花。","诸生试罢书如积，剧县归时讼正哗。","安得骑鲸从李白，试看牛女转云车。"]},{"t":"试院唱酬十一首 次前韵三首 其三","f":"七言律诗","c":["浊醪能使客忘家，屈指归期已有涯。","鱼化昨宵惊细雨，鹿鸣他日饮寒花。","已谙江上肴蔬薄，莫笑衙前鼓笛哗。","太守况兼乡曲旧，会须投辖止行车。"]},{"t":"试院唱酬十一首 次韵吕君见赠","f":"七言律诗","c":["偶然倾盖接清言，不觉门前昼漏传。","老病低摧方伏枥，壮心坚锐正当年。","莫嫌客舍一杯酒，试论灊山三祖禅。","明日程文堆几案，只应衰懒得安眠。"]},{"t":"试院唱酬十一首 次韵吕君兴善寺静轩","f":"七言律诗","c":["自恨寻山计苦迟，年过四十始知非。","小轩迎客如招隐，野鸟窥人自识机。","窗外竹深孤鹤下，阶前菊秀晚蜂飞。","老僧战胜长幽寂，瘦骨缘何未肯肥。"]},{"t":"金沙台","f":"七言律诗","c":["待罪东轩仅两秋，搉酤事了且夷犹。","奖崇善类询舆论，过访仁贤棹小舟。","契合通家心异姓，情敦同气迈凡流。","金沙台上聊舒乐，即景题诗閤酒瓯。"]},{"t":"雨中宿酒务","f":"七言律诗","c":["微官终日守糟缸，风雨凄凉夜渡江。","早岁谬知儒术贵，安眠近喜壮心降。","夜深唧唧醅鸣瓮，睡起萧萧叶打窗。","阮籍作官都为酒，不须分别恨南邦。"]},{"t":"雨过","f":"七言律诗","c":["东南流注已鸣涧，西北霏微仅敛尘。","人意共怀艰食病，天公那有不仁人。","云移已分贫无福，雩应方知社有神。","田里相望无一舍，终年苦乐会须匀。"]},{"t":"驾幸亲贤宅赠随驾诸公","f":"七言律诗","c":["日日南风夜气烦，一声鸣䟆万人看。","禁沟飞水清黄道，凉殿分冰遍从官。","急雨未成昏观阙，微飙稍觉泛和銮。","相看挥汗尘埃里，散发何人旧不冠。"]},{"t":"临江萧氏家宝堂","f":"七言律诗","c":["高人不解作生涯，唯有中堂书五车。","竹简多于孔氏壁，牙签新似邺侯家。","田园岂是子孙计，青紫今为里巷誇。","富贵早知皆有命，君应未厌十年赊。"]},{"t":"南斋独坐","f":"五言律诗","c":["独坐南斋久，忘家似出家。","香烟秾作穗，茶面结成花。","细竹才通径，长松初有槎。","往还真断绝，一一数归鸦。"]},{"t":"南堂新游花坛二首 其二","f":"五言律诗","c":["老木不忍伐，横枝宜少除。","根茎渐有托，雨露稍分馀。","生意初无损，开花终自如。","他年诸草木，成就此幽居。"]},{"t":"南堂新游花坛二首 其一","f":"五言律诗","c":["乱竹侵红药，病花羞晚春。","移根近谈笑，得土长精神。","荣悴非由尔，芬芳止为人。","庭西井泉好，汲灌每躬亲。"]},{"t":"城中牡丹推高皇庙园迟适联骑往观归报未开戏作","f":"七言律诗","c":["汉庙名园甲颍昌，洛川珍品重姚黄。","雨馀往看初疑晚，春尽方开自不忙。","争占一时人意速，养成千叶化功长。","老人终岁关门坐，花落花开已两忘。"]},{"t":"城南访张恕","f":"七言律诗","c":["事似棼丝拨不开，秋随脱叶暗相催。","城南绿野宜幽步，水北红尘漫作堆。","赤枣青瓜报丰熟，黄鸡白酒劝徘徊。","此中真有醇风在，一亩何年斸草莱。"]},{"t":"复次烟字韵答黄大临庭坚见寄二首 其一","f":"七言律诗","c":["水竹遮藏自一川，日高茅屋始炊烟。","犬牙舂米新秋后，麦粒烝茶欲社天。","冠盖只今成弃物，杉松他日记栽年。","定应笑我劳生在，卯睡闻呼衣为颠。"]},{"t":"复次烟字韵答黄大临庭坚见寄二首 其二","f":"七言律诗","c":["十载劳思寤寐间，新诗态度比云烟。","清风吹我无千里，明月随人共一天。","归去林泉应避暑，北征道路恐经年。","与君共愧知时鹤，养子先依黑柏颠。"]},{"t":"复次韵","f":"七言律诗","c":["滕王阁在谁携手，徐孺湖宽可放情。","楚客解书南国恨，秦筝助发上林莺。","系匏独负杯中物，拥鼻知逢洛下生。","问得长须添梦想，蓬窗灯火达天明。"]},{"t":"将之绩溪梦中赋泊舟野步","f":"五言律诗","c":["扁舟逢野岸，试出步崇冈。","山转得幽谷，人家馀夕阳。","被畦多绿茹，堆屋剩黄粱。","深羡安居乐，谁令志四方。"]},{"t":"将归二首 其二","f":"五言律诗","c":["为客不满岁，还家见两孙。","遥知临竹户，相对引瓢樽。","老罢那嫌瘦，心宽尚喜存。","风波随处有，何幸免惊奔。"]},{"t":"将归二首 其一","f":"五言律诗","c":["久客初何事，言归似有名。","腾腾且随俗，落落竟无成。","病苦医犹厌，囊空身自轻。","家人惊别后，无限白须生。"]},{"t":"将至南京雨中寄王巩","f":"七言律诗","c":["河牵一线流不断，雨散千丝卷却来。","烟际横桥村十里，船中倦客酒三杯。","老年转觉脾嫌湿，世路早令心似灰。","赖有故人怜寂寞，系舟待我久徘徊。"]},{"t":"将使契丹九日对酒怀子瞻兄并示坐中","f":"七言律诗","c":["黄华已向初旬见，白酒相携九日尝。","萸少一枝心自觉，舂同斗粟味终长。","兰生庭下香时起，玉在人前坐亦凉。","千里使胡须百日，暂将中子治书囊。"]},{"t":"将拆旧屋权住西廊","f":"七言律诗","c":["平生未有三间屋，今岁初成百步廊。","欲趁闲年就新宅，不辞暑月卧斜阳。","修篁已谢前人种，甘井何妨众口尝。","奔走从来成底事，安居到处漫为乡。"]},{"t":"将移绩溪令","f":"七言律诗","c":["坐看酒垆今五年，恩移岩邑稍西还。","他年贫富随天与，何日身心听我閒。","山栗似拳应自饱，蜂糖如土不须悭。","仲卿意向桐乡好，身后烝尝亦此间。"]},{"t":"故成都尹陆介夫挽词","f":"七言律诗","c":["拥节西南未一年，凄凉道路泣东辕。","蜀都富乐真当惜，民事艰难谁复论。","白马何人趋远日，青刍盈束更无言。","异时归去逢遗老，空听咨嗟述旧恩。"]},{"t":"故枢密签书赠正议大夫王彦霖挽词二首 其二","f":"五言律诗","c":["倾盖晚相亲，东西省户邻。","听君占谏草，继我出词纶。","京尹声初浃，枢廷迹尚新。","邯郸炊未熟，荣谢隔逡巡。"]},{"t":"故枢密签书赠正议大夫王彦霖挽词二首 其一","f":"五言律诗","c":["试吏有能名，升台擅直声。","雄飞极九载，修路止三城。","壮志方凌厉，遗书忽叹惊。","老人殊可念，白首泣新茔。"]},{"t":"春日耕者","f":"七言律诗","c":["阳气先从土脉知，老农夜起饲牛饥。","雨深一尺春耕利，日出三竿晓饷迟。","妇子同来相妩媚，乌鸢飞下巧追随。","纷纭政令曾何补，要取终年风雨时。"]},{"t":"春尽","f":"七言律诗","c":["春风过尽百花空，燕坐笙箫起灭中。","树影连天开翠幕，鸟声入耳当歌童。","楞严十卷几回读，法酒三升是客同。","试问邻僧行乞在，何人闲暇似衰翁。"]},{"t":"春阴","f":"七言律诗","c":["春后谁令百日阴，雨淫风横两相侵。","天公未有惜花意，野老空存念麦心。","共怪丛筠亦黄落，终怜老桧独萧森。","过中不克阳安在，夏旱前知未易禁。"]},{"t":"春旱弥月郡人取水邢山二月五日水入城而雨","f":"七言律诗","c":["春旱时闻孽火然，邢山龙老不安眠。","麦生三寸未覆垄，雨过一犁初及泉。","深愧贫民饥欲死，可怜肉食坐称贤。","南斋遗老知尤幸，汤饼黄齑又一年。"]},{"t":"春深三首 其三","f":"七言律诗","c":["偶有茅檐潩水阴，近依城市浅非深。","幽居每自比陈寔，古学何人贵杜林。","邻父时来陪小饮，儿曹颇解续微吟。","前年仅了春秋传，后有仁人知我心。"]},{"t":"春深三首 其二","f":"七言律诗","c":["小园松竹有清阴，懒病从兹日益深。","醉客满堂惭北海，野僧同社忆东林。","逢人问道空长啸，久客思归尚越吟。","三十年前诵圆觉，年来虽老解安心。"]},{"t":"春深三首 其一","f":"七言律诗","c":["郊原红绿变青阴，闭户不知春已深。","稍喜荒畦添野荠，坐看新竹补疏林。","帘中飞絮萦残梦，窗外啼莺伴独吟。","欲听楞严终懒出，道人知我祖无心。"]},{"t":"柳子玉郎中挽词二首 其一","f":"七言律诗","c":["晚岁抽身尘土中，灊山仍乞古仙宫。","羞将白发随冯叟，欲就丹砂继葛洪。","龙虎未能留物化，芭蕉久已悟身空。","骚人欲作招魂赋，蝉蜕疑非世俗同。"]},{"t":"柳子玉郎中挽词二首 其二","f":"七言律诗","c":["新诗锦绣烂成编，醉墨龙蛇洒未乾。","共首卜居空旧约，宛丘携手忆馀欢。","风流可见身如在，乡国全归意所安。","行到都门送君处，长河清泪两汍澜。"]},{"t":"柳湖久无水怅然成咏","f":"七言律诗","c":["平湖水尽起黄埃，惟有长堤万万栽。","病鹤摧颓沙上舞，游人寂寞岸边回。","秋风草木初摇落，日暮樵苏自往来。","更试明年春絮起，共看飞雪乱成堆。"]},{"t":"洗竹","f":"七言律诗","c":["寒甚南轩竹半黄，晚抽旱笋杂榛荒。","不嫌毒手千竿尽，稍放清风八月凉。","短彗只堪除粪壤，新萌会看伏牛羊。","扶持造化须人力，早听人言布麦糠。"]},{"t":"省事","f":"七言律诗","c":["早岁读书无甚解，晚年省事有奇功。","自许平生初不错，人言毕竟两皆空。","空中有实何人见，实际心知与佛同。","烦恼消除病亦去，闭门便了此生中。"]},{"t":"秋后即事","f":"七言律诗","c":["苦热真疑不复凉，火流渐见迫西方。","清风一夜吹茅屋，竹簟今朝避石床。","露湿中庭菊含蕊，水浮西浦稻生芒。","秋成得饱家家事，莫笑农夫喜欲狂。"]},{"t":"秋社分题","f":"五言律诗","c":["天公闵贫病，雨止得丰穰。","南亩场功作，东家社酒香。","分均思孺子，归遗笑东方。","肯劝拾遗住，休嫌父老狂。"]},{"t":"秋雨","f":"七言律诗","c":["禾田已熟畏愁霖，积潦欲乾泥尚深。","一雨一凉秋向晚，似安似病老相侵。","人间有尽皆归物，世外无生赖有心。","要觅尘埃不到处，一灯相照夜愔愔。"]},{"t":"种兰","f":"七言律诗","c":["兰生幽谷无人识，客种东轩遗我香。","知有清芬能解秽，更怜细叶巧凌霜。","根便密石秋芳早，丛倚修筠午荫凉。","欲遣蘼芜共堂下，眼前长见楚词章。"]},{"t":"种花二首 其二","f":"五言律诗","c":["筑室少闲地，种花能几畦。","松筠旧满眼，桃李渐成蹊。","无计通湖水，长思种藕泥。","幽怀终不惬，拄杖出城西。"]},{"t":"种花二首 其一","f":"五言律诗","c":["筑室力已尽，种花功尚疏。","山丹得春雨，艳色照庭除。","末品何曾数，群芳自不如。","今秋接千叶，试取洛人馀。"]},{"t":"种菜","f":"七言律诗","c":["久种春蔬旱不生，园中汲水乱瓶罂。","菘葵经火未出土，僮仆何朝饱食羹。","强有人功趋节令，怅无甘雨困耘耕。","家居闲暇厌长日，欲看年华上菜茎。"]},{"t":"绝胜亭","f":"七言律诗","c":["夜郎秋涨水连空，上有虚亭缥缈中。","山满长天宜落日，江吹旷野作惊风。","爨烟惨淡浮前浦，渔艇纵横逐钓筒。","未省岳阳何似此，应须子细问南公。"]},{"t":"胡长史祠堂","f":"七言律诗","c":["白首青衫仍隐居，晚抛环堵就安舆。","生刍忽改烝尝地，函丈空悲讲解馀。","弟子玙璠相照耀，儿孙松桂共扶疏。","我来恨不瞻遗老，空怪乡邻尽读书。"]},{"t":"荥阳唐高祖太宗石刻像","f":"五言律诗","c":["谁言肤寸像，胜力妙人天。","欲疗众生病，阴扶济世贤。","身微须覆护，眼净照几先。","岂为成功报，犹应历劫缘。"]},{"t":"追尊皇太后挽词二首 其二","f":"五言律诗","c":["德美钟岐嶷，荣华倍感伤。","一时朝野恨，百世本支长。","出祖悲无憾，因山俭有光。","他年过嵩洛，望拜裕陵旁。"]},{"t":"追尊皇太后挽词二首 其一","f":"五言律诗","c":["月缺年何久，龙飞事一新。","追崇名号正，同袝礼容均。","凤翣低迎日，龙輴细起尘。","都人知舜孝，拥绋尽沾巾。"]},{"t":"送元老西归","f":"七言律诗","c":["昼锦西归及早秋，十年太学为亲留。","读诗俛就当年说，答策甘从下第收。","莫嫌簿领妨为学，从此文章始自由。","家有吏师遗躅在，当令耆旧识风流。"]},{"t":"送文太师致仕还洛三首 其一","f":"七言律诗","c":["国老无心岂为身，五年朝谒慰簪绅。","元臣事业通三世，旧将威名服四邻。","遍阅后生真有道，欲谈前事恐无人。","比公惟有凌云桧，岁岁何妨雨露新。"]},{"t":"送文太师致仕还洛三首 其二","f":"七言律诗","c":["齐鲁元勋古太师，寂寥千载恐无之。","昔归暂缩经邦手，复起还当问道时。","入谒何曾须掖侍，到家依旧拥旌麾。","孔公灵寿固应在，秋晚香山访佛祠。"]},{"t":"送文太师致仕还洛三首 其三","f":"七言律诗","c":["西都风物汉唐馀，天作溪山养退居。","盈尺好花扶几杖，拂天修竹倚庭除。","白头伴侣谁犹健，率意壶飧久已疏。","我欲试求三亩宅，从公它日赋归欤。"]},{"t":"送毛滂斋郎","f":"七言律诗","c":["先志承颜善养亲，束装骑马试为臣。","酒肠天予浑无敌，诗律家传便出人。","拥鼻高吟方自得，折腰奔走渐劳神。","归来一笑须勤取，花发陈吴二月春。"]},{"t":"送王宗望郎中赴河东漕","f":"七言律诗","c":["春初戎马掠河壖，属国仓皇不解鞍。","未免驱民馈边食，旋闻奉使辍郎官。","年高转觉精神胜，虑稳要令事业安。","持节近看葱岭雪，拥裘应惯雁门寒。"]},{"t":"送王适徐州赴举","f":"七言律诗","c":["送别江南春雨淫，北方谁是子知音。","性如白玉烧犹冷，文似朱弦叩愈深。","万里同舟宽老病，一杯分袂发悲吟。","明年榜上看名姓，杨柳春风正似今。"]},{"t":"送任师中通判黄州","f":"七言律诗","c":["一别都门今五年，剧谈精壮故依然。","厌居巴蜀千山底，决住荆河十顷田。","老去功名无意取，身闲诗笔更能专。","黄州无事聊须饮，世俗方今自足贤。"]},{"t":"送吕由庚推官得替还洛中二首 其一","f":"七言律诗","c":["君家相国旧元勋，凛凛中丞继后尘。","谈笑二年同幕府，风流一倍愈它人。","南都去后少佳客，西洛归来多老臣。","我亦宦游无久意，它年松竹许相邻。"]},{"t":"送吕由庚推官得替还洛中二首 其二","f":"七言律诗","c":["洛水留人一向乾，雪泥溢路十分寒。","送行我岂无樽酒，多难君知久鲜欢。","回首祇应怜老病，凌风争看试轻翰。","到家定见嵩阳老，问我衰迟未解官。"]},{"t":"送吕希道少卿知滁州","f":"七言律诗","c":["长怪名卿亦坐曹，忽乘五马列旌旄。","才多莫厌官无事，郡小不妨名自高。","庶子定应牵赋咏，醉翁聊复继游遨。","试寻苦战清流下，要识经纶帝业劳。"]},{"t":"送张恕朝奉南京签判二首 其一","f":"七言律诗","c":["楚蟹吴柑初著霜，梁园官酒试羔羊。","老如计相非无齿，清似留侯未却粮。","杖屦稍通宾客过，殽蔬要遣子孙尝。","诏书委曲如公意，幕府新除朱绂郎。"]},{"t":"送张恕朝奉南京签判二首 其二","f":"七言律诗","c":["朱绂还家罢倚门，留都无事最宜亲。","下车趋走惊邻舍，决狱平反慰老人。","相见只今多邂逅，旧游他日半埃尘。","何年重起扁舟兴，会作东湖十日宾。"]},{"t":"送李宪司理还新喻","f":"五言律诗","c":["采芹芹已老，浴沂沂尚寒。","蒯缑长叹息，苜蓿正阑干。","黄卷忘忧易，青衫行路难。","归耕未有计，且复调闲官。"]},{"t":"送杜介归扬州","f":"七言律诗","c":["扬州繁丽非前世，城郭萧条却古风。","尚有花畦春雨后，不妨水调月明中。","东都甲第非嫌汝，北牖羲皇自属翁。","清洛放船经月事，急先鶗鴂绕芳丛。"]},{"t":"送陈安期都官出城马上","f":"七言律诗","c":["城中二月不知春，唯有东风满面尘。","归意已随行客去，流年惊见柳条新。","簿书填委休何日，学问榛芜愧古人。","一顷稻田三亩竹，故园何负不收身。"]},{"t":"送侄迈赴河间令","f":"五言律诗","c":["老去那堪用，恩深未敢归。","谁能告民病，一一指吾非。","尔赴河间治，无嫌野老讥。","仍将尺书报，勿复问从违。"]},{"t":"送林子中安厚卿二学士奉使高丽二首 其一","f":"七言律诗","c":["东夷从古慕中华，万里梯航今一家。","夜静双星先渡海，风高八月自还槎。","鱼龙定亦知忠信，象译何劳较齿牙。","屈指归来应自笑，手持玉帛赐天涯。"]},{"t":"送林子中安厚卿二学士奉使高丽二首 其二","f":"七言律诗","c":["官是蓬莱海上仙，此行聊复看桑田。","鲲移鹏徙秋帆健，潮阔天低晓日鲜。","平地谁言无崄岨，仁人何处不安全。","但将美酒盈船去，多作新诗异域传。"]},{"t":"送青州签判俞退翁致仕还湖州","f":"七言律诗","c":["不作清时言事官，海邦那复久盘桓。","早依莲社尘缘少，新就草堂归计安。","富贵暂时朝露过，江山故国水精寒。","宦游从此知多事，收取《楞伽》静处看。"]},{"t":"送姜司马","f":"七言律诗","c":["七岁立谈明主前，江湖晚节弄渔船。","斗鸡谁识城东老，丧马方知塞上贤。","生计未成归去咏，草书时发醉中颠。","当年不解看齐物，气踊如山谁见怜。"]},{"t":"送逊监淮西酒并示诸任二首 其二","f":"七言律诗","c":["淮西留滞昔经年，唯有诸任时往还。","炊黍留宾不嫌陋，借书度日免长闲。","归来潩水无人问，梦绕伊家古桧间。","二老旧游唯我在，后生谁复识苍颜。"]},{"t":"送逊监淮西酒并示诸任二首 其一","f":"七言律诗","c":["畴昔南迁海上雷，艰难唯与汝同来。","再从龙尉茅丛底，旋卜云桥荔子堆。","相与闭门寻旧学，谁言复出理官醅。","乘田委吏先师事，莫学陶翁到即回。"]},{"t":"送饶州周沃秀才免解","f":"五言律诗","c":["少年工作赋，中岁复穷经。","骥老终知道，剑埋新发硎。","束装邻里助，答策友朋听。","还似临淄贡，随风起北溟。"]},{"t":"送唐觐","f":"七言律诗","c":["溪上幽居少四邻，西家幸有著书人。","经年食菜谁怜瘦，终日题诗自不贫。","身在江湖钓竿地，心驰兰会战车尘。","此行便有飞腾处，笑杀年来老病身。"]},{"t":"送贾讷朝奉通判眉州","f":"七言律诗","c":["归念长依落日边，壶浆今见逆新官。","声传已觉讴歌遍，身到前知政令宽。","民病贤人来已暮，时平蜀道本无难。","明年我欲修桑梓，为赏庭前荔子丹。"]},{"t":"送钱承制赴广东都监","f":"七言律诗","c":["家声远继河西守，游宦多便岭外官。","南海无波闲斗舸，北堂多暇得羞兰。","忽闻常棣歌离索，应寄寒梅报好安。","它日扁舟定归计，仍将犀玉付江湍。"]},{"t":"送钱婺州纯老","f":"七言律诗","c":["桃花汴水半河流，已作南行第一舟。","倦报朝中言啧乱，喜闻淮上橹咿呦。","平时答策词无枉，此去为邦学更优。","自古东阳足贤守，请君重赋沈公楼。"]},{"t":"送顿起及第还蔡州","f":"七言律诗","c":["诏书京辅起沉沦，岁贡仍居第一人。","不愧得官名暂屈，自誇对策语深淳。","读书饱足终无厌，从宦奔驰自此新。","我去淮阳今不久，邻邦时得问音尘。"]},{"t":"送高士敦赴成都兵钤","f":"七言律诗","c":["扬雄老病久思归，家在成都更向西。","邂逅王孙驰驿骑，丁宁父老问耕犁。","禅房何处不行乐，壁像君家有旧题。","德厚不妨三世将，时平空见万夫齐。"]},{"t":"送高安罗令审礼","f":"七言律诗","c":["一邑忧劳水旱中，牛刀闲暇似无功。","政成仍喜新蚕熟，归去还将旧橐空。","清白久闻誇父老，沉埋谁为诉诸公。","谪居长恨交游少，怅望肩舆又欲东。"]},{"t":"送梁交供知莫州","f":"七言律诗","c":["猛士当令守四方，中原诸将近相望。","一樽度日空閒暇，千骑临边自激昂。","谈笑定先降虏使，诗书仍得靖戎行。","君看宿将何承矩，安用摧锋百战场。"]},{"t":"送傅宏著作归觐待观城阙","f":"七言律诗","c":["胶西前辈郑康成，千载遗风及后生。","旧学诗书儒术富，兼通法律吏能精。","还家綵服频为寿，得邑河壖喜有兵。","民事近来多迫促，弦歌聊试武城声。"]},{"t":"送董扬休比部知真州","f":"五言律诗","c":["奏课西南最，分符江海冲。","往来观惠术，蟠错试馀锋。","文字从堆案，樽罍强解容。","金山只隔水，时复听晨钟。"]},{"t":"送蒋夔赴代州教授","f":"七言律诗","c":["忆游太学十年初，犹见胡公岂弟馀。","遍阅诸生非有道，最怜能赋似相如。","青衫共笑方持板，白发相看各满梳。","暂免百忧趋长吏，勉调三寸事新书。"]},{"t":"送道士杨见素南游","f":"七言律诗","c":["黄河春涨入隋沟，往意随波日夜流。","万里寻山如野鹤，一身浮水似轻鸥。","湖风送客那论驿，岳寺留人暗度秋。","迟子北归来见我，携琴委曲记深幽。"]},{"t":"送韩祗严户曹得替省亲成都","f":"七言律诗","c":["宦游东土暂相依，政役频烦会合稀。","每恃详明容老病，不堪羁旅送将归。","思亲道路宁论远，入蜀山河渐觉非。","我有旧庐江水上，因君聊复梦魂飞。"]},{"t":"送颜复赴阙","f":"七言律诗","c":["箪瓢未改安贫性，凫绎犹传直道馀。","不见失官愁戚戚，但闻高卧起徐徐。","居中旧厌军容讲，补外仍遭城旦书。","此去将身置何许，秋风未免忆鲈鱼。"]},{"t":"送霸州司理翟曼","f":"五言律诗","c":["大梁能赋客，边郡系囚曹。","官职不相称，声名终自高。","试观为吏苦，应过读书劳。","努力事初宦，尺丝无厌缫。"]},{"t":"闻子瞻习射","f":"七言律诗","c":["旧读兵书气已振，近传能射喜征鼖。","手随乐节宁论中，箭作鸱声不害文。","力薄仅能胜五斗，才高应自敌三军。","良家六郡传真法，马上今谁最出群。"]},{"t":"闻子瞻重游南山","f":"七言律诗","c":["终南重到已春回，山木缘崖绿似苔。","谷鸟鸣呼嘲独往，野人笑语记曾来。","定邀道士弹鸣鹿，谁与溪堂共酒杯。","应有新诗还寄我，与君和取当游陪。"]},{"t":"闻王巩还京会客剧饮戏赠","f":"七言律诗","c":["闻君归去便招呼，笑语不知清夜徂。","结束佳人试银甲，留连狂客恼金吾。","烛花零落玉山倒，诗笔攲斜翠袖扶。","暂醉何年依锦瑟，东斋还复卧氍毹。"]},{"t":"闻京东有道人号贺郎中者唐人也其徒有识之者作诗寄之","f":"七言律诗","c":["贺老稽山去不还，镜湖独棹钓鱼船。","南来太白寻无处，却作郎官又几年。","岱下迎鸾惊典谒，蒙山施药悯耕田。","试穷脚力追行迹，亦使今生识地仙。"]},{"t":"除夕","f":"五言律诗","c":["患难思年改，龙钟惜岁徂。","关河先垄远，天地小臣孤。","吾道凭温酒，时情付拥炉。","南荒足妖怪，此日谩桃符。"]},{"t":"除日","f":"七言律诗","c":["年年最后饮屠酥，不觉年来七十馀。","十二春秋新罢讲，五千道德适亲书。","木经霜雪根无蠹，船出风波载本虚。","自怪多年客箕颍，每因吾党赋归欤。"]},{"t":"除日二首 其二","f":"七言律诗","c":["七十四年明日是，三千里外未归人。","酒篘泉涌如迎节，诗句云生喜见春。","贺客不来知我病，邻家窃语笑吾真。","时人莫作乐天看，燕坐端能毕此身。"]},{"t":"除日二首 其一","f":"七言律诗","c":["屠苏末后不辞饮，七十四人今自希。","筋力明年应更减，诚心忧世久知非。","脾寒服药近方验，风痹经冬势渐微。","得罪明时归已晚，此生此病任人讥。"]},{"t":"除夜","f":"五言律诗","c":["老去不自觉，岁除空一惊。","深知无得丧，久已罢经营。","黄卷讥前失，清樽借后生。","何年遂疏懒，伏腊任躬耕。"]},{"t":"除夜二首 其二","f":"五言律诗","c":["七十三年客，相从尚几年。","西方他日事，东鲁一经传。","渐解平生缚，初安半夜禅。","纷纷争夺际，何意此心全。"]},{"t":"除夜二首 其一","f":"五言律诗","c":["年年赋除夜，一赋一衰残。","家有三斗酿，春馀半月寒。","鸡豚不改旧，邻里自相欢。","元日应无客，萧然不著冠。"]},{"t":"除夜会饮南湖怀王巩","f":"七言律诗","c":["岁晚城东故相家，夜听帘外落琼花。","醉眠东阁银釭暗，起视中庭风竹斜。","鲁酒近来无奈薄，秦筝别后苦闻誇。","思君倦对空陂饮，归去纷如日莫鸦。"]},{"t":"食鸡头","f":"七言律诗","c":["风开芡觜铁为须，斧斫沙磨旋付厨。","细嚼兼收上池水，徐咽还成沧海珠。","佳客满堂须一斗，闲居赖我近平湖。","多年不到会灵沼，气味宛然初不殊。"]},{"t":"食菱","f":"五言律诗","c":["野沼涨清泉，乌菱不直钱。","蟹肥螯正满，石破髓初坚。","节物秋风早，樽罍夜月偏。","令人思淮上，小舫藕如椽。"]},{"t":"食樱笋二首 其二","f":"七言律诗","c":["林竹抽萌不忍挑，谁家盈束伴晨樵。","箨龙似欲号无罪，食客安知惜后凋。","不愿盐梅调鼎味，姑从律吕应箫韶。","林间老死虽无用，一试冬深雪到腰。"]},{"t":"食樱笋二首 其一","f":"七言律诗","c":["一旱经春草木焦，朱樱结子独盈条。","盘中宛转明珠滑，舌上逡巡绛雪消。","仰嗫佳人露犹湿，偷衔啼鸟语尤娇。","南方荔子争先后，羞见炎风六月烧。"]},{"t":"乘小舟出筠江二首 其一","f":"七言律诗","c":["短舫漂浮真似叶，小蓬低浅仅如巢。","幽吟但觉山川走，困睡不知风雨交。","红饭白醪供醉饱，青蓑黄箬可缠包。","一竿鹤发他年事，万斛龙骧任见嘲。"]},{"t":"乘小舟出筠江二首 其二","f":"七言律诗","c":["宦游欲学林间鹊，每到新年旋叠巢。","蓬箬笼船聊似屋，渔樵把臂便成交。","不妨袖里携诗卷，尚可床头置药包。","《古史》欲成身愈困，客来未免答讥嘲。"]},{"t":"唐修撰义问挽词二首 其二","f":"五言律诗","c":["我返南荒日，君临旧许初。","笑谈宽老病，旌旆拥茅庐。","酒盏开虽数，溪堂到尚疏。","谁言生死隔，近在浃旬馀。"]},{"t":"唐修撰义问挽词二首 其一","f":"五言律诗","c":["家风台柏老，遗直故依然。","节见南迁后，神凝未瞑前。","临民旧有法，训子适成篇。","九转今犹在，参同岂妄传。"]},{"t":"留守与宾客会开元龙兴寺观灯余有故不预中夜登南城","f":"七言律诗","c":["灯引双旌万点红，倾城车马在城东。","使君行乐人人共，倦客安眠夜夜同。","梦想笑谈倾满坐，卧闻歌筦逐春风。","三更试上南楼看，无限繁星十里中。"]},{"t":"留滞高安四年有馀忽得信闻当除官真扬间偶成小诗书于屋壁","f":"七言律诗","c":["数间茅屋久蹉跎，四见秋风入薜萝。","北棹偶然追雁羽，南公谁复伴渔蓑。","三年贾傅惊吾老，九岁刘郎愧尔多。","此去仍家江海上，不妨一叶弄清波。"]},{"t":"病中郭尉见访","f":"七言律诗","c":["偶成三日寒兼热，知是多闻力未全。","却问药王求妙剂，惭非摩诘已虚圆。","劳公强说修行渐，顾我方为病垢缠。","应是床头有新酒，欲邀佳客故留连。"]},{"t":"病后","f":"七言律诗","c":["一经寒热攻骸骨，正似兵戈过室庐。","柱木支撑终未稳，筋皮收拾久犹疏。","芭蕉张王要须朽，云气浮游毕竟虚。","赖有衣中珠尚在，病中点检亦如如。"]},{"t":"病后白发","f":"五言律诗","c":["枯木自少叶，不堪经晓霜。","病添衰发白，梳落细丝长。","筋力从凋朽，肝心罢激昂。","势如秋后雨，一度一凄凉。"]},{"t":"病退","f":"七言律诗","c":["冷枕单衣小竹床，卧闻秋雨滴心凉。","此间本净何须洗，是病皆空岂有方。","示疾维摩元自在，放身南岳离思量。","病根欲去真元在，中夜梦游何有乡。"]},{"t":"病愈二首 其二","f":"五言律诗","c":["病退日身轻，身轻心转清。","山空流水上，海静寸灯明。","朝市谁留住，林泉自不行。","筠溪惭丐士，流荡过平生。"]},{"t":"病愈二首 其一","f":"五言律诗","c":["学道虽云久，沉疴竟未除。","炎烝度三伏，晻暧觉中虚。","嘉谷不自长，荒榛终费锄。","何辞用兰石，梨枣得扶疏。"]},{"t":"竞渡","f":"七言律诗","c":["史君欲听榜人讴，一夜江波拍岸流。","父老不知招屈恨，少年争作弄潮游。","长鲸破浪聊堪比，小旆逆风殊未收。","角胜争先非老事，凭栏寓目思悠悠。"]},{"t":"索居三首 其三","f":"五言律诗","c":["许蔡古邻国，风烟相杂和。","萧然客舍静，不愿主人过。","野荠春将老，淮鱼夏渐多。","街南病居士，有酒对酣歌。"]},{"t":"索居三首 其二","f":"五言律诗","c":["平生亦何事，十载苦颠隮。","梦崄曾非崄，觉迷终不迷。","客居兼壮子，别久愧良妻。","稍讶音书阔，春阴道路泥。"]},{"t":"索居三首 其一","f":"五言律诗","c":["索居非谪地，垂老更穷途。","去住看人意，幽忧赖我无。","小园花草秽，陋巷犬羊俱。","近觉根尘离，忘言日益愚。"]},{"t":"蚕麦","f":"五言律诗","c":["春旱麦半熟，蚕收仅十分。","不忧无饼饵，已幸有襦裙。","造化真怜汝，耕桑不谩勤。","经过话关陕，贫病不堪闻。"]},{"t":"蚕麦二首 其二","f":"七言律诗","c":["三界人家多鲜福，一时蚕麦得难兼。","锄耰已愧非吾力，汤火尤惊取不廉。","贵客争誇火浣布，贫家粗有水精盐。","薄衫冷面消长夏，扪腹当知百不堪。"]},{"t":"蚕麦二首 其一","f":"七言律诗","c":["疏慵自分人嫌我，贫病可怜天养人。","蚕眠已报冬裘具，麦熟旋供汤饼新。","撷桑晓出露濡足，拾穗暮归尘满身。","家家辛苦大作社，典我千钱追四邻。"]},{"t":"诸子将筑室以画图相示三首 其三","f":"七言律诗","c":["积因得果通三世，临老长闲自一时。","久尔观心终未悟，偶然见道了无疑。","南迁北返吾何病，片瓦尺椽天与期。","自断此生今已矣，世间何物更如斯。"]},{"t":"诸子将筑室以画图相示三首 其二","f":"七言律诗","c":["旧庐近已借诸子，新宅分甘临老时。","万里松楸终独往，四方兄弟亦何疑。","竹间疏户幽人到，林上长松野鹤期。","已觉高轩惭卫赐，可怜黄犬哭秦斯。"]},{"t":"诸子将筑室以画图相示三首 其一","f":"七言律诗","c":["还家卜筑初无地，随分经营似有时。","多斫修篁终未忍，略存古柏更无疑。","画图且作百间计，入室犹应三岁期。","得到安居真老矣，一生歌哭任于斯。"]},{"t":"读传灯录示诸子","f":"七言律诗","c":["大鼎知难一手扛，此心已自十年降。","旧存古镜磨无力，近喜三更月到窗。","早岁文章真自累，一生忧患信难双。","从今父子俱清净，共说无生或似庞。"]},{"t":"逢章户掾赴澧州","f":"五言律诗","c":["江船不厌窄，船窄始宜行。","风里长先过，滩头一倍轻。","迎亲无恶处，禄养胜躬耕。","澧上春兰早，犹堪吊屈生。"]},{"t":"陪毛君游黄仙观","f":"七言律诗","c":["李叟仙居仍近市，黄公道院亦依城。","定应昔日山林地，未有今时鸡犬声。","白鹤翻飞终不返，黄冠憔悴只躬耕。","试从车骑寻遗迹，恐有居人解养生。"]},{"t":"高邮赠别杜介供奉","f":"七言律诗","c":["淮南鱼米年年贱，直便归休无俸钱。","锦背图书何益事，尘生弦筦正参禅。","逢人未废一樽酒，送客长随百里船。","世上得如君自在，不须开府事开边。"]},{"t":"堂成不施丹雘唯纸窗水屏萧然如野人之居偶作","f":"七言律诗","c":["高栋虚窗五月凉，客来扫地旋焚香。","白云低绕明月观，涨海东流清暑堂。","病久渴心思沆瀣，梦回馀念属潇湘。","老人夫妇修行久，此处从今是道场。"]},{"t":"寄张芸叟","f":"词","c":["老矣张芸叟，亲编乐府词。","才高君未觉，手战我先衰。","点?旧无对，吟哦今与谁。","十年酬唱绝，欢喜得新诗。"]},{"t":"寄题江涣长官南园茅斋","f":"七言律诗","c":["白发辛勤困小邦，尘劳坐使壮心降。","河阳罢后成南圃，彭泽归来卧北窗。","畦畔草生亲荷锸，床头酒熟自倾缸。","因君遣我添归兴，旧有茅茨濯锦江。"]},{"t":"寄题陈宪郎中竹轩","f":"七言律诗","c":["家有修篁绿满轩，趋庭诗礼旧忘言。","凌霜自得良朋友，过雨时添好子孙。","试剪轻筠扶野步，旋收凉叶煮清樽。","风流共道胜桑梓，邻里何妨种百根。"]},{"t":"寄题武陵柳氏所居二首 其一 天真堂","f":"七言律诗","c":["宦游阅尽山川胜，归老方知气味真。","歌哭不移身自稳，往还无间语尤亲。","永怀前辈无因见，犹喜诸郎有此人。","千岁展禽风未改，不加雕琢世称珍。"]},{"t":"寄题武陵柳氏所居二首 其二 康乐楼","f":"七言律诗","c":["邑居欲尽溪山好，不作层楼无奈何。","岩谷满前收蜡屐，漪涟极目卷渔蓑。","安心已得安身法，乐土偏令乐事多。","千里筠阳犹静治，还家一笑定无他。"]},{"t":"寄题赵㞦承事戏綵堂","f":"七言律诗","c":["春晚安舆遍浙东，永嘉别乘喜无穷。","橐装已笑分诸子，吏道何劳问薛公。","堂上寿樽诸掾集，室中禅论衲僧通。","兴阑却返林泉去，幕府长留孝弟风。"]},{"t":"寄题蒲传正学士阆中藏书阁","f":"七言律诗","c":["朱栏碧瓦照山隈，竹简牙签次第开。","读破文章随意得，学成富贵逼身来。","诗书教子真田宅，金玉传家定粪灰。","更把遗编观得失，君家旧物岂须猜。"]},{"t":"得告家居次韵贡父见寄","f":"七言律诗","c":["君恩赐告许归来，雨后中庭有绿苔。","起问日高三丈久，卧闻车过九门开。","泥封连日传新语，腕脱知君有轶才。","待得晴乾追后乘，未应尘土热如灰。"]},{"t":"曹郎子文赴山阳令","f":"七言律诗","c":["囊空口众不堪闲，却喜平生得细论。","鹤发进封偿旧德，彩衣听讼勉平反。","楚风剽疾观新政，浙水萧条咏旧恩。","记取老人临别语，茶瓢霜后早相存。"]},{"t":"梦中咏西湖","f":"七言律诗","c":["谁凿西湖十里中，扁舟载酒飏轻风。","草木蕃滋百事足，寒暄淡薄四时同。","东邻适与吾庐便，西岸遥将岳麓通。","闲游草草无人识，竹杖藤鞋一老翁。"]},{"t":"移竹","f":"五言律诗","c":["墙阴竹蒙密，板筑念相妨。","欲补园东缺，欣乘雨后凉。","三年生笋遍，一径引风长。","但恐翁弥老，筇枝懒复将。"]},{"t":"移陈州牡丹偶得千叶二本喜作","f":"七言律诗","c":["小圃初开清潩岸，名花近取宛丘城。","争言千叶根难认，忽发双葩眼自明。","谪堕神仙终不俗，飞来鸾凤有馀清。","细锄瓦砾除荆棘，未可令齐众草生。"]},{"t":"章氏郡君挽词","f":"七言律诗","c":["冯唐垂老郎潜后，李白风流罢直馀。","解组同归荣故国，剖符仍得奉安舆。","家声未替三公旧，葬客应倾数郡车。","德映闺门人莫见，埋文子细列幽墟。"]},{"t":"绩溪二咏 其二 翠眉亭","f":"七言律诗","c":["谁安双岭曲弯弯，眉势低临户牖间。","斜拥千畦铺渌水，稍分八字放遥山。","愁霏宿雨峰峦湿，笑卷晴云草木闲。","忽忆故乡银色界，举头千里见苍颜。"]},{"t":"绩溪二咏 其一 豁然亭","f":"七言律诗","c":["南看城市北看山，每到令人意豁然。","碧瓦千家新过雨，青松万壑正生烟。","经秋卧病闻斤响，此日登临负酒船。","径请诸君作佳句，壁间题我此诗先。"]},{"t":"雪后小酌赠内","f":"五言律诗","c":["薄雪为灯止，和风应节来。","出游吾已懒，小酌意难裁。","竹径泥方滑，菁畦冻欲开。","细君怜老病，加料作新醅。"]},{"t":"黄几道郎中同年挽词二首 其一","f":"七言律诗","c":["温恭天赋此心良，惠爱人知政术长。","井水无波任瓶绠，牛刀投隙应宫商。","分符出遍名城守，携被归从华省郎。","不到汝阴遗恨远，坐令湖水减清光。"]},{"t":"黄几道郎中同年挽词二首 其二","f":"七言律诗","c":["早岁相从能几时，淮阳花发正游嬉。","鸣弓矍相人如堵，席地沧浪柳作帷。","十载旧游真是梦，一时佳客尚存谁。","遥闻葬日车千两，渍酒绵中寄一悲。"]},{"t":"傅钦之学士济源草堂","f":"七言律诗","c":["闻有高居直百金，西山南麓北山阴。","园通济水池塘好，花近洛川颜色深。","人去节旄分重镇，客来猿鹤感幽吟。","潩溪雨过西湖涨，归兴萧然定不任。"]},{"t":"傅银青挽词二首 其二","f":"五言律诗","c":["丹旐国西门，茅庐济水深。","官清贫似旧，名重殁犹存。","台阁传遗懿，交游拭泪痕。","君恩不改故，延赏遍诸孙。"]},{"t":"傅银青挽词二首 其一","f":"五言律诗","c":["名自乌台发，恩从凤沼深。","盐梅和众口，金玉比诚心。","澹泊平生事，弥留一病侵。","遗言自无憾，朝野为沾襟。"]},{"t":"喜王巩承事北归","f":"七言律诗","c":["同罪南迁惊最远，乘流北下喜先归。","谓言一笑秋风后，却顾千山驿路非。","岭外云烟随梦远，江边鱼蟹为人肥。","还家嫁女都无事，卧读诗书尽掩扉。"]},{"t":"喜雨","f":"七言律诗","c":["夏田已报七分熟，秋稼方忧十日乾。","好雨徐来不仓卒，天公似欲救艰难。","魃张鹰犬无遗力，社近鸡豚趁早寒。","老病随人幸一饱，炉香无语只长叹。"]},{"t":"喜雨","f":"七言律诗","c":["一旱经春夏已半，好雨通宵晓未收。","气爽暂令多病喜，来迟未解老农忧。","力耕仅足公家取，遗秉休违寡妇求。","时向林间数新竹，箨龙腾上欲迎秋。"]},{"t":"喜雪呈鲜于子骏三首 其一","f":"七言律诗","c":["发函宽大一封书，卧阁雍容三日馀。","旋见雪花投夜落，未应天意与人疏。","瓦乾淅淅初鸣霰，畦润渐渐想没锄。","高会梁园遗胜在，早知词赋似相如。"]},{"t":"喜雪呈鲜于子骏三首 其二","f":"七言律诗","c":["春秋无麦自当书，况复秋田水潦馀。","一雪端来救焦槁，千箱乞与等亲疏。","消残瘟疠曾非药，蚀遍陈根不用锄。","犹恐远村沾未足，试呼农圃问何如。"]},{"t":"喜雪呈鲜于子骏三首 其三","f":"七言律诗","c":["茧纸铺庭几误书，杨花糁径未春馀。","积随平野分高下，舞信微风作密疏。","解使游人似姑射，仍令飞鸟变舂锄。","共惊天巧无能学，造物无心本亦如。"]},{"t":"寒雨","f":"五言律诗","c":["江南殊气候，冬雨作春寒。","冰雪期方远，蕉絺意始阑。","未妨溪草绿，先恐岭梅残。","忽发中原念，貂裘据锦鞍。"]},{"t":"寒食二首 其二","f":"七言律诗","c":["寄住汝南怀岭南，五年一醉久犹酣。","身逃争地差云静，名落尘寰终自惭。","耳畔飞蝇看尚在，鼻中醇酢近能甘。","今朝寒食唯当饮，买酒先防客欲谈。"]},{"t":"寒食二首 其一","f":"七言律诗","c":["寒食今年客汝南，馀樽倾泻亦醺酣。","道人久厌世间浊，僧舍犹存肉食惭。","花折园夫时送客，饧留孙女尚分甘。","欲游紫极谁为伴，长揖孤松对不谈。"]},{"t":"寒食前一日寄子瞻","f":"七言律诗","c":["寒食明朝一百五，谁家冉冉尚厨烟。","桃花开尽叶初绿，燕子飞来体自便。","爱客渐能陪痛饮，读书无思懒开编。","秦川雪尽南山出，思共肩舆看麦田。"]},{"t":"寓居二首 其一 东亭","f":"七言律诗","c":["十口南迁粗有归，一轩临路阅奔驰。","市人不惯频回首，坐客相谙便解颐。","惭愧天涯善知识，增添城外小茅茨。","华严未读河沙偈，偃仰明窗手自披。"]},{"t":"寓居六咏 其一","f":"五言律诗","c":["手植天随菊，晨添苜蓿盘。","丛长怜夏苦，花晚怯秋寒。","素食旧所愧，长斋今未阑。","殷勤拾落蕊，眼暗读书难。"]},{"t":"寓居六咏 其三","f":"五言律诗","c":["邻家三亩竹，萧散倚东墙。","谁谓非吾有，时能惠我凉。","雪深闻毁折，风作任披猖。","事过还依旧，相看意愈长。"]},{"t":"寓居六咏 其四","f":"五言律诗","c":["弱榴生掩冉，插竹强支叉。","旋叠封根石，能开著子花。","扶持物遂性，缀缉我成家。","故国田园少，何须恨海涯。"]},{"t":"寓居六咏 其二","f":"五言律诗","c":["山丹炫南土，盈尺愧西京。","所至曾无比，知非浪得名。","未须求别种，尚欠剥繁英。","行复春风度，天涯眼暂明。"]},{"t":"寓居六咏 其五","f":"五言律诗","c":["大鸡如人立，小鸡三寸长。","造物均付予，危冠两昂藏。","出栏风易倒，依草枯不僵。","后庭花草盛，怜汝计兴亡。"]},{"t":"景福顺老夜坐道古人搐鼻语","f":"七言律诗","c":["中年闻道觉前非，邂逅仍逢老顺师。","搐鼻径参真面目，掉头不受别钳锤。","枯藤破衲公何事，白酒青盐我是谁。","惭愧东轩残月上，一杯甘露滑如饴。"]},{"t":"曾子固舍人挽词","f":"七言律诗","c":["少年漂泊马光禄，末路骞腾朱会稽。","儒术远追齐稷下，文词近比汉京西。","平生碑版无容继，此日铭诗谁为题。","试数庐陵门下士，十年零落晓星低。"]},{"t":"曾郎元矩见过逾月听其言久而不厌追感平昔为赋诗","f":"七言律诗","c":["胄子相从得佳婿，掖垣同直喜良朋。","交情不意隔生死，世事休论有废兴。","宿草芊绵泪入土，故琴牢落恨填膺。","远来似觉清谈胜，试问传家今几灯。"]},{"t":"游西湖","f":"七言律诗","c":["闭门不出十年久，湖上重游一梦回。","行过闾阎争问讯，忽逢鱼鸟亦惊猜。","可怜举目非吾党，谁与开尊共一杯。","归去无言掩屏卧，古人时向梦中来。"]},{"t":"游庐山山阳七咏 其五 万杉寺","f":"七言律诗","c":["万木青杉一手栽，满堂白佛九天来。","涓涓石溜供厨足，矗矗山屏绕寺开。","半榻松阴秋簟冷，一杯香饭午钟催。","安眠饱食平生事，不待山僧唤始回。"]},{"t":"游庐山山阳七咏 其六 三峡石桥","f":"七言律诗","c":["三峡波涛饱溯沿，过桥雷电记当年。","江声仿佛瞿唐口，石角参差滟滪前。","应有夜猿啼古木，已将秋叶作归船。","老僧未省游巴蜀，松下相逢问信然。"]},{"t":"游庐山山阳七咏 其一 开先瀑布","f":"七言律诗","c":["山上流泉自作溪，行逢石缺泻虹霓。","定知云外波澜阔，飞到峰前本末齐。","入海明河惊照曜，倚天长剑失提携。","谁来卧枕莓苔石，一洗尘心万斛泥。"]},{"t":"游庐山山阳七咏 其四 归宗寺","f":"七言律诗","c":["来听归宗早晚钟，疲劳懒上紫霄峰。","墨池漫叠溪中石，白塔微分岭上松。","佛宇争推一山甲，僧厨坐待十方供。","欲游山北东西寺，岩谷相连更几重。"]},{"t":"游庐山山阳七咏 其七 白鹤观","f":"七言律诗","c":["五老相携欲上天，玄猿白鹤尽疑仙。","浮云有意藏山顶，流水无声入稻田。","古木微风时起籁，诸峰落日尽生烟。","归鞍草草还城市，惭愧幽人正醉眠。"]},{"t":"游庐山山阳七咏 其三 简寂观","f":"七言律诗","c":["山行但觉鸟声殊，渐近神仙简寂居。","门外长溪净客足，山腰苦笋助盘蔬。","乔松定有藏丹处，大石仍存拜斗馀。","弟子苍髯年八十，养生世世授遗书。"]},{"t":"游庐山山阳七咏 其二 漱玉亭","f":"七言律诗","c":["山回不见落银潢，馀溜喧豗响石塘。","目乱珠玑溅空谷，足寒雷电绕飞梁。","入瓶铜鼎春茶白，接竹斋厨午饭香。","从此出山都不弃，满田粳稻插新秧。"]},{"t":"游净因院寄琏禅师","f":"七言律诗","c":["岁月潜消日里冰，依然来见佛堂灯。","此身已自非前我，问法何妨似旧僧。","洒面飞泉时点点，压池苍石尚层层。","遥知近爱金山好，江水煎茶日几升。"]},{"t":"登上水关","f":"七言律诗","c":["淇水沄沄入禁城，城楼中断过深清。","空郊南数牛羊下，落日回瞻观阙明。","岁月逼人行老大，江湖发兴感平生。","画舫早晚笼新屋，慰意来看水面平。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 登嵩山十首 其四 醒心泉","f":"五言律诗","c":["上山苦饥渴，中道得寒泉。","举瓢石窦响，入口烦痾痊。","洑流去不见，落涧声锵然。","莫归复相值，相从下平川。"]},{"t":"筑室示三子","f":"七言律诗","c":["宅舍元依毕竟空，小乘惯住草庵中。","一生滞念馀妻子，百口侨居怯雨风。","松竹已栽犹稍稍，栋梁未具勿匆匆。","三间道院吾真足，馀问儿曹莫问翁。"]},{"t":"答颜复国博","f":"七言律诗","c":["岁晚河冰留画船，一轩修竹喜萧然。","诗词温厚新成格，道论精微近入禅。","病后不胜清醑酽，别时仍得旧书传。","欲成古史须咨考，陋巷何因接尺椽。"]},{"t":"腊雪五首 其三","f":"五言律诗","c":["久有归耕意，西山百亩田。","雪来殊不恶，酒熟自相便。","一被簪裳裹，长遭罗网牵。","飞霙迫残腊，愁思渡今年。"]},{"t":"腊雪五首 其四","f":"五言律诗","c":["忧愁不可缓，风雪故相撩。","试问五斗米，能胜一束樵。","耕耘终亦饱，哺啜定谁邀。","寒暑不须避，倾危且自遥。"]},{"t":"腊雪五首 其二","f":"五言律诗","c":["骄阳不能久，密雪自相催。","急霰初鸣瓦，飞花旋集台。","着人消瘴疫，覆麦长根荄。","欲试樽中物，门前问客来。"]},{"t":"腊雪五首 其五","f":"五言律诗","c":["雪霜何与我，忧思自伤神。","忠信亦何罪，才名空误身。","归来聊且止，老去莫逢嗔。","樽酒它年事，相看醉此晨。"]},{"t":"舜泉复发","f":"七言律诗","c":["奕奕清波旧绕城，旱来泉眼亦尘生。","连宵暑雨源初接，发地春雷夜有声。","复理沟渠通屈曲，重开池沼放澄清。","通衢细洒浮埃净，车马归来似晚晴。"]},{"t":"谢人惠千叶牡丹","f":"七言律诗","c":["东风催趁百花新，不出门庭一老人。","天女要知摩诘病，银瓶满送洛阳春。","可怜最后开千叶，细数馀芳尚一旬。","更待游人归去尽，试将童冠浴湖滨。"]},{"t":"谢任亮教授送千叶牡丹","f":"七言律诗","c":["花从单叶成千叶，家住汝南疑洛南。","乱剥浮苞任狼籍，并偷春色恣醺酣。","香秾得露久弥馥，头重迎风似不堪。","居士谁知已离畏，金槃剪送病中庵。"]},{"t":"谢张安道惠马","f":"七言律诗","c":["从事年来鬓似蓬，破车倦仆众人中。","作诗仅比穷张籍，得马还从老晋公。","夜起趋朝非所事，晓骑行乐定谁同。","惯乘款段游田里，怯听骎骎两耳风。"]},{"t":"谢洞山石台远来访别","f":"七言律诗","c":["窜逐深山无友朋，往还但有两三僧。","共游渤澥无边处，扶出须弥最上层。","未尽俗缘终引去，稍谙真际自虚澄。","坐令颠老时奔走，窃比韩公愧未能。"]},{"t":"鲁元翰中大挽词二首 其二","f":"七言律诗","c":["十年初见范公园，知与钱塘结弟昆。","乐易向人无不可，疏慵怜我正忘言。","南迁却返逢北渡，远聘相过适近藩。","无复放怀哗笑语，挽诗空寄泪潺湲。"]},{"t":"鲁元翰中大挽词二首 其一","f":"五言律诗","c":["遗直诵家声，持心本至诚。","何劳求皦察，所至自安平。","气象馀前辈，才华属后生。","飞腾看诸子，相继亦公卿。"]},{"t":"新种芭蕉","f":"七言律诗","c":["芭蕉移种未多时，濯濯芳茎已数围。","毕竟空心何所有，攲倾大叶不胜肥。","萧骚莫雨鸣山乐，狼籍秋霜脱敝衣。","堂上幽人观幻久，逢人指示此身非。"]},{"t":"新桥","f":"七言律诗","c":["六月长桥断不收，朱栏初喜映春流。","虹腰宛转三百尺，鲸背参差十五舟。","入市樵苏看络绎，归家盐酪免迟留。","病夫最与民同喜，卯酉匆匆无复忧。"]},{"t":"楼观","f":"七言律诗","c":["老聃厌世入流沙，飘荡如云不可遮。","弟子怜师将去国，关门望气载还家。","高台尚有传经处，画壁空留驾犊车。","一授遗书无复老，不知何苦服胡麻。"]},{"t":"溯潮二首 其一","f":"七言律诗","c":["潮来海若一长呼，潮去萧条一吸馀。","初见千艘委泥土，忽浮万斛溯空虚。","映山少避曾非久，借势前行却自如。","天地尚遭人意料，乘时使气定粗疏。"]},{"t":"溯潮二首 其二","f":"七言律诗","c":["疋练萦回出海门，黄泥先变碧波浑。","初来似欲倾沧海，正满真能倒百源。","流蘖飞腾竟何在，扁舟睥睨久仍存。","自惭不作山林计，来往终随万物奔。"]},{"t":"筠州州宅双莲","f":"七言律诗","c":["绿盖红房共一池，一双游女巧追随。","镜中比并新妆后，风际携扶欲舞时。","露蕊暗开香自倍，霜蓬渐老折犹疑。","殷勤画手传真态，道院生绡数幅垂。"]},{"t":"简学中诸生","f":"七言律诗","c":["泮水秋生藻荇凉，莫窗灯火乱萤光。","图书粗足惟须读，菽粟才供且自强。","羽籥暗催新节物，弦歌不废近诗章。","腐儒最喜南迁后，仍见西雍白鹭行。"]},{"t":"辞灵惠庙归过新兴院书其屋壁","f":"七言律诗","c":["来时稻叶针锋细，去日黄花黍粒粗。","久病终惭多敝政，丰年犹喜慰耕夫。","青山片片添红叶，渌水星星照白须。","东观校雠非老事，眼昏那复竞铅朱。"]},{"t":"雎阳五老图","f":"七言律诗","c":["贤才冠世得优閒，免向金门老赘冠。","颂德华名盈满轴，规章文献表穹桓。","宦家有道生忠烈，夷夏初宁谏齿寒。","正是紫微垣里客，如今列上画图看。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 过登封阎氏园","f":"五言律诗","c":["秋暑尚烦襟，林泉净客心。","菊残知节过，荷尽觉池深。","疏柳摇山色，青苔遍竹阴。","犹嫌近官道，轣辘听车音。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 许州留别顿主簿","f":"七言律诗","c":["洛寺相从不出门，绕城空复记名园。","程文堆案晨兴早，竹簟连床夜雨喧。","归路逢僧暂容与，登山无力强扳援。","遥知别后都如梦，赖有君诗一一存。"]},{"t":"熙宁壬子八月于洛阳妙觉寺考试举人及还道出嵩少之间至许昌共得大小诗二十六首 将出洛城过广爱寺见三学演师引观杨惠之塑宝山朱瑶画文殊普贤为赋三首 其三","f":"五言律诗","c":["壁毁丹青在，移来殿庑深。","赋形惊变态，观佛觉无心。","旌旆翻空色，笙竽含妙音。","风流出吴样，遗法到如今。"]},{"t":"滕达道龙图挽词二首 其二","f":"七言律诗","c":["南窜逢公弄水亭，北归留我阖闾城。","壮年不见日千里，馀论犹惊敌万兵。","简册何人知造膝，边防触处竦先声。","伤心系舸城东地，目断安知有死生。"]},{"t":"滕达道龙图挽词二首 其一","f":"五言律诗","c":["才适邦家用，学非章句儒。","遭逢初莫测，流落一长吁。","大节轻多难，深言究远图。","收功太原守，谈笑视羌胡。"]},{"t":"踏藕","f":"五言律诗","c":["春湖柳色黄，宿藕冻犹僵。","翻沼龙蛇动，撑船牙角长。","清泉浴泥滓，粲齿碎冰霜。","莫使新梢尽，炎风翠盖凉。"]},{"t":"题方子明道人东窗","f":"五言律诗","c":["纸窗云叶净，香篆细烟青。","客到催茶磨，泉声响石瓶。","禅关敲每应，丹诀问无经。","赠我刀圭药，年来发变星。"]},{"t":"题王诜都尉设色山卷后","f":"七言律诗","c":["还君横卷空长叹，问我何年便退休。","欲借岩阿著茅屋，还当溪口泊渔舟。","经心蜀道云生足，上马胡天雪满裘。","万里还朝径归去，江湖浩荡一轻鸥。"]},{"t":"题李简夫葆光亭","f":"五言律诗","c":["径草侵芒屩，庭花堕石台。","小亭幽事足，野色向人来。","坐上乌皮几，墙间大瓠罍。","老成无不可，谈笑得徘徊。"]},{"t":"题杜介供奉熙熙堂","f":"七言律诗","c":["门前籍籍草生径，堂上熙熙气吐春。","遮眼图书聊度日，放情丝竹最关身。","年来冯脱乌皮几，客去时乾漉酒巾。","卜筑城中移榜就，休心便作广陵人。"]},{"t":"题南康太守宅五老亭","f":"七言律诗","c":["五老高闲不入城，开轩肯就史君迎。","坐中莫著闲宾客，物外新成六弟兄。","云气飘浮衣袂举，泉流洒落佩环声。","岌然终日俱无语，静寿相看意自明。"]},{"t":"题徐正权秀才城西溪亭","f":"七言律诗","c":["竹林分径水通渠，真与幽人作隐居。","溪上路穷惟画舫，城中客至有罾鱼。","东来只为林泉好，野外从教簿领疏。","不识徂徕石夫子，兼因女婿觅遗书。"]},{"t":"题都昌清隐禅院","f":"七言律诗","c":["北风江上落潮痕，恨不乘舟便到门。","楼观飞翔山断际，松筠阴翳水来源。","升堂猿鸟晨窥坐，乞食帆樯莫绕村。","谁道溪岩许深处，一番行草认元昆。"]},{"t":"题郾城彼岸寺二首 其一 文殊院古柏","f":"七言律诗","c":["曾看大柏孔明祠，行尽天涯未见之。","此树便当称子行，他山只可作孙枝。","栋梁知是谁家用，舟楫唯应海水宜。","日莫飞鸦集无数，青田老鹤未曾知。"]},{"t":"题郾城彼岸寺二首 其二 武宗元比部画文殊玄奘","f":"七言律诗","c":["遗墨消磨顾陆馀，开元一一数吴卢。","本朝唯有宗元近，国本长留后世模。","出世真人气雍穆，入蕃老释面清癯。","居人不惜游人爱，风雨侵陵色欲无。"]},{"t":"歙县岁寒堂","f":"七言律诗","c":["槛外甘棠锦绣屏，长松何者擅亭名。","浮花过眼无多日，劲节凌寒尽此生。","暗长茯苓根自大，旋收金粉气尤清。","长官不用求琴谱，但听风吹作弄声。"]},{"t":"赠王复处士","f":"七言律诗","c":["候潮门外王居士，平昔交游遍海涯。","本种杉松为老计，晚将亭榭付邻家。","为生有道终安隐，好事来游空叹嗟。","犹有东坡旧诗卷，忻然对客展龙蛇。"]},{"t":"赠史文通奉议二首 其二","f":"五言律诗","c":["有叟住东野，畏人希入城。","君时共还往，我欲问修行。","早岁识岩客，近时逢绛生。","真能访茅屋，屣履试将迎。"]},{"t":"赠史文通奉议二首 其一","f":"五言律诗","c":["墙北史居士，挂冠心转闲。","顶开人共怪，神去夜深还。","白雪微侵鬓，丹砂久驻颜。","从君欲问道，何日径开关。"]},{"t":"赠司空张公安道挽词三首 其三","f":"五言律诗","c":["西蜀识公初，南都从事馀。","一言知我可，久好复谁如。","学术留元叹，家声付伯鱼。","霜天近生日，闻挽重唏嘘。"]},{"t":"赠司空张公安道挽词三首 其二","f":"五言律诗","c":["孤高出世学，豪迈谪仙人。","早岁犹和俗，中年自识真。","定馀时发照，尘尽四无邻。","闻道骑箕尾，还应事玉宸。"]},{"t":"赠司空张公安道挽词三首 其一","f":"五言律诗","c":["道广中无竞，才高治不烦。","安心本笃静，忧世亦时言。","寿考同侪尽，经纶故事存。","犹应门下客，微论记根原。"]},{"t":"赠医僧善正","f":"七言律诗","c":["老怯江边瘴疠乡，城东时喜到公房。","历言五藏如经眼，欲去三彭自有方。","身厌远游安静默，术因多病更深长。","时时为我谈尊宿，曾入南公古道场。"]},{"t":"赠李简夫司封","f":"七言律诗","c":["平生谈笑接诸公，归老身心著苦空。","往事少能陪晤语，新诗时喜挹清风。","形骸摩诘羸偏健，笔札西台晚更工。","笑我壮年常苦病，异时何以作衰翁。"]},{"t":"赠景福顺长老二首 其一","f":"五言律诗","c":["屈指江西老，多言剑外人。","身心已无著，乡党漫相亲。","窜逐知何取，周旋意甚真。","仍将大雷雨，一洗百生尘。"]},{"t":"赠景福顺长老二首 其二","f":"五言律诗","c":["念昔先君子，南游四十年。","相看顺老在，想见讷师贤。","岁历风轮转，禅心海月圆。","常情计延促，无语对潸然。"]},{"t":"赠蔡駜居士","f":"七言律诗","c":["结茅汝上只三间，种稻城西仅一廛。","梅老外生诗律在，秀公弟子佛心传。","埋盆叠石常幽坐，留客开樽辄醉眠。","闻道邻僧乞米送，时无韩子定谁怜。"]},{"t":"磻溪石","f":"五言律诗","c":["吕公年已莫，择主渭河边。","跪饵留双膝，临溪不计年。","神专能陷石，心大岂营鳣。","不到磻溪上，安知自守坚。"]},{"t":"藏菜","f":"七言律诗","c":["爨清葵芥充朝膳，岁晚风霜断菜根。","百日园枯未易过，一家口众复何言。","多排瓮盎先忧尽，旋设盘盂未觉烦。","早晚春风到南圃，侵凌雪色有新萱。"]},{"t":"衢州赵阅道少师濯缨亭","f":"七言律诗","c":["挂冠缨上已无尘，犹爱溪光碧照人。","点检旧游黄石在，扫除诸念白鸥亲。","一尊父老囊金尽，三径松筠生事贫。","他日南公数人物，丹青添入县图新。"]},{"t":"中秋月望十六终夜如昼","f":"五言古诗","c":["秋气久已到，月明如可期。","云生未望夜，天借极圆时。","冷澈登临倦，衰慵起舞迟。","兔闲长捣药，桂老尚生枝。","运转何年住，清明与物宜。","油然任消长，斤斧定何施。"]},{"t":"记岁首乡俗寄子瞻二首 其一 踏青","f":"七言古诗","c":["江上冰消岸草青，三三五五踏青行。","浮桥没水不胜重，野店压糟无复清。","松下寒花初破萼，谷中幽鸟渐嘤鸣。","洞门泉脉龙睛动，观里丹池鸭舌生。","山下瓶罂沾稚孺，峰头鼓乐聚簪缨。","缟裙红袂临江影，青盖骅骝踏石声。","晓去争先心荡漾，莫归誇后醉从横。","最怜人散西轩静，暧暧斜阳著树明。"]},{"t":"次韵刘贡父登黄楼怀子瞻二首 其二","f":"五言古诗","c":["蔼蔼才名世，骎骎日转禺。","一时同接淅，平昔共栖梧。","揽辔真壮士，拥旄良丈夫。","尘埃脱缁绶，水石慰霜须。","胜地来相失，清樽未暇俱。","射馀空见帖，铸罢祗观模。","归计何当决，徂年贵早图。","槛中终为食，韝上耻闻呼。","顾我千羊毳，平生一钓舻。","微官不须满，也复试游吴。"]},{"t":"戎州","f":"五言古诗","c":["江水通三峡，州城控百蛮。","沙昏行旅倦，边静禁军闲。","汉虏更成市，罗纨靳不还。","投毡拣精密，换马瘦孱颜。","兀兀头垂髻，团团耳带环。","夷声不可会，争利苦间关。"]},{"t":"次韵子瞻馀杭法喜寺绿野亭怀吴兴太守孙莘老","f":"五言古诗","c":["信美非吾土，三吴一水中。","亭高望已极，舟入去无穷。","朝市知安在，湖山信有功。","遨游逐凫鸭，饮食数鱼虫。","波浪喧朝夕，梅烝变绿红。","逢人问京洛，去国长儿童。","同舍情相接，邻邦信屡通。","相邀欲相过，道里讯溪翁。"]},{"t":"次韵子瞻招隐亭","f":"五言古诗","c":["隐居吾未暇，何暇劝夫人。","试饮此亭酒，自惭缨上尘。","林深开翠帟，岸断峻严闉。","送雪村酤酽，迎阳鸟哢新。","竹风吹断籁，湖月转车轮。","霜叶飞投坐，山梅重压巾。","欲居常有待，已失叹无因。","古语君看取，声名本实宾。"]},{"t":"次韵子瞻南溪避世堂","f":"五言古诗","c":["柱杖行穷径，围堂尚有林。","飞禽不惊处，万竹正当心。","虎啸风吹籁，霜多蝉病瘖。","兽骄从不避，人到记由今。","未暇终身住，聊为半日吟。","青松可绝食，黄叶不须衾。","偶到初迷路，将还始觉深。","堂中有幽士，插髻尚馀簪。"]},{"t":"次韵子瞻送范景仁游嵩洛","f":"五言古诗","c":["寻山非事役，行路不应难。","洛浦花初满，嵩高雪尚寒。","平林抽冻笋，奇艳变山丹。","节物朝朝好，肩舆步步安。","酴醾酿腊酒，苜蓿荐朝盘。","得意忘春晚，逢人语夜阑。","归休三黜柳，赋咏五噫鸾。","鹤老身仍健，鸿飞世共看。","云移忽千里，世路脱重滩。","西望应思蜀，东还定过韩。","平川涉清颍，绝顶上封坛。","出处看公意，令人欲弃官。"]},{"t":"次韵子瞻麻田青峰寺下院翠麓亭","f":"五言古诗","c":["走马红尘合，开怀野寺存。","南山抱村转，渭水带沙浑。","亭峻朱栏绕，堂虚白佛尊。","烦襟喜修竹，倦马乐芳荪。","白氎柔随手，清泉满照盆。","尘颜洗濯净，髀肉再三扪。","馈食青蔬软，流匙细粟翻。","老僧勿施敬，对客说山门。"]},{"t":"次韵孔文仲舍人酴醾","f":"五言古诗","c":["苍蛇冻不死，轻素暖仍归。","落蕊时吹面，繁香自扑帏。","光凝真照夜，枝软或牵衣。","似厌风霾苦，应思雾雨霏。","开樽迎最盛，扫地见初稀。","赖有清阴在，金波肯发挥。"]},{"t":"次韵毛君山房遣兴","f":"五言古诗","c":["欲就阳崖暖，新开石磴斜。","谁言太守宅，自是野人家。","燕坐收心鉴，冥观阅界沙。","退公长寂寞，外物自喧哗。","缺径移松补，斜阳种竹遮。","白云生后础，孤鹜伴残霞。","破闷时寻鹤，呼眠亦任鸦。","喜闻糟出瓮，屡问菊开花。","古井元依斗，丹砂旧养芽。","蚍蜉频上案，猿狖巧分楂。","客到扁舟远，年侵两鬓华。","心摇挂风旆，眼暗隔轻纱。","强拨横肱睡，来从插版衙。","隐居惭弃掷，胜地每咨嗟。","顽钝终何取，彫磨岂复加。","焦先夙所尚，圜舍恰如蜗。"]},{"t":"次韵刘贡父登黄楼怀子瞻二首 其一","f":"五言古诗","c":["青山开四面，白水绕三禺。","野阔时闻籁，人闲旧据梧。","画船留上客，遗迹问田夫。","事少日常饮，才疏世未须。","决河初荐至，胜事偶相俱。","燕子卑无取，滕王远可模。","飞涛隐睥睨，落日丽浮图。","同舍新持节，专城敢遽呼。","未迎行部驾，已放下淮舻。","试问登消暑，如何楚与吴。"]},{"t":"次韵沈立少卿白鹿","f":"五言古诗","c":["白鹿何年养，惊猜未肯驯。","轩除非本性，饮食强依人。","照影冰浮水，飞毛雪洒尘。","独游应已倦，忽见乍疑神。","野色明幽步，烟芜荐卧身。","异姿人共爱，清意尔谁亲。","日暖山苗熟，风微涧草春。","何缘解缰絷，奔放任天真。"]},{"t":"自柘城还府马上","f":"五言古诗","c":["春色无人见，兹行偶众先。","柳黄新过雨，麦绿稍铺田。","河润兼冰散，禽声向日圆。","城池高受雾，濉涣暖生烟。","送客情初恶，还家意稍便。","旋闻夫事起，已过佛灯然。","簿领何时毕，尘埃空自怜。","南湖渐可到，早治木兰船。"]},{"t":"李简夫挽词二首 其一","f":"五言律诗","c":["老成浑欲尽，吊客一潸然。","遗事人人记，清诗句句传。","挂冠疏傅早，乐世白公贤。","叹息风流在，埋文得细镌。"]},{"t":"和张安道读杜集","f":"五言古诗","c":["我公才不世，晚岁道尤高。","与物都无著，看书未觉劳。","微言精《老》、《易》，奇韵喜《庄》、《骚》。","杜叟诗篇在，唐人气力豪。","近时无沈、宋，前辈蔑刘、曹。","天骥精神稳，层台结构牢。","龙腾非有迹，鲸转自生涛。","浩荡来何极，雍容去若遨。","坛高真命将，毳乱始知髦。","白也空无敌，微之岂少褒。","论文开锦绣，赋命委蓬蒿。","初试中书日，旋闻鄜畤逃。","妻孥隔豺虎，关辅暗旌旄。","入蜀营三径，浮江寄一艘。","投人惭下舍，爱酒类东皋。","漂泊终浮梗，迂疏独钓鳌。","误身空有赋，掩胫惜无袍。","卷轴今何益，零丁昔未遭。","相如元群世，惠子谩临濠。","得失将谁怨，凭公付浊醪。"]},{"t":"和李诚之待制宴别西湖","f":"五言古诗","c":["东来亦何恃，夫子此分符。","谈笑万事毕，樽罍众客俱。","高情生远岫，清兴发平湖。","坐使羁游士，能忘岁月徂。","纵欢真乐易，恨别不须臾。","庙幄新谋帅，河间最近胡。","安边本馀事，清赏信良图。","应念兹园好，流泉海内无。"]},{"t":"试院唱酬十一首 次前韵","f":"五言古诗","c":["南国号多士，几人洙泗风。","英材自入彀，坏阵不劳攻。","文缛山藏豹，飞高弋慕鸿。","蚩妍归品藻，得失付虚空。","考行先推本，登贤旋奏公。","期君缓归辔，一醉鹿鸣中。"]},{"t":"试院唱酬十一首 观试进士呈试官","f":"五言古诗","c":["松庭散朝日，棘户启秋风。","鹄鹭纷来下，旌旗俨未攻。","驰词看倚马，馀力送征鸿。","逸足谁先到，孤标想暗空。","晶荧双镜并，高下片言公。","老病方耽睡，飞沉一梦中。"]},{"t":"春雪","f":"五言古诗","c":["温风吹破腊，留雪恼新春。","信逐残梅到，花从半夜匀。","旋消微覆瓦，狂下亦欺人。","压竹时闻落，埋萱久未伸。","山川濛不解，楼观洗成新。","拥褐僧方睡，开门客屡嚬。","爨烟知岁稔，履迹笑吾贫。","畦冻初生韭，泥融正卖薪。","寒鱼争就汕，烛酒颇无巡。","预喜田宜麦，槃餐饼饵频。"]},{"t":"送王恪郎中知襄州","f":"七言古诗","c":["魏公德业冠当年，汝守威名竦汉边。","将相传家俱未远，子孙到处各推贤。","风流最喜君真似，符竹连分政得专。","岘首重寻碑堕泪，习池还指客横鞭。","逃亡已觉依刘表，寒俊应须礼浩然。","当有郡人知古意，拦街齐唱接篱篇。"]},{"t":"送张师道杨寿祺二同年","f":"五言古诗","c":["故国多贤俊，登科并弟兄。","重来旧游处，两见近题名。","冉冉须堪把，骎骎岁可惊。","孤辕已南向，疋马复西征。","入峡猿应苦，还荆雁已鸣。","喜从元帅幕，官职渐峥嵘。"]},{"t":"送李昭叙移黎阳都监归洛省亲","f":"五言古诗","c":["与君非旧识，倾盖便相亲。","共事林泉郡，忘归南北人。","煮茶流水曲，载酒后湖漘。","未觉游从厌，空惊别恨新。","濒河今重地，知己旧元臣。","洛下闻鸡犬，家书不浃旬。","西还倚门罢，北渡羽书频。","忠孝传家事，风流待一振。"]},{"t":"送苏公佐修撰知梓州","f":"五言古诗","c":["乘轺旧西蜀，出镇复东川。","父老知遗爱，壶浆定满前。","江山昔年路，旄节异邦权。","望重朝中旧，疆分剑外天。","岁登无猛政，蛮服罢防边。","去国身虽乐，忧时论独坚。","孤诚抱松直，汇进比茅连。","我亦相从逝，疏狂且自全。"]},{"t":"送赵㞦秘书还钱塘","f":"五言古诗","c":["世人何局促，奔走鬓苍苍。","闻道馀杭守，独游何有乡。","禅心朝吐月，元气夜生光。","清静安罢瘵，宽仁服暴强。","声名高一世，风采见诸郎。","谒帝朱为绂，还家綵作裳。","经过留画舫，谈笑接清觞。","问讯颜依旧，峥嵘岁自长。","人生真几许，世味不堪尝。","归去闻诗罢，求余却老方。"]},{"t":"陪杜充张恕鸿庆宫避暑","f":"五言古诗","c":["至后雨如泻，晴来热更多。","簿书沾汗垢，岩石思藤萝。","赖有祠宫静，时容俗客过。","老郎无不可，公子亦能和。","道胜还相接，禅迷屡见诃。","清凉生绝念，烦暑散沉疴。","古木便张幄，鸣禽巧当歌。","桃香呈绛颊，瓜熟裹青罗。","饭细经唇滑，茶新到腹薖。","剧谈时自笑，饱食更无它。","适意未应厌，后游真若何。","官居邻曲沼，田畎助清波。","晚照明疏柳，微风响众荷。","轻舟尚可载，小雨试渔蓑。"]},{"t":"落叶满长安分题","f":"五言古诗","c":["有客倦长安，秋风正飒然。","九衢飞乱叶，八水凝寒烟。","摇落南山见，凄凉陋巷偏。","名园失绿暗，清渭泛红鲜。","衣信催烦杵，狼烽报极边。","长江苦吟处，日暮想横鞭。"]},{"t":"燕贡士","f":"五言古诗","c":["泮水生芹藻，干旄在浚城。","桑鸮同变响，苹鹿共和鸣。","秋晚槐先堕，霜多桂向荣。","清尊助劝驾，急管发欢声。","勇锐青衿士，淹通白发生。","芬芳杂兰菊，变化等鹍鲸。","去日衣冠盛，归时里巷惊。","坐中词赋客，愧尔一经明。"]},{"t":"丁亥生日","f":"五言古诗","c":["少年即病肺，喘作锯木声。","中年复病脾，暴下泉流倾。","困苦始知道，处世百欲轻。","收功在晚年，二疾忽已平。","来年今日中，正行七十程。","老聃本吾师，妙语初自明。","至哉希夷微，不受外物婴。","非三亦非一，了了无形形。","迎随俱不见，瞿昙谓无生。","湛然琉璃内，宝月长盈盈。"]},{"t":"九日三首 其三","f":"五言律诗","c":["幼子淮西客，双壶思老人。","远来经颔淡，细酌喜清醇。","饮罢遥怜汝，归来早及春。","南斋昔未有，馀似旧时贫。"]},{"t":"九日家酿未熟","f":"五言古诗","c":["平生不喜饮，九日犹一酌。","今年失家酿，节到真寂寞。","床头泻馀樽，畦菊吐微萼。","洗盏对妻孥，肴蔬随厚薄。","兴来欲径醉，量尽还自却。","傍人叹身健，省己知脾弱。","尚有姑射人，自守常绰约。","养生要慈俭，已老惭矍铄。","燕居渐忘我，杜门奚不乐。","风曲日已乾，浊醪可徐作。"]},{"t":"入峡","f":"五言古诗","c":["舟行瞿唐口，两耳风鸣号。","渺然长江水，千里投一瓢。","峡门石为户，郁怒水力骄。","扁舟落中流，浩如一叶飘。","呼吸信奔浪，不复由长篙。","捩柁破濆旋，畏与乱石遭。","两山蹙相值，望之不容舠。","渐近乃可入，白盐最雄高。","草木皆倒生，哀叫悲玄猱。","白云缭长袖，零落如飞毛。","缅怀洚水年，惨蹙病有尧。","禹益决岷水，屡与山鬼鏖。","摧冈转大石，破地疏洪涛。","巉巉当道山，斩截肩尾销。","峭壁下无趾，连峰断脩腰。","破处不生草，上不挂鸟巢。","水怪不尽戮，下有龙与鳌。","辽哉千万年，禹死遗迹牢。","岂必见河洛，开峡斯已劳。"]},{"t":"八阵碛","f":"五言古诗","c":["涨江吹八阵，江落阵如故。","我来苦寒后，平沙如匹素。","乘高望遗迹，磊磊六十四。","遥指如布棋，就视不知处。","世称诸葛公，用众有法度。","区区落褒斜，军旅无阔步。","中原竟不到，置阵狭无所。","茫茫平沙中，积石排队伍。","独使后世人，知我非莽卤。","奈何长蛇形，千古竟不悟。","惟馀桓元子，久视不能去。"]},{"t":"八玺","f":"七言律诗","c":["秦人一玺十五城，百二十城当八玺。","元日临轩组绶新，君臣相顾无穷喜。","九鼎峥嵘夏禹馀，八玺错落古所无。","古人鄙陋今人笑，父老不惯空惊呼。"]},{"t":"十一月十三日雪","f":"五言古诗","c":["南方霜露多，虽寒雪不作。","北归亦何喜，三年雪三落。","我田在城西，禾麦敢嫌薄。","今年陈宋灾，水旱更为虐。","闭籴斯不仁，逐熟自难却。","饥寒虽吾患，尚可省盐酪。","飞蝗昨过野，遗种遍陂泺。","春阳百日至，闹若蚕生箔。","得雪流土中，及泉尽鱼跃。","美哉丰年祥，不待炎火灼。","呼儿具樽酒，对妇同一酌。","误认屋瓦鸣，更愿闻雪脚。"]},{"t":"三不归行","f":"七言古诗","c":["客心摇摇若悬旌，三度欲归归不成。","方春欲归我自懒，秋冬欲归事自变。","问我欲归定何时，天公默定人不知。","孔公晚岁将入楚，盘桓陈蔡行且住。","昭王已死不复南，意欲归老父母邦。","卫灵父子无足取，姑尔息肩俟东鲁。","三桓岂知用圣人，哀公亦自不能臣。","冉求一战却齐虏，请君召师君亦许。","归来闭户理诗书，弁冕时出从大夫。","梦见周公已不复，老死故国心亦足。","孔公愈老愈屯邅，顾我未及门下贤。","乡邦万里不能往，妻孥近寄颍川上。","依嵩架颍结茅茨，自问此志于何期。","汝南一寓岁行复，来年归去栽松竹。"]},{"t":"三日上辛祈谷除日宿斋户部右曹元日赋三绝句寄呈子瞻兄 其一","f":"七言绝句","c":["七度江南自作年，去年初喜奉椒槃。","冬来误入文昌省，连日斋居未许还。"]},{"t":"三游洞","f":"七言古诗","c":["洞前危径不容足，洞中明旷坐百人。","苍崖硉兀起成柱，乱石散列如惊麇。","清溪百丈下无路，水满沙土如鱼鳞。","夜深明月出山顶，下照洞口才及唇。","沉沉深黑若大屋，野老构火青如燐。","平明欲出迷上下，洞气飘乱为横云。","深山大泽亦有是，野鸟鸣噪孤熊蹲。","三人一去无复见，至今冠盖长满门。"]},{"t":"上高息轩起亭二绝 其一","f":"七言绝句","c":["山下清溪溪上市，溪光山色映人烟。","幽亭正在人声里，长与溪山共寂然。"]},{"t":"久旱府中取虎头骨投邢山潭水得雨戏作","f":"词","c":["邢山潭中黑色龙，经年懒卧泥沙中。","嵩阳山中白额虎，何年一箭肉为土。","龙虽生，虎虽死，天然猛气略相似，生不益人死何负。","虎头枯骨金石坚，投骨潭中潭水旋。","龙知虎猛心已愧，虎知龙懒自增气。","山前一战风雨交，父老晓起看麦苗。","君不见岐山死诸葛，真能奔走生仲达。"]},{"t":"久雨","f":"五言古诗","c":["云低气尚浊，雨细泥益深。","经旬势不止，晚稼日已侵。","闲居赖田食，忧如老农心。","堆场欲生耳，栖亩将陆沉。","常赋虽半释，杂科起相寻。","凶年每多暴，此忧及山林。","号呼天不闻，有言不如喑。","愿见云解脱，秋阳破群阴。"]},{"t":"千叶白莲花","f":"五言古诗","c":["莲花生淤泥，净色比天女。","临池见千叶，谪堕问何故。","空明世无匹，银瓶送佛所。","清泉养芳洁，为我三日住。","蔫然落宝床，应返梵天去。"]},{"t":"土牛","f":"五言古诗","c":["天地非不仁，万物自刍狗。","土牛适成象，逡巡见屠剖。","田家挽双角，归理缫丝釜。","生无负重力，死作初耕候。","碎身本不辞，及物稍无负。","君看刘表牛，岂脱曹公手。"]},{"t":"大人久废弹琴比借人雷琴以记旧曲十得三四率尔拜呈","f":"七言律诗","c":["久厌凡桐不复弹，偶然寻绎尚能存。","仓庚鸣树思前岁，春水生波满旧痕。","泉落空岩虚谷应，佩敲清殿百官寒。","终宵窃听不能学，庭树无风月满轩。"]},{"t":"子瞻与李公麟宣德共画翠石古木老僧谓之憩寂图题其后","f":"七言绝句","c":["东坡自作苍苍石，留取长松待伯时。","只有两人嫌未足，更收前世杜陵诗。"]},{"t":"子瞻和陶公读山海经诗欲同作而未成梦中得数句觉而补之","f":"五言古诗","c":["此心淡无著，与物常欣然。","虚闲偶有见，白云在空间。","爱之欲吐玩，恐为时俗传。","逡巡自失去，云散空长天。","永愧陶彭泽，佳句如珠圆。"]},{"t":"子瞻闻瘦以诗见寄次韵","f":"七言古诗","c":["多生习气未除肉，长夜安眠懒食粥。","屈伸久已效熊虎，倒挂渐拟同蝙蝠。","众笑忍饥长杜门，自恐莫年还入俗。","经旬辄瘦骇邻父，未信脑满添黄玉。","海夷旋觉似齐鲁，山蕨仍堪尝菽粟。","孤船会复见洲渚，小车未用安羊鹿。","海南老兄行尤苦，樵爨长须同一仆。","此身所至即所安，莫同归期两黄鹄。"]},{"t":"子瞻寄示岐阳十五碑","f":"五言古诗","c":["堂上岐阳碑，吾兄所与我。","吾兄自善书，所取无不可。","欧阳弱而立，商隐瘦且椭。","小篆妙诘曲，波字美婀娜。","谭藩居颜前，何类学颜颇。","魏华自磨淬，峻秀不包裹。","九成刻贤俊，磊落杂幺么。","英公与褒鄂，戈戟闻自荷。","何年学操笔，终岁惟箭笴。","书成亦可爱，艺业嗟独夥。","余虽谬学文，书字每慵堕。","车前驾骐骥，车后系羸跛。","逾年学举足，渐亦行駊騀。","古人有遗迹，䈕短不及锁。","愿从兄发之，洗砚处兄左。"]},{"t":"子瞻惠双刀","f":"五言古诗","c":["彭城一双刀，黄金错刀镮。","脊如双引绳，色如青琅玕。","开匣飞电落，入手清霜寒。","引之置膝上，凛然愁肺肝。","我衰气力微，览镜毛发斑。","誓将斩鲸鲵，静此沧海澜。","又欲戮犀兕，永息行路难。","有志竟不从，抚刀但长叹。","投刀泪如霰，北斗空阑干。","归来刈蓬蒿，锄田植芳兰。","惜刀不忍用，用亦非所便。","弃置尘土中，坐使锋刃刓。","床头夜生光，知有蛟龙蟠。","惭君赠我意，时取一磨看。"]},{"t":"广福僧智昕西归","f":"五言古诗","c":["老人寄东岩，萧然四无邻。","八尺清冷泉，中有白发人。","婆娑弄明月，松间夜相宾。","平生指庚壬，终老投此身。","筑室颍川市，西望长悲辛。","故山比丘僧，茧足超峨岷。","归涂三千里，秋风入衣巾。","北崦百步外，我梦一室新。","速营三间堂，永奉两足尊。","我归要有时，久远与子亲。","悟老非凡僧，瓦砾化金银。","归来味玄言，见日当自陈。"]},{"t":"马上见卖芍药戏赠张厚之二绝 其一","f":"七言绝句","c":["春风欲尽无寻处，尽向南园芍药中。","过尽此花真尽也，此生应与此花同。"]},{"t":"中秋见月寄子瞻","f":"七言古诗","c":["西风吹暑天益高，明月耿耿分秋毫。","彭城闭门青嶂合，卧听百步鸣飞涛。","使君携客登燕子，月色着人冷如水。","筵前不设鼓与钟，处处笛声相应起。","浮云卷尽流金丸，戏马台西山郁蟠。","杯中渌酒一时尽，衣上白露三更寒。","扁舟明日浮古汴，回首逡巡陵谷变。","河吞巨野入长淮，城没黄流只三版。","明年筑城城似山，伐木为堤堤更坚。","黄楼未成河已退，空有遗迹令人看。","城头见月应更好，河流深处今生草。","子孙幸免鱼鳖食，歌舞聊宽使君老。","南都从事老更贫，羞见青天月照人。","飞鹤投笼不能出，曾是彭城坐中客。"]},{"t":"中秋夜八绝 其一","f":"五言绝句","c":["长空开积雨，清夜流明月。","看尽上楼人，油然就西没。"]},{"t":"书郭熙横卷","f":"词","c":["凤阁鸾台十二屏，屏上郭熙题姓名。","崩崖断壑人不到，枯松野葛相攲倾。","黄散给舍多肉食，食罢起爱飞泉清。","皆言古人不复见，不知北门待诏白发垂冠缨。","袖中短轴才半幅，惨澹百里山川横。","岩头古寺拥云木，沙尾渔舟浮晚晴。","遥山可见不知处，落霞断雁俱微明。","十年江海兴不浅，满帆风雨通宵行。","投篙椓杙便止宿，买鱼沽酒相逢迎。","归来朝中亦何有，包裹观阙围重城。","日高困睡心有适，梦中时作东南征。","眼前欲拟要真物，拂拭束绢付与汾阳生。"]},{"t":"六月十三日病起走笔寄仇池","f":"五言古诗","c":["入伏节气变，翛然如九秋。","墙上有短树，庭下风飕飕。","风来吹我衣，虻蚋各已收。","移床就堂下，仰见月成钩。","但与支体快，不作腑脏谋。","半夜起寒热，展转脱水鳅。","药剂失先后，欲速反见留。","不免召杨子，把臂揣厥由。","笑我冷治冷，徒尔苦舌喉。","授我桂与姜，乃始与病投。","逾旬不出户，映牖披重裘。","遥闻南山下，不与他土侔。","山寒雪不解，清气昼夜浮。","馀冷入市城，烦热遭濯漱。","况乃郡斋静，满地贮清流。","露湿荷叶净，月上松柏幽。","墙头白杨树，秋声无时休。","夜蜩感寒气，上树鸣啾啾。","野鹤弄池水，落拍翅羽修。","此处虽可爱，慎勿恣意游。","凡人爱凉冷，凉冷乃热雠。","试扫北窗下，静卧却所忧。","屏扇去冰雪，虚室风自油。","岁热强自厚，良药彼有不。"]},{"t":"厅前柏","f":"五言古诗","c":["稚柏如婴儿，冉冉三尺长。","移根出涧石，植干对华堂。","重露恣膏沐，清风时抑扬。","我老不耐寒，怜汝堪风霜。","朝夕望尔长，尺寸常度量。","知非老人伴，可入诸孙行。","想见十年后，檐前蔚苍苍。","人来顾汝笑，诵我此诗章。"]},{"t":"双凫观","f":"七言律诗","c":["王乔西飞朝洛阳，飘飘千里双凫翔。","凫飞遭网不能去，惟有空屦凫已亡。","谁知野鸟不能化，岂必双屦能飞扬。","凫神屦怪当有在，搔首野庙春风长。"]},{"t":"孔毅父封君挽词二首 其一","f":"五言律诗","c":["交契良人厚，家风季妇贤。","诗书中有助，蘋藻岁无愆。","象服期他日，恩封属此年。","神伤自不觉，吊客问潸然。"]},{"t":"文与可学士墨君堂","f":"五言古诗","c":["虚堂竹丛间，那复厌竹远。","风庭响交戛，月牖散凌乱。","尚恐昼掩关，婵娟不长见。","中堂开素壁，萧飒起霜干。","随宜赋生意，落笔皆葱茜。","根茎杂土石，枝叶互长短。","依依露下绿，冉冉风中展。","开门视丛薄，与此终何辨。"]},{"t":"方筑西轩穿地得怪石","f":"七言古诗","c":["卞氏平日本富家，庭中怪石蹲麇麚。","子孙分散不复惜，排弃坑谷埋泥沙。","一株跃出随畚锸，知我开轩方种花。","颓然远岭垂涧壑，豁然洞穴通烟霞。","十夫徙置幸不远，轩前桐柏阴交加。","我家旧隐久不到，小池尺水三流槎。","少年旋绕看不足，时呼野老来煎茶。","老人得此且自慰，更访馀石探幽遐。"]},{"t":"木冰","f":"七言古诗","c":["老病不眠知夜寒，晨兴薄冰满庭前。","枯榆老柳变精妍，细稍如苗粗如椽。","风敲碎玉落纷然，冰裹槲叶谁雕镌。","邻家父老呼东垣，欲沽官酒囊无钱。","我亦强起试一观，树稼不见今十年。"]},{"t":"毛君惠温柑荔支二绝 其一","f":"七言绝句","c":["楚山黄橘弹丸小，未识洞庭三寸柑。","不有风流吴越客，谁令千里送江南。"]},{"t":"毛国镇生日二绝 其一","f":"七言绝句","c":["生日元同小赵公，里闾相接往还通。","怪公日夜归心切，欲寄此生丹灶中。"]},{"t":"王公生日","f":"五言古诗","c":["纯阴十月晚，劲气肃群骄。","惟有乔松在，长看积雪消。","生贤禀真性，特立冠当朝。","早岁初成赋，群雄已失标。","治才精破竹，廷论壮生飙。","博士皆推贾，宣皇重试萧。","周旋穷政体，出入解心焦。","九列高称冠，三台岂足超。","论功归颍霸，举相待虞姚。","骥骋经新卧，弓强发久弨。","百年时节在，四海众心翘。","当见飞中使，赍金赐此朝。"]},{"t":"王君贶宣徽挽词三首 其一","f":"五言律诗","c":["妙年收贾傅，白首贵王阳。","志气文章在，功名岁月长。","遗孙依旧德，故吏满诸方。","河朔三持节，斯民定不忘。"]},{"t":"王诜都尉宝绘堂词","f":"词","c":["侯家玉食绣罗裳，弹丝吹竹喧洞房。","哀歌妙舞奉清觞，白日一醉万事忘。","百年将种存慨慷，西取庸蜀践戎羌。","战袍赐锦盘雕章，宝刀玉玦馀风霜。","天孙渡河夜未央，功臣子孙白且长。","朱门甲第临康庄，生长介胄羞膏粱。","四方宾客坐华堂，何用为乐非笙簧。","锦囊犀轴堆象床，竿叉连幅翻云光。","手披横素风飞扬，长林巨石插雕梁。","清江白浪吹粉墙，异花没骨朝露香。","挚禽猛兽舌腭张，腾踏騕袅联骕骦。","喷振风雨驰平冈，前数顾陆后吴王。","老成虽丧存典常，坐客不识视茫洋。","骐驎飞烟郁芬芳，卷舒终日未用忙。","游意淡泊心清凉，属目俊丽神激昂。","君不见伯孙孟孙俱猖狂，干时与事神弗臧。"]},{"t":"见儿侄唱酬次韵五首 其五","f":"五言律诗","c":["西湖虽不到，甘井窃馀凉。","三伏罢饮酒，桂浆携一觞。","冠者五六人，起舞互低昂。","人生有离合，此欢未易忘。"]},{"t":"见儿侄唱酬次韵五首 其四","f":"五言律诗","c":["身病要须闲，闲极自成趣。","空虚虽近道，懒拙初非悟。","偶将今生脚，还着古人屦。","大小适相同，本来无别处。"]},{"t":"见儿侄唱酬次韵五首 其三","f":"五言律诗","c":["宇宙非不宽，闭门自为阻。","心知外尘恶，且忍闲居苦。","跏趺默非睡，龛灯翳复吐。","道士为我言，婴儿出歌舞。"]},{"t":"见儿侄唱酬次韵五首 其二","f":"五言律诗","c":["读书虽不恶，不读亦自好。","根牙就区别，花实随时老。","耘锄不可无，雨露勿忧少。","我钓不在鱼，一竿寄洲岛。"]},{"t":"见儿侄唱酬次韵五首 其一","f":"五言律诗","c":["芝兰生吾庐，一雨一增茜。","本亦何预人，怀抱终眷眷。","老傅时已迫，尘垢日须浣。","永惭旧文书，展读不终卷。"]},{"t":"风雪","f":"五言古诗","c":["冬温未宜人，风雪中夜止。","疾雷略吾窗，轻冰入吾被。","病去适三日，惊起存一气。","心安气亦安，二物本非二。","皎然一寸灯，下烛九泉底。","物来无不应，物去未尝昧。","恨我俗缘深，挠此古佛智。","医来视六脉，六脉非昔比。"]},{"t":"风痹三作","f":"五言古诗","c":["年老百病生，风痹已三作。","主家长患聋，说法仍害脚。","十年学趺坐，从此罢雀跃。","闭目时自观，寸田饱耕凿。","下种本无种，服药亦非药。","田熟根自生，病去如花落。","吾生默已定，有数谁能却。","数尽吾则行，未应堕冥漠。"]},{"t":"丙戌十月二十三日大雪","f":"五言古诗","c":["秋成粟满仓，冬藏雪盈尺。","天意悯无辜，岁事了不逆。","谁言丰年中，遭此大泉厄。","肉好虽甚精，十百非其实。","田家有馀粮，靳靳未肯出。","闾阎但坐视，悯悯不得食。","朝饥愿充肠，三五本自足。","饱食就茗饮，竟亦安用十。","奸豪得巧便，轻重窃相易。","邻邦谷如土，胡越两不及。","闲民本无赖，翩然去井邑。","土著坐受穷，忍饥待捐瘠。","彼哉陶钧手，用此狂且愎。","天且无奈何，我亦长太息。"]},{"t":"东方书生行","f":"七言古诗","c":["东方书生多愚鲁，闭门诵书口生土。","窗中白首抱遗编，自信此书传父祖。","辟雍新说从上公，册除仆射酬元功。","太常弟子不知数，日夜吟讽如寒虫。","四方窥觇不能得，一卷百金犹复惜。","康成颖达弃尘灰，老聃瞿昙更出入。","旧书句句传先师，中途欲弃还自疑。","东邻小儿识机会，半年外舍无不知。","乘轻策肥正年少，齿疏唇腐真堪笑。","是非得失付它年，眼前且买先腾踔。"]},{"t":"冬至日作","f":"七言古诗","c":["羲和飞辔留不住，小儿逢节喜欲舞。","人言老翁似小儿，烝豚酿酒多为具。","颍川本自非吾乡，邻里十年成旧故。","谁令闭户谢往还，寿酒独向儿孙举。","饮罢跏趺闭双目，寂然自有安心处。","心安自谓无老少，不知须发已如素。","似闻钱重薪炭轻，今年九九不难数。"]},{"t":"冬至雪","f":"五言古诗","c":["旱久魃不死，连阴未成雪。","微阳九地来，颠风三日发。","父老窃相语，号令风为节。","讲武罢冬夫，畿甸休保甲。","累囚出死地，冗官去烦杂。","手诏可人心，吾君信明哲。","风频雪犹吝，来岁恐无麦。","天公听一言，惟幸早诛魃。"]},{"t":"北京送孙曼叔屯田权三司开坼司","f":"五言古诗","c":["人生不愿才，才士困奔走。","君为大农属，求暇更能否。","自我游魏博，相识恨未久。","谁言但倾盖，信有胜白首。","清晨坐风观，落日语凉牖。","棋精动如律，弓健不论斗。","旁观我不能，晤语君见受。","秋风起沙漠，凄雨湿征袖。","送行欲汲汲，富贵恐君后。","将去聊迟迟，已远悲朋友。"]},{"t":"北堂","f":"五言古诗","c":["吾庐虽不华，粗有南北堂。","通廊开十窗，爽气来四方。","风长日气远，六月有馀凉。","儿女避不居，留此奉爷娘。","爷娘发如丝，不耐寒暑伤。","单衣蕉葛轻，软饭菘芥香。","无客恣卧起，有客罗壶觞。","今年得风痹，摩膏沃椒汤。","念终舍此去，故山松柏苍。","此地亦何为，岁时但烝尝。"]},{"t":"卢鸿草堂图","f":"五言古诗","c":["昔为太室游，卢岩在东麓。","直上登封坛，一夜茧生足。","径归不复往，峦壑空在目。","安知有十志，舒卷不盈幅。","一处一卢生，裘褐荫乔木。","方为世外人，行止何须录。","百年入箧笥，犬马同一束。","嗟予缚世累，归来有茅屋。","江干百亩田，清泉映修竹。","尚将逃姓名，岂复上图轴。"]},{"t":"去年冬辙以起居郎入侍迩英讲不逾时迁中书舍人虽忝冒愈深而瞻望清光与日俱远追记当时所见作四绝句呈同省诸公 其一","f":"七言绝句","c":["迩英肃肃晓霜清，玉宇时闻槁叶零。","风过都城吹广内，万人笑语落中庭。"]},{"t":"司马君实端明独乐园","f":"七言古诗","c":["子嗟丘中亲艺麻，邵平东陵亲种瓜。","公今归去事农圃，亦种洛阳千本花。","修篁绕屋韵寒玉，平泉入畦纡卧蛇。","锦屏奇种斸岩窦，嵩高灵药移萌芽。","城中三月花事起，肩舆遍入公侯家。","浅红深紫相媚好，重楼多叶争矜誇。","一枝盈尺不论价，十千斗酒那容赊。","归来曳履苔径滑，醉倒闭门春日斜。","车轮班班走金毂，印绶若若趋朝衙。","世人不顾病杨绾，弟子独有穷侯芭。","终年著书未曾厌，一身独乐谁复加。","宦游嗟我久尘土，流转海角如浮槎。","归心每欲自投劾，孺子渐长能扶车。","过门有意奉谈笑，幅巾怀刺无袍靴。"]},{"t":"四十一岁岁莫日歌","f":"七言古诗","c":["小儿不知老人意，贺我明年四十二。","人生三十百事衰，四十已过良可知。","少年读书不晓事，坐谈王霸了不疑。","脂车秣马试长道，一日百里先自期。","不知中途有陷阱，山高日莫多棘茨。","长裾大袖足溯挽，却行欲返筋力疲。","蝮蛇当前猛虎后，脱身且免充朝饥。","归来掩卷泪如雨，平生读书空自误。","山中故人一长笑，布衣脱粟何所苦。","古人知非不嫌晚，朝来闻道行当返。","四十一岁不可言，四十二岁聊自还。"]},{"t":"四月二十八日新热寄仇池","f":"七言古诗","c":["细莎为屦如编须，轻葛为服如剪莩。","寒泉洒屋朝露濡，霜簟可荐机可扶。","风鸣牖间如吹竽，此虽有暑宜亦无。","庭前峻山槎之馀，盆中养鳅大如鱼。","荻生抱甲未见肤，蔓起上屋将悬壶。","麦苗高齐可藏乌，此虽非野仅亦如。","兄居溪堂南山趺，濯足溪水惊雁凫。","澄潭百丈清无淤，将往思我立踟蹰。","东轩鄙陋何足居，欲行不行系辕驹。"]},{"t":"外孙文九伏中入村晒麦","f":"七言古诗","c":["春田不雨忧无麦，入囷得半犹足食。","伏中一晒不可缓，旱田苍耳犹难得。","人言春旱夏当潦，入伏未保天日好。","老农经事言不虚，防风防雨如防盗。","外孙读书旧有功，五言七字传祖风。","旋投诗笔到田舍，知我老来馋且慵。","秋田正急车难起，汗滴肩赪愧邻里。","磨声细转雪花飞，举家百口磨牙齿。","食前方丈我所无，烝饼十字或有诸。","孙归何用慰勤苦，烹鸡亦有烝胡卢。"]},{"t":"正旦夜梦李士宁过我谈说神怪久之草草为具仍以一小诗赠之","f":"七言绝句","c":["先生惠然肯见客，旋买鸡豚旋烹炙。","人间饮食未须嫌，归去蓬壶却无吃。"]},{"t":"用林侄韵赋雪","f":"五言古诗","c":["密雪来何晚，穷冬候欲差。","投空落细米，布地净平沙。","缭绕飞相著，重仍积暗加。","雨微花破碎，风细脚倾斜。","次第来如掺，冥濛堕不哗。","燖鹅吹劲鞴，秀苇拂轻耞。","画字飘还没，团毬暖旋窊。","出盐东海若，鍊石古皇娲。","翻簸腾归骑，纷飘集晚鸦。","庭梅辨红萼，垄麦覆黄芽。","拨砌求新药，寻踪射伏䴥。","埋楼平尽脊，集树短留槎。","乱下曾何择，平铺欲尽遮。","欺贫寒入褐，恼客重添车。","积素聊成烛，烹甘强试茶。","病僧添晓钵，老令放晨衙。","融液曾何有，鲜明竟不奢。","积多还避井，化早发从畬。","溜滴檐垂箸，行观径转蛇。","谁能相就醉，都市酒容赊。"]},{"t":"白须","f":"七言律诗","c":["少年不办求良药，老病无疑生白须。","下种已迟空怅望，无心犹幸省工夫。","虚明对面谁知我，宠辱当前莫问渠。","自顷闭门今十载，此生毕竟得如愚。"]},{"t":"白须","f":"五言古诗","c":["中岁谬学道，白须何由生。","故人指我笑，闻道未能行。","我笑谢故人，唯唯亦否否。","老聃古道师，白发生而有。","佛告波斯匿，汝有不白存。","亭中掌亭人，何尝随客奔。","客去不用留，主在亭不毁。","墁墙支折栋，在我不在尔。","道成款玉晨，跪乞五色丸。","肝心化黄金，齿发何足言。"]},{"t":"石苍舒醉墨堂","f":"五言古诗","c":["石君得书法，弄笔岁月久。","经营妙在心，舒卷功随手。","惟兹逸群气，扶驾须斗酒。","作堂名醉墨，挥洒动墙牖。","安得浊酒池，淋漓看濡首。","但取继张君，莫顾颠名丑。"]},{"t":"示资福谕老","f":"五言古诗","c":["幽居百无营，孤坐若假寐。","根尘两相接，逆流就一意。","意念纷无端，中止不及地。","寂然了无觉，乃造真实际。","百川入沧溟，众水皆一味。","止为潭渊深，动作涛澜起。","动止初何心，乃遇适然耳。","吾心未尝劳，万物将自理。"]},{"t":"立冬闻雷","f":"五言古诗","c":["阳淫不收敛，半岁苦常燠。","禾黍饲蝗螟，粳稻委平陆。","民饥强扶耒，秋晚麦当宿。","闵然候一雨，霜落水泉缩。","荟蔚山朝隮，滂沱雨翻渎。","经旬势益暴，方冬岁愈蹙。","半夜发春雷，中天转车毂。","老夫睡不寐，稚子起惊哭。","平明视中庭，松菊半摧秃。","潜发枯草萌，乱起蛰虫伏。","薪槱不出市，晨炊午未熟。","首种不入土，春饷难满腹。","书生信古语，洪范有遗牍。","时无中垒君，此意谁当告。"]},{"t":"记岁首乡俗寄子瞻二首 其二 蚕市","f":"七言古诗","c":["枯桑舒牙叶渐青，新蚕可浴日晴明。","前年器用随手败，今冬衣着及春营。","倾囷计口卖馀粟，买箔还家待种生。","不惟箱篚供妇女，亦有锄镈资男耕。","空巷无人斗容冶，六亲相见争邀迎。","酒肴劝属坊市满，鼓笛繁乱倡优狞。","蚕丛在时已如此，古人虽没谁敢更。","异方不见古风俗，但向陌上闻吹笙。"]},{"t":"记病","f":"五言古诗","c":["我病在脾胃，一病四十年。","微伤辄暴下，倾注如流泉。","去年医告我，此病犹可痊。","试取姜豆附，三物相和丸。","服之不旬浃，病去如医言。","医言药有毒，病已当速捐。","我意药有功，服久功则全。","侵寻作风痹，两足几蹒跚。","徐悟药过量，医初固云然。","旧病则已除，奈此新病缠。","医言无甚忧，前药姑舍旃。","药毒久自消，真气从此完。","鄙夫不信医，私智每自贤。","咄哉已往咎，终身此韦弦。"]},{"t":"龙川道士","f":"五言古诗","c":["昔我迁龙川，不见平生人。","倾囊买破屋，风雨庇病身。","颀然一道士，野鹤堕鸡群。","飞鸣闾巷中，稍与季子亲。","刺口问生事，褰裳观运斤。","俯仰忽三年，愈久意愈真。","送我出重岭，长揖清江滨。","方营玉皇宫，栋宇期一新。","成功十年后，脱身走中原。","见公心自足，徒步非我勤。","我归客箕颍，昼日长掩关。","仆夫忽告我，门有万里宾。","问其所从来，笑指南天云。","心知故人到，惊喜不食言。","我老益不堪，惟有二顷田。","年年种麦禾，仅能免饥寒。","君来亦何为，助我耕且耘。","嗟古或有是，今世非所闻。"]},{"t":"买炭","f":"五言古诗","c":["苦寒搜病骨，丝纩莫能禦。","析薪燎枯竹，勃郁烟充宇。","西山古松栎，材大招斤斧。","根槎委溪谷，龙伏熊虎踞。","挑抉靡遗馀，陶穴付一炬。","积火变深黳，牙角犹愤怒。","老翁拥破毡，正昼出无屦。","百钱不满篮，一坐幸至莫。","御炉岁增贡，圆直中常度。","闾阎不敢售，根节姑付汝。","升平百年后，地力已难富。","知夸不知啬，俯首欲谁诉。","百物今尽然，岂为一炭故。","我老或不及，预为子孙惧。"]},{"t":"任氏阅世堂前大桧","f":"七言古诗","c":["君家大桧长百尺，根如车轮身弦直。","壮夫连臂不能抱，孤鹤高飞直上立。","狂风动地舞枝干，大雪翻空洗颜色。","人言此桧三百年，未知昔是何人植。","君家大夫老不遇，一生使气未尝屈。","没身不说归故里，遗爱自知怀旧邑。","此翁此桧两相似，相与阅世何终极。","汝南山浅无良材，栎柱栋椽聊障日。","便令杀身起大厦，亦恐众材无匹敌。","且留枝叶挠云霓，犹得世人长太息。"]},{"t":"伐双谷","f":"五言古诗","c":["芳兰非不嘉，当门自宜锄。","矧此恶木阴，久妨长者车。","仆夫砺寻斧，告我日方除。","久持不忍意，柯条益扶疏。","植根虽云固，伐去曾须臾。","我涂虽不宽，出入自有馀。","开门听还往，并纳贤与愚。","荒秽一朝尽，来者皆虚徐。"]},{"t":"再次前韵示元老","f":"五言古诗","c":["豪杰多自悟，不待文王兴。","四方有馀师，十室岂无朋。","我老不知时，早岁谁误称。","归来理茅屋，对客食藜蒸。","遇渴即饮水，何尝问淄渑。","冠裳强包裹，毁誉如飞蝇。","植根久已尔，苕颖日自升。","忘我亦忘法，无冰知消冰。"]},{"t":"再和十首 其一","f":"七言绝句","c":["涧草岩花日日开，江南秋尽似春回。","旋开还落无人顾，惟有山蜂暖尚来。"]},{"t":"同子瞻次过远重字韵","f":"七言古诗","c":["孟子自誇心不动，未试永嘉铁轮重。","弟兄六十老病馀，万里同遭海隅送。","长披羊裘类严子，罢食猪肝同闵仲。","大男留处事田亩，幼子随行躬釜瓮。","低眉语笑接邻父，弹指吁嗟到蛮洞。","茅茨一日敢忘葺，桑柘十年须勉种。","来时邂逅得相携，归去逡巡应复从。","莫惊忧患尔来同，久知出处平生共。","虽令子孙治家学，休炫文章供世用。","颍川筑室久未成，夜来忽作西湖梦。"]},{"t":"同子瞻次梅圣俞旧韵题乡舍木山","f":"七言古诗","c":["江槎出没浮犀牛，波涛掀天谷为洲。","江寒水落惊霜秋，危根瘦节鸣寒流。","脆朽吹去谁镌锼，连峰叠嶂立酋酋。","吾家此山不易得，十年弃置空自尤。","猿号鹤唳岂无意，委蛇怪我怀羔裘。","西归父老拍手笑，笑忆翁子躬薪槱。","去时三山今有五，不问故园惟一丘。"]},{"t":"同子瞻泛汴泗得渔酒二咏 其一","f":"五言律诗","c":["江湖性终在，平地难久居。","渌水雨新涨，扁舟意自如。","河身萦疋素，洪口转千车。","愿言弃城市，长竿夜独渔。"]},{"t":"同子瞻泛汴泗得渔酒二咏 其二","f":"五言律诗","c":["懒思久废诗，病肠不堪酒。","强颜水石间，滥迹宾主后。","不知白浪翻，但怪青山走。","莫随使车尘，岂畏严城斗。"]},{"t":"同孔常父作张夫人诗","f":"五言古诗","c":["女子勿言弱，男儿何必强。","君看张夫人，身举十五丧。","头上脱笄珥，箧中斥襦裳。","筑坟连丘山，松柏郁苍苍。","亲戚不为助，涕泣感道傍。","昔有王氏老，身为尚书郎。","亲死弃不葬，簪裾日翱翔。","白骨委庐陵，宦游在岐阳。","一旦有丈夫，轩轩类佯狂。","相面识心腹，开口言灾祥。","嗟汝平生事，不了令谁当。","汝身暖丝绵，汝口甘稻粱。","衣食未尝废，此事乃可忘。","一言中肝心，投身拜其床。","傍人漫不知，相视空茫茫。","终言汝不悛，物理久必偿。","儿女病手足，相随就沦亡。","鄙夫本愚悍，过耳风吹墙。","明年及前期，长子忧骭疡。","一麾守巴峡，双柩还故乡。","弱息虽仅存，蹒跚亦非良。","谁言天地宽，网目固自张。","古事远不信，近事世所详。","企张非求福，祸败当惩王。"]},{"t":"同王适曹焕游清居院步还所居","f":"五言古诗","c":["身为江城吏，心似野田叟。","寻僧忽忘归，饱食莫携手。","畏人久成性，路绕古城后。","茅茨远相望，鸡犬亦时有。","人还市井罢，日落狐兔走。","回风吹横烟，烧火卷林薮。","草深径渐恶，荆棘时挂肘。","褰裳涉沮洳，斜绝污池口。","投荒分岑寂，攲侧吾自取。","二君独何为，经岁坐相守。","游从乏车骑，饮食厌菘韭。","周旋未忍弃，辛苦亦何负。","归来倚南窗，试挹樽中酒。","笑问黄泥行，此味还同否。"]},{"t":"同王适赋雪","f":"七言古诗","c":["北风吹雨雨不断，遍满虚空作飞霰。","纸窗独卧不成眠，茅屋无声时一泫。","鸟乌错莫寒未起，庭户空明夜惊旦。","重楼复阁烂生光，绝涧连山漫不见。","夹砌双杉洗更碧，满田碧草埋应烂。","城中闭户无履迹，市上孤烟数晨爨。","细排玉箸短垂檐，暗结轻冰时入研。","拨灰有客顾尊俎，迹兔何人试鹰犬。","未容行役扫车毂，应有老农歌麦饭。","一来江城若俄顷，四见白花飞面旋。","坐看酒瓮谁敢尝，归踏冰泥屡成溅。","年来桥板断不属，莫出肩舆足忧患。","到家昏黑空自笑，诉妇勤劳每长叹。","床头有酒未用沽，囊里无钱不劳算。","更令雪片大如手，终胜溪瘴长熏眼。","谒告犹能不出门，典衣共子成高宴。"]},{"t":"同李倅钧访赵嗣恭留饮南园晚衙先归","f":"七言古诗","c":["城南高楼出乔木，下有方塘秋水足。","新霜未变草木鲜，晚日旋催梨枣熟。","雨荒松菊半榛莽，风老菰蒲初瑟缩。","门前大路多尘土，日中过客无留毂。","开门却扫如有待，下马升堂真不速。","劝我一振衣上黄，临风共倒樽中渌。","肴蔬草草意不尽，丝竹泠泠暗相属。","琳宫仙伯自閒暇，幕府粗官苦烦促。","晚衙簿领当及期，后堂车辖要须漉。","令人更愧东宫师，眷恋溪山弃华屋。"]},{"t":"吕司空挽词三首 其一","f":"五言律诗","c":["少年轻富贵，一意在诗书。","共恨经纶晚，才收老病馀。","寡言知德胜，善应本中虚。","卒相承平业，讴歌元祐初。"]},{"t":"吕希道少卿松局图","f":"五言古诗","c":["溪回山石间，苍松立四五。","水深不可涉，上有横桥渡。","溪外无居人，磐石平可住。","纵横远山出，隐见云日莫。","下有四老人，对局不回顾。","石泉杂风松，入耳如暴雨。","不闻人世喧，自得山中趣。","何人昔相遇，图画入纨素。","尘埃依古壁，永日奉樽俎。","隐居畏人知，好事竟相误。","我来再三叹，空有飞鸿慕。","逝将从之游，不惜烂樵斧。"]},{"t":"因旧","f":"词","c":["君不见林上鹊，冬深始营巢，及春巢已成。","又不见梁上燕，春深初作窠，及夏雏已生。","我为一区屋，三年费经营。","纷纷伐梧楸，日厌斤斧声。","老境能几何，何日安馀龄。","一言愧吾儿，事忌与力争。","青杨易三栋，赤榆换双楹。","指顾行即具，构筑役亦轻。","酂侯念子孙，不处高闬闳。","吾今何人斯，此则坐右铭。"]},{"t":"安厚卿枢密母夫人挽词二首 其一","f":"五言律诗","c":["家起侧微中，身兼富贵终。","慈仁本宜寿，勤约自成风。","大府宁居久，名邦赐沐雄。","共传生子福，仍指读书功。"]},{"t":"戏作家酿二首 其二","f":"五言古诗","c":["我饮半合耳，晨兴不可无。","千钱买一斗，众口分须臾。","月俸本有助，法许吏未俞。","悯悯坐相视，馋涎落盘盂。","颍潩旧乏水，粳糯贵如珠。","今年利陂堨，碓声喧里闾。","典衣易钟釜，入瓮生醍醐。","欢欣走童孺，左右陈肴蔬。","细酌奉翁媪，馀润沾庖厨。","诘朝日南至，相戒留全壶。","一家有喜色，经冬可无沽。","莫怪杜拾遗，斗水宽忧虞。"]},{"t":"戏作家酿二首 其一","f":"五言古诗","c":["方暑储曲糵，及秋舂秫稻。","甘泉汲桐柏，火候问邻媪。","唧唧鸣瓮盎，暾暾化梨枣。","一拨欣已熟，急搊嫌不早。","病色变渥丹，羸躯惊醉倒。","子云多交游，好事时相造。","嗣宗尚出仕，兵厨可常到。","嗟我老杜门，奈此平生好。","未出禁酒国，耻为瓮间盗。","一醉汁滓空，入腹谁复告。"]},{"t":"戏题菊花","f":"七言律诗","c":["春初种菊助槃蔬，秋晚开花插酒壶。","微物不多分地力，终年乃尔任人须。","天随匕箸几时辍，彭泽樽罍未遽无。","更拟食根花落后，一依本草太伤渠。"]},{"t":"收蜜蜂","f":"七言古诗","c":["空中蜂队如车轮，中有王子蜂中尊。","分房减口未有处，野老解与蜂语言。","前人传蜜延客住，后人秉艾催客奔。","布囊包裹闹如市，坌入竹屋新且完。","小窗出入旋知路，幽圃首夏花正繁。","相逢处处命俦侣，共入新宅长子孙。","今年活计知尚浅，蜜蜡未暇分主人。","明年少割助和药，惭愧野老知利源。"]},{"t":"早睡","f":"五言古诗","c":["老人如婴儿，起晏睡常早。","粗毡薄絮被，孤枕自媚好。","倒床作龟息，逡巡辄复觉。","隔门灯火明，仿佛闻语笑。","杯棬相劝酬，往往见讥诮。","披衣坐跏趺，衰老当自了。","室空窗亦虚，半夜明月到。","老卢下种法，从古无此妙。","根生花辄开，得者自不少。","要须海底行，更问药山老。"]},{"t":"杀麦二首 其一","f":"五言律诗","c":["麦幸十分熟，雨过三日霪。","初晴尚未伏，半夜卷重阴。","细筑场无隙，轻推磨有音。","惊闻诸县水，一晒直千金。"]},{"t":"杂兴二首 其一","f":"七言古诗","c":["陋巷丈夫病且贫，悬鹑百结聊庇身。","蠕蠕大虱长孙子，败缯敝絮开阳春。","故襦宽博裹肩䏶，出没逡巡初莫畏。","一朝换酒入邻家，顾视腰间犹犊鼻。","入缝循腰还自足，肌肤转近尤为福。","咋皮吮血无已时，应待渠家具汤沐。"]},{"t":"次子瞻夜字韵作中秋对月二篇一以赠王郎二以寄子瞻 其一","f":"七言古诗","c":["平明坐曹黄昏归，终岁得闲惟有夜。","已邀明月出墙东，更遣清风扫庭下。","城上青鬟四山合，门前白练长江泻。","谁家高会吹参差，邻妇悲歌舂罢亚。","二年忧患今已过，一夜清光天所借。","西京诗句出苏李，南国风流数王谢。","已随孤棹去中原，肯顾新科求上舍。","读书本自比嵇锻，学剑要须问曹蔗。","清觞滟滟君莫违，佳句骎骎予已怕。","狂夫猖狂终累人，不返行遭亲党骂。"]},{"t":"次远韵","f":"五言古诗","c":["万里谪南荒，三子从一幼。","谬追春秋馀，赖尔牛马走。","忧病多所忘，问学非复旧。","借书里诸生，疑事谁当叩。","吾儿虽懒教，擢颖既冠后。","求友卷中人，玩心竹间岫。","时令检遗阙，相对忘昏昼。","兄来试讴吟，句法渐翘秀。","暂时鸿雁飞，迭发埙篪奏。","更念宛丘子，颀然何时觏。"]},{"t":"次远韵齿痛","f":"五言古诗","c":["元明散诸根，外与六尘合。","流中积缘气，虚妄无可托。","敝陋少空明，妇姑相攘夺。","日出暵焦牙，风来动危萚。","喜汝因病悟，或免终身著。","更须诵楞严，从此脱缠缚。"]},{"t":"次迟韵二首 其二","f":"五言古诗","c":["世事非吾忧，物理有必至。","常旸百川竭，顾亦防雨耳。","阴阳相纠缠，反覆更自治。","幽怀澹不起，默坐识其意。","长子念衰老，远行重惭愧。","疏慵身似僧，岑寂家近寺。","但闻事日新，未觉吾有异。","器锽本自出，藩角徒不遂。","得失众共知，穷达佛所记。","要令北归日，粗究一大事。"]},{"t":"次迟韵二首 其一","f":"五言古诗","c":["老谪江南岸，万里修烝尝。","三子留二子，嵩少道路长。","累以二孀女，辛勤具糇粮。","谁令南飞鸿，送汝至我旁。","饥寒不能病，气纾色亦康。","拊背问家事，嗟我久已忘。","力耕当及春，无为久南方。","还家语诸女，素刚非王章。"]},{"t":"次迟韵对雪","f":"五言古诗","c":["雪寒近可忧，麦熟远有喜。","我生忧喜中，所遇一已委。","平生闻汝南，米贱豚鱼美。","今年恶蝗旱，流民鬻妻子。","一食方半菽，三日已于耜。","号呼人谁闻，悯恻天自迩。","繁阴忽连夕，飞霰堕千里。","卷舒惊太速，原隰殊未被。","贫家望一麦，生事如毛起。","荐饥当逐熟，西去真纳履。"]},{"t":"次迟韵示陈天倪秀才侄孙元老主簿","f":"五言古诗","c":["茅檐有佳客，肃肃清风兴。","吾孙成均来，左右皆良朋。","为怜众兄弟，将冠未有称。","条枚失熂燎，中林化薪蒸。","老夫方苦贫，不办酒如渑。","夏田已失麦，种豆喜多蝇。","何以待君子，箪瓢容一升。","君来岂非误，门庭冷如冰。"]},{"t":"次迟韵复雪","f":"七言古诗","c":["老人怕寒愁早作，夜闻飞霰知相虐。","粟车未到泥复深，场薪欲尽心惊愕。","山川滉荡势如海，孤舟一叶知安泊。","山中故人消息断，欲问有无隔溪壑。","人言王生好事人，回船不顾山阴约。","故侯生来本贫窭，妻子至今美藜藿。","曳履长歌解忍饥，裹饭往饲今谁托。","家人来告酒可刍，洗盏开瓶同一酌。"]},{"t":"次迟韵寄适逊","f":"七言古诗","c":["饥民畏寒尤恶雪，旋理破裘纴败缬。","我虽久客未成归，黍酒齑羹还泼节。","汝雨薪炭旧如土，尔来薄俸才供爇。","眼前暖热无可道，心下清凉有馀洁。","颍川归去知何时，祠宫欲罢无同列。","夜中仿佛梦两儿，欲迓老人先聚说。"]},{"t":"次前韵","f":"七言律诗","c":["心空烦恼不须除，白尽年来罢镊须。","随俗治生终落落，苦心忧世漫区区。","居连里巷知安否，食仰田园问有无。","我已闭门还往绝，待乘明月过君庐。"]},{"t":"次前韵","f":"七言律诗","c":["龙鸾仅比闽团酽，盐酪应嫌北俗粗。","采愧吴僧身似腊，点须越女手如酥。","舌根遗味轻浮齿，腋下清风稍袭肤。","七碗未容留客试，瓶中数问有馀无。"]},{"t":"次前韵答景仁","f":"七言古诗","c":["儒林谈道亦云旧，远自太史牛马走。","区区分别竟何为，扰扰祇添心上垢。","道大如天不可测，异出同归各穿窦。","浩然一水散千沤，却观彼我曾无有。","我丈中心冰玉洁，世上浮荣尽灰灭。","终年行道自不知，笑指空门名异说。","此心未信道不生，石上下种何由茁。","道在起居饮食中，安问胡僧分五叶。"]},{"t":"次烟字韵答黄庭坚","f":"七言律诗","c":["病卧江干须带雪，老捻书卷眼生烟。","贫如陶令仍耽酒，穷似湘累不问天。","令弟近应怜废学，大兄昔许叩延年。","比闻蔬茹随僧供，相见能容醉后颠。"]},{"t":"次韵子瞻人日猎城西","f":"五言古诗","c":["将贤士气振，令肃军声悄。","晨登戏马台，一试胡騕袅。","城空巷无人，里社转相晓。","吾公庶无疾，但恐园囿小。","荆榛一焚荡，雉兔皆惊矫。","翩翩白马将，手把青丝挑。","少小事边徼，斩刈轻荼蓼。","殿前赐鞍勒，珂月明皎皎。","自言得所事，强暴无不了。","庙算本诗书，下策禁焚燎。","当令百鍊刚，甘就一指绕。","低回未尝试，坐被世人少。","秋霜一朝下，凌厉见鸷鸟。","为君整骄惰，重立穰苴表。"]},{"t":"次韵子瞻上元见寄","f":"五言古诗","c":["谁怜东坡老，独看南海灯。","故人隐山麓，燕坐销床棱。","人生天运中，往返成废兴。","炎起爨下薪，冻合瓶中冰。","赖有不变处，寂如方定僧。","建城亦岩邑，灯火高下层。","头陀旧所识，天寒发鬅鬙。","问我何时来，嗟哉谷为陵。","幸此米方贱，日食聊一升。","夜出随众乐，餔糟共腾腾。"]},{"t":"次韵子瞻与邓圣求承旨同直翰苑怀武昌西山旧游","f":"七言古诗","c":["我游齐安十日回，东坡桃李初未栽。","扁舟乱流入樊口，山雨未止淫黄梅。","寒溪闻有古精舍，相与推挽登崔嵬。","山深县令喜客至，寺荒蔓草生经台。","黄鹅白酒得野馈，藤床竹簟无纤埃。","可怜迁客畏人见，共怪青山谁为堆。","行惊晚照催出谷，中止乱石倾馀罍。","古今相望两令尹，文词洒落千山隈。","野人岂复识遗趣，过客时为剜苍苔。","五年留滞屐齿秃，一朝挥手船头开。","玉堂却忆昔游处，笑问五柳应彫摧。","满朝文士蚤贵达，凭凌霄汉乘风雷。","入参秘殿出华省，何曾著足空山来。","漂流邂逅览遗躅，耳中尚有江声哀。"]},{"t":"次韵子瞻与苏世美同年夜饮","f":"词","c":["晚岁事游宦，相从未尝足。","羡君四海皆兄弟，栈中直木不容曲。","临安老令况同科，相逢岂厌樽中醁。","潦倒谁怜涧底松，岁寒尚有霜前竹。","闻道渠家八丈夫，它日归耕免幽独。"]},{"t":"次韵子瞻山村五绝 其一","f":"七言绝句","c":["山行喜遇酒旗斜，无限桃花续杏花。","与世浮沉真避世，将家漂荡似无家。"]},{"t":"次韵子瞻广陵会三同舍各以其字为韵 孙巨源","f":"五言古诗","c":["巨源学从横，世事夙讨论。","著书十万字，辩如白波翻。","谏垣适多事，忧心生病根。","立谈信无补，闭口出国门。","弃置卧江海，闵嘿宁复言。","朝行共长叹，逐客继二孙。","南方固乡党，谪官侣鹤猿。","风俗未宁静，朋党争排跟。","引去良自得，浊清在澄源。","往者未可招，冠盖方骏奔。"]},{"t":"次韵子瞻广陵会三同舍各以其字为韵 刘贡甫","f":"五言古诗","c":["贡甫少多才，交游一何众。","谈词坐倾倒，玉麈日挥弄。","逡巡不为虐，巧捷有微中。","群情忌超迈，微过出嘲讽。","南迁时已久，未见肯力贡。","舌在终自奇，髀满安足痛。","人生百年内，仅比一朝梦。","骎骎就消涸，斗水倾漏瓮。","江淮未可嫌，迟晚聊自送。","试观终日闲，何似两耳哄。"]},{"t":"次韵子瞻广陵会三同舍各以其字为韵 刘莘老","f":"五言古诗","c":["莘老奋徒步，首与观国宾。","俨然自约束，被服韨与绅。","黾勉丞相府，接迹舆台臣。","顾嫌任安躁，未忍裂坐茵。","推置冠獬豸，谓言我比邻。","三晋固多士，肮脏存斯人。","窜责不敢辞，狂言见天真。","南方异风俗，强食鱼尾莘。","应同贾太傅，抱屈耻自陈。","犹有痛哭书，受釐定何辰。"]},{"t":"次韵子瞻书黄庭内景卷后赠蹇道士拱辰","f":"七言古诗","c":["君诵黄庭内外篇，本欲洗心不求仙。","夜视片月堕我前，黑氛剥尽朝日妍。","一暑一寒久自坚，体中风行上通天。","亭亭孤立孰傍缘，至哉道师昔云然。","既已得之戒不传，知我此心未亏骞。","指我婴儿藏谷渊，言未绝口行已旋，我思其言夜不眠。"]},{"t":"次韵子瞻见寄","f":"七言古诗","c":["我将西归老故丘，长江欲济无行舟。","宦游已如马受轭，衰病拟学龟藏头。","三年学舍百不与，糜费廪粟常惭羞。","矫时自信力不足，从政敢谓学已优。","闭门却扫谁与语，昼梦时作钧天游。","自从四方多法律，深山更深逃无术。","众人奔走我独闲，何异端居割蜂蜜。","怀安已久心自知，弹劾未至理先屈。","馀杭军府百事劳，经年未见持干旄。","贾生作傅无封事，屈平忧世多离骚。","烦刑弊法非公耻，怒马奔车忌鞭箠。","藐藐何自听谆谆，谔谔未必贤唯唯。","求田问舍古所非，荒畦弊宅今馀几。","出从王事当有程，去须膰肉嫌无名。","扫除百忧唯有酒，未退聊取身心轻。"]},{"t":"次韵子瞻见寄","f":"五言古诗","c":["衮衮河渭浊，皎皎江汉清。","源流既自异，美恶终未明。","嗟我顽钝质，乃与公并生。","出处每自托，讴吟辄尝赓。","譬如病足马，共此千里程。","胜负坐已决，岂待终一枰。","忆公年少时，濯濯吐新萌。","坚姿映松柏，直节凌榛荆。","学成志益厉，秋霜落春荣。","澹然养浩气，脱屣遗齐卿。","百鍊竟不变，三年终未鸣。","区区两郡守，籍籍四海声。","年来效溯默，世事慵讥评。","不见室家好，恍如揖重城。","别离长尘垢，岁月何峥嵘。","彭门偶会合，白发互相惊。","受教恐不足，吐论那复争。","疾雷发聋聩，清月照昏盲。","笃爱未忍弃，浪云旧齐名。","更请同郭许，题品要当精。"]},{"t":"次韵子瞻发洪泽遇大风却还宿","f":"五言古诗","c":["昨夜宿洪泽，再来遂如归。","却行虽云拙，乘险谅亦非。","谁言淮阴近，阻此骇浪飞。","长风径千里，蛟蜃相因依。","眇然恃一叶，此势安可违。","冒涉彼何人，勇决生虑微。","欲速有不达，鱼腹岂足肥。","风帆尚可转，野庙谁能祈。","但当拥衾睡，慎闭窗与扉。","夜闻声尚恶，起视聊披衣。"]},{"t":"次韵子瞻对月见忆并简崔度","f":"七言古诗","c":["先师客陈未尝饱，弟子于今敢言巧。","败墙破屋秋雨多，夜视阴精过毕昴。","齑盐冷落空杯盘，且依道士修还丹。","丹田发火五脏暖，未补漫漫长夜寒。","我生疲驽恋莝豆，崔翁游边指北斗。","唯有王江亦未归，闭门无客邀沽酒。"]},{"t":"次韵子瞻生日见寄","f":"七言古诗","c":["日月中人照与芬，心虚虑尽气则薰。","彤霞点空来群群，精诚上彻天无云。","寸田幽阙暖不焚，眇视中外绛锦纹。","冥然物我无复分，不出不入常氤氲。","道师东西指示君，乘此飞仙勿留坟。","茅山隐居有遗文，世人心动随虻蚊。","不信成功如所云，蚤夜宾饯同华勋。","尔来仅能破魔军，我经生日当益勤。","公禀正气饮不醺，梨枣未实要锄耘。","日云莫矣收桑枌，西还闭门止纷纷。","忧愁真能散凄焄，万事过耳今不闻。"]},{"t":"次韵子瞻记十月十六日所见","f":"词","c":["君不见天高后土黄，变化出入唯阴阳。","旋凝细雾作飞雹，复遣震雷追日光。","可怜万物甚微细，坐听百变随颠僵。","深根固蒂无计遁，倏来忽返安能防。","平生未见实惊耳，稍远不知如隔墙。","君看歌舞醉华屋，下有累絷排两廊。","眼前苦乐尚悬绝，空中造化知有亡。","我居宛丘厌凝冱，雪翻海水填陂塘。","但知膏泽利牟麦，恣食饼饵真嘉祥。","山阳所记亦何事，有酒胡不尽一觞。"]},{"t":"次韵子瞻记岁莫乡俗三首 其一 馈岁","f":"五言古诗","c":["周公制乡礼，无有相通佐。","鼎肉送子思，烝豚出阳货。","交亲随高低，岂问小与大。","自从此礼衰，伏腊有饥卧。","乡人慕古俗，酬酢等四坐。","东邻遗西舍，迭出如蚁磨。","宁我不饮食，无尔相咎过。","相从庆新春，颜色买愉和。"]},{"t":"次韵子瞻记岁莫乡俗三首 其二 别岁","f":"五言古诗","c":["富贵日月速，贫贱觉岁迟。","迟速不须问，俱作不可追。","亲旧且酣饮，送尔天北涯。","岁岁虽无情，从我历四时。","酌尔一杯酒，留我壮且肥。","长作今岁欢，勿起异日悲。","掉头不肯顾，曾莫与我辞。","酒阑气方横，岂信从尔衰。"]},{"t":"次韵子瞻记岁莫乡俗三首 其三 守岁","f":"五言古诗","c":["于菟绝绳去，顾兔追龙蛇。","奔走十二虫，罗网不及遮。","嗟我地上人，岂复奈尔何。","未去不自闲，将去乃喧哗。","天上驱兽官，为君肯停檛。","鲁阳挥长戈，日车果再斜。","酾酒劝尔醉，期尔暂蹉跎。","偕醉遣尔去，寿考自足誇。"]},{"t":"次韵子瞻再游径山","f":"五言古诗","c":["我兄东南游，我亦梦中去。","径山闻已熟，往意穿云雾。","梦经山前溪，足冷忽先渡。","举头云峰合，到寺霜日莫。","香厨馔岩蔌，野径踏藤屦。","平生共游处，骞足蹑高步。","崎岖每生胝，眩晃屡回顾。","何年弃微官，携手众山路。"]},{"t":"次韵子瞻好头赤","f":"七言律诗","c":["沿边壮士生食肉，小来骑马不骑竹。","翩然赤手挑青丝，捷下巅崖试深谷。","牵入故关榆叶赤，未惯中原暖风日。","黄金络头依圉人，俯听北风怀所历。"]},{"t":"次韵子瞻江西","f":"七言律诗","c":["许君马老共一邦，西山断处流蜀江。","谁令十载重渡泷，滩头旧寺晨钟撞。","乱流赤脚记淙淙，道俗自谓丹霞庞。","便令筑室修畦矼，往还二老筇一双。"]},{"t":"次韵子瞻竹?","f":"词","c":["野食不穿囷，溪饮不盗盎。","嗟?独何罪，膏血自为罔。","阴阳造百物，偏此愚不爽。","肥痴与瘦黠，禀受不相髣。","王孙处深谷，小若儿在襁。","超腾避弹射，将中还复枉。","一朝受羁緤，冠带相宾飨。","愚死智亦擒，临食抵吾掌。"]},{"t":"次韵子瞻自径山回宿湖上","f":"五言古诗","c":["朝从径山来，泱莽径山色。","莫从湖上归，滉漾湖光碧。","借问泛湖舟，何似登山屐。","高怀厌朝市，远去忘忧慄。","目向幽人青，颜从浊醪赤。","尘埃解罗网，宇宙为安宅。","油然了无营，此意谁能诘。","嗟子别离久，欲往徒反侧。","留滞亦何为，空惊突深黑。"]},{"t":"次韵子瞻自普照入山独游二庵","f":"七言古诗","c":["披榛入山山路细，钟声出寺门将闭。","石苔冉冉上芒鞋，草露漙漙著衣袂。","野人茅茨苫竹屋，终身局促无生计。","天公未省长困人，春田米尽秋田继。","老妻稚子亦自乐，野草山花还插髻。","长笑人间醉未醒，终老辛勤漫欺世。"]},{"t":"次韵子瞻行至奉新见寄","f":"五言古诗","c":["四年候公书，长视飞鸿背。","十日留公谈，欲作白莲会。","匏瓜一遭系，卖酒长不在。","夜归步江漘，明月照清濑。","心开忽自得，语异竟非背。","一尊谈笑间，万事寂寥外。","欲同千里行，奈此一官碍。","何年真耦耕，举世无此大。"]},{"t":"次韵子瞻过海","f":"五言古诗","c":["我迁海康郡，犹在寰海中。","送君渡海南，风帆若张弓。","笑揖彼岸人，回首平生空。","平生定何有，此去未可穷。","惜无好勇夫，从此乘桴翁。","幽子疑龙虾，牙须竟谁雄。","闭门亦勿见，一嗅同香风。","晨朝饱粥饭，洗钵随僧钟。","有问何时归，兹焉若将终。","居家出家人，岂复怀儿童。","老聃真吾师，出入初犹龙。","笼樊顾甚密，俯首姑尔容。","众人指我笑，缰锁无此工。","一瞬千佛土，相期兜率宫。"]},{"t":"次韵子瞻过淮见寄兼简孙奕职方三首 其一","f":"五言律诗","c":["出处平生共，江淮恨不来。","宦游良误我，老病赋怀哉。","徇物终今世，量书尽几堆。","归耕少忧患，惟有仰春雷。"]},{"t":"次韵子瞻初到杭州见寄二绝 其一","f":"七言绝句","c":["吏治区区岂不任，吴中已自富才能。","还应占位书名姓，学取蓝田崔县丞。"]},{"t":"次韵子瞻吴中田妇叹","f":"七言古诗","c":["久雨得晴唯恐迟，既晴求雨来何时。","今年舟楫委平地，去年蓑笠为裳衣。","不知天公谁怨怒，弃置下土尘与泥。","丈夫强健四方走，妇女龌龊将安归。","塌然四壁倚机杼，收拾遗粒吹糠粞。","东邻十日营一炊，西邻谁使救汝饥。","海边唯有盐不旱，卖盐连坐收婴儿。","传闻四方同此苦，不关东海诛孝妇。"]},{"t":"次韵子瞻系御史狱赋狱中榆槐竹柏 竹","f":"五言古诗","c":["故园今何有，犹有百竿竹。","春雷起新萌，不放牛羊触。","虽无朱栏拥，不见红尘辱。","清风时一过，交戛响鸣玉。","渊明避纷乱，归嗅东篱菊。","嗟我独何为，弃此北窗绿。"]},{"t":"次韵子瞻系御史狱赋狱中榆槐竹柏 柏","f":"五言古诗","c":["曲如山下藤，脆若溪上苇。","春风一张王，秋霜死则已。","胡为南涧中，辛勤种柏子。","上枝挠云霓，下根绞石齿。","伐之为梁栋，岁月良晚矣。","白首阅时人，君看柱下史。"]},{"t":"次韵子瞻系御史狱赋狱中榆槐竹柏 榆","f":"五言古诗","c":["秋风一何厉，吹尽山中绿。","可怜凌云条，化为樵夫束。","凛然造物意，岂复私一木。","置身有得地，不问直与曲。","青松未必贵，枯榆还自足。","纷然落叶下，萧条愧华屋。"]},{"t":"次韵子瞻系御史狱赋狱中榆槐竹柏 槐","f":"五言古诗","c":["盛衰日相寻，循环何曾歇。","攀条揽柔荑，回首惊脱叶。","绿槐阴最厚，零落今存荚。","千林一枯槁，平地三尺雪。","草木何足道，盈虚视新月。","微阳起泉下，生意未应绝。"]},{"t":"次韵子瞻和陶公止酒","f":"五言古诗","c":["少年无大过，临老重复止。","自言衰病根，恐在酒杯里。","今年各南迁，百事付诸子。","谁言瘴雾中，乃有相逢喜。","连床闻动息，一夜再三起。","溯流俯仰得，此病竟何理。","平生不尤人，未免亦求己。","非酒犹止之，其馀真止矣。","飘然从孔公，乘桴南海涘。","路逢安期生，一笑千万祀。"]},{"t":"江州五咏 其四 东湖","f":"五言律诗","c":["读书庐山中，作郡庐山下。","平湖浸山脚，云峰对虚榭。","红蕖纷欲落，白鸟时来下。","犹思隐居胜，乱石惊湍泻。"]},{"t":"次韵子瞻和渊明饮酒二十首 其二十","f":"五言古诗","c":["诸妄不可赖，所赖惟一真。","内欲求性命，油然反清淳。","外将应物化，致一常日新。","商于四父老，携手初逃秦。","翻然感汉德，投足复践尘。","出处盖有道，岂为诸吕勤。","嗟我千岁后，澹然与之亲。","还将山林姿，俯首要路津。","囊中旧时物，布衣白纶巾。","功成不归去，愧此同心人。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十九","f":"五言古诗","c":["我友二三子，兼有仕未仕。","青松出林秀，岂独私与己。","敛然不求人，而我自罍耻。","临风忽长鸣，谁信日千里。","江行视渔父，但自正纲纪。","持纲起万目，鲂鳟皆可止。","老成日就衰，所馀殆难恃。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十八","f":"五言古诗","c":["清秋九日近，菊酒皆可得。","永愧陶翁饥，虽饥心不惑。","怀忠受正命，赋命本通塞。","斯人今苟在，可与同事国。","惜哉委荆榛，忍饥长默默。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十七","f":"五言律诗","c":["南方有贫士，狂怪如病风。","垢面发如葆，自污屠酒中。","导我引河水，上与昆崙通。","长箭挽不尽，不中无尤弓。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十六","f":"五言古诗","c":["家居简馀事，犹读内景经。","浮尘扫欲尽，火枣行当成。","清晨委群动，永夜依寒更。","低帷閟重屋，微月流中庭。","依松白露上，历坎幽泉鸣。","功从猛士得，不取儿女情。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十五","f":"五言古诗","c":["去年旅都城，三月不求宅。","彼哉安知我，争扫习礼迹。","三已竟无怨，心伏鸷鸟百。","无私心如丹，经患发先白。","功名已不求，馀事复何惜。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十四","f":"五言古诗","c":["淮海老使君，受诏行当至。","当官不避事，无事辄径醉。","平生自相许，兄先弟亦次。","东南岂徒往，多难嫌暴贵。","白首六卿中，嚼蜡那复味。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十三","f":"五言古诗","c":["天厨酿冰池，摇振畏出境。","年衰杂羸病，一釂百不醒。","鸾台异诸曹，有政非簿领。","颓然虽无谪，因谢出囊颖。","回首愧周行，群英粲彪炳。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十二","f":"五言古诗","c":["春旱麦半死，夏雨欣及时。","出郊视禾田，父老有好辞。","秋阴结愁霖，似欲直败兹。","冥冥人天际，影响良不疑。","精诚发中禁，悯默非有欺。","鸡号日东出，乃令民信之。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十一","f":"五言古诗","c":["修己以安人，嗟古有此道。","平生妄谓得，忽忽恨衰老。","年来亦见用，何益世枯槁。","逡巡事朝谒，出入自媚好。","报君要得人，被褐信怀宝。","斯人何时见，即上归耕表。"]},{"t":"次韵子瞻和渊明饮酒二十首 其十","f":"五言古诗","c":["羌虏忘君恩，战鼓惊四隅。","边候失晨夜，骑驿驰中涂。","诏书止穷征，诸将守来驱。","敌微势可料，师竞力无馀。","防边未云失，忧怀愧安居。"]},{"t":"次韵子瞻和渊明饮酒二十首 其九","f":"五言古诗","c":["尺书千里至，辍食手自开。","将卜东南居，故乡非所怀。","勿言湖山美，永与平生乖。","鸿雁秋南来，及春思故栖。","蛟龙乘风云，既雨反其泥。","兄弟通四海，叩门事虽谐。","直道竟三黜，去国终恐迷。","何如自卫反，阙里从参回。"]},{"t":"次韵子瞻和渊明饮酒二十首 其八","f":"五言古诗","c":["明月出东墙，万物含馀姿。","孤蝉庇繁荫，众鸟栖高枝。","解衣适少事，扪腹知亡奇。","朝与群动作，莫复何所为。","此时不自有，日出还受羁。"]},{"t":"次韵子瞻和渊明饮酒二十首 其七","f":"五言古诗","c":["开卷观古人，谁非一世英。","骨肉委黄垆，泯灭俱无情。","憧憧来无尽，扰扰相夺倾。","惊雷震朱夏，鲜能及秋鸣。","得酒且酣饮，问谁逃死生。"]},{"t":"次韵子瞻和渊明饮酒二十首 其六","f":"五言律诗","c":["梦中见百怪，一一皆谓是。","醉中身已忘，万事随亦毁。","此心不应然，外物妄使尔。","安心十年后，此语知非绮。"]},{"t":"次韵子瞻和渊明饮酒二十首 其五","f":"五言古诗","c":["昔在建城市，盐酒昼夜喧。","夏潦恐天漏，冬雷知地偏。","妻孥日告我，胡不反故山。","一来朝廷上，七年不知还。","有寓均建城，且志昔日言。"]},{"t":"次韵子瞻和渊明饮酒二十首 其四","f":"五言古诗","c":["秋鸿一何乐，空际乘风飞。","秋虫一何忧，壁间终夜悲。","忧乐本何有，力尽两无依。","物生逐所遇，久行不知归。","少年气难回，老者百事衰。","聊复沃以酒，永与狂心违。"]},{"t":"次韵子瞻和渊明饮酒二十首 其三","f":"五言古诗","c":["世人岂知我，兄弟得我情。","少年喜文章，中年慕功名。","自从落江湖，一意事养生。","富贵非所求，宠辱未免惊。","平生不解饮，欲醉何由成。"]},{"t":"次韵子瞻和渊明饮酒二十首 其二","f":"五言律诗","c":["人言性本静，不必林与山。","世虽有此理，知谁非妄言。","自我作归计，于今十馀年。","低回轩冕中，此语愧虚传。"]},{"t":"次韵子瞻和渊明饮酒二十首 其一","f":"五言古诗","c":["我性本疏懒，父母强教之。","逡巡就科选，逮此年少时。","幽忧二十年，懒性祗如兹。","偶然践黄闼，俯仰空自疑。","乞身未敢言，常愧外物持。"]},{"t":"次韵子瞻临皋新葺南堂五绝 其一","f":"七言绝句","c":["江声六月撼长堤，雪岭千重过屋西。","一叶轩昂方断渡，南堂萧散梦寒溪。"]},{"t":"次韵子瞻将之吴兴赠孙莘老","f":"七言古诗","c":["宦游莫向长城窟，冬冰折胶弦亦绝。","吴中腊月百事便，蟹煮黄金鲈鲙雪。","京城旧友一分散，近忆吴兴须满颊。","世事反复如翻飞，今日共鲧前益垂。","畏人但恐去不远，适意未觉归来迟。","借问校雠天禄阁，何如江海同游嬉。"]},{"t":"次韵子瞻独觉","f":"七言古诗","c":["咄咄书空中有怪，内热搜膏发痈疥。","羹藜饭芋如固然，饱食安眠真一快。","午鸡鸣屋呼不起，欠伸吉贝重衾里。","此身南北付天工，竹杖芒鞋即行李。","夜长却对一灯明，上池溢流微有声。","幻中非幻人不见，本来日月无阴晴。"]},{"t":"次韵子瞻秋雪见寄二首 其一","f":"七言律诗","c":["秋气萧骚仍见雪，客愁缭绕动萦心。","幽吟北户窗声细，归梦函关马迹深。","疏树飞花轻蔌蔌，衰荷留柄乱簪簪。","遥闻诗酒皆推胜，社客何人近纳琛。"]},{"t":"次韵子瞻送千乘千能","f":"五言古诗","c":["少年食糠覈，吐去愿一官。","躬耕遇敛穫，不知以为欢。","谓言一飞翔，要胜终屈蟠。","朝廷未遑入，江海失所安。","多忧变华发，照影惭双鸾。","恩从万里归，独喜大节完。","日食太仓米，箧中有馀纨。","奇穷不当尔，自信处此难。","长女闻孀居，将食泪滴槃。","老妻饱忧患，悲吒摧心肝。","西飞问黄鹄，谁当救饥寒。","二子怜我老，辇致心一宽。","别久得会合，喜极成辛酸。","忽闻倚门望，有书惊岁阑。","深情见缓急，欲报非琅玕。","劝尔勤孝友，慎毋慕衣冠。","渊渟自成井，放泻当生澜。","岂有白雪驹，举足无和銮。"]},{"t":"次韵子瞻送杨杰主客奉诏同高丽僧游钱塘","f":"七言古诗","c":["人言长安远如日，三韩住处朝日赤。","飞帆走马入齐梁，却渡吴江食吴橘。","玉门万里唯言九，行人泪堕阳关酒。","佛法西来到此间，遍满曾如屈伸手。","出家王子身心虚，飘然渡海如过渠。","远来忽见倾盆雨，属国真逢戴角鱼。","至人无心亦无法，一物不见谁为敌。","东海东边定有无，拍手笑作中朝客。"]},{"t":"次韵子瞻送陈睦龙图出守潭州","f":"七言古诗","c":["海上石桥馀折栋，大舶记君过铁瓮。","东行万里若乘空，老蜃长鲸应入鞚。","波摇风卷卧不起，免教髀肉鞍磨痛。","归来过我话艰苦，惊汗津津尚流汞。","海涯风物画成图，错落天吴兼紫凤。","至今想象隔人世，往往风涛吹昼梦。","长沙欲往厌飞楫，幸有千兵作迎送。","文章清逸世少比，科第峥嵘声自重。","远行屡屈众所叹，出祖谁攀车欲动。","明朝鼓角背王城，莫听单于吹晓弄。"]},{"t":"次韵子瞻凌虚台","f":"五言古诗","c":["弃我谓我远，求我谓我还。","我一尔则二，视此台上山。","山高上干天，独不照我颜。","无乃我自蔽，谁谓山则悭。","远望不见趾，近视不得鬟。","山实未始变，任子自择删。","北风吹南崖，山上秋叶斑。","道远又寒苦，皴裂辞难攀。","晴空卷朝云，照夜霜月弯。","强尔登此台，免尔超阓阛。"]},{"t":"次韵子瞻特来高安相别先寄迟适远却寄迈迨过遁","f":"七言古诗","c":["老兄骑骡日百里，据鞍作诗若翻水。","忽吟春草思惠连，因之亦梦添丁子。","群儿竞长堪一笑，老马卧餐何日起。","闻兄尽室皆旧人，见面未曾惟遁耳。","迟年最长二十六，已能干父穷愁里。","豫儿扬眉稍刚劲，党子温纯无愠喜。","我兄憔悴我亦穷，门户久长真待尔。","但令戢戢见头角，甑倒囊空定何耻。","家藏万卷须尽读，此外一簪无所恃。","船中未用废诗书，闭窗莫看江山美。"]},{"t":"次韵子瞻留别三首 其一","f":"七言律诗","c":["公来十日坐东轩，手自披云出朝日。","山川满目竟何有，波浪翻天同一湿。","诸门迭出惊异状，间道怀归终旧壁。","此行千里隔江河，何人更问维摩疾。"]},{"t":"次韵子瞻病中大雪","f":"五言古诗","c":["吾兄笔锋雄，诗俊不可和。","雪中思清绝，韵恶愈难奈。","殷勤赋黄竹，自劝饮白堕。","言随飞花落，意与长风簸。","馀力远见撩，千里寄璀瑳。","嗟予学久废，有类转空磨。","研磨久无得，安可待充货。","空记乘峡船，行意被摧剉。","溟濛覆洲渚，泠冽光照坐。","我唱君实酬，驰骋不遑卧。","譬如逐兽卢，岂觉山径坷。","酒肴助喧热，笔砚尽沾涴。","诗词禁推类，令肃安敢破。","亦有同行人，牵挽赴程课。","尔来隔秦魏，渴望等饥饿。","徒然遇佳雪，有酒谁与贺。"]},{"t":"次韵子瞻病中赠提刑段绎","f":"五言古诗","c":["京东分东西，中划齐鲁半。","兄来本相从，路绝一长叹。","前朝使者还，手把新诗玩。","怜我久别离，卷帙为舒散。","谁言穷陋邦，得此唱酬伴。","相逢倾盖间，晤语何旦旦。","宦游少娱乐，缠缚苦文案。","能于王事馀，时作楚词乱。","譬如近膏油，未肯忘濯盥。","贤豪真勉强，功业畏缭缓。","伊余独何为，旧籍西南贯。","窃禄未遑归，自笑嗟已懦。","方当四海寒，恋此一寸炭。","主倦客欲留，逡巡要夺馆。","奈何独见收，软言强温暖。","此意定难酬，还予授子粲。"]},{"t":"次韵子瞻题郭熙平远二绝 其一","f":"七言绝句","c":["乱山无尽水无边，田舍渔家共一川。","行遍江南识天巧，临窗开卷两茫然。"]},{"t":"次韵子瞻减降诸县囚徒事毕登览","f":"五言古诗","c":["山川足清旷，阛阓巧拘囚。","安得孅阿御，同为穆满游。","遥知因涣汗，远出散幽忧。","原隰繁分绣，村墟尽小侯。","春深秦树绿，野阔渭河流。","四顾神萧瑟，前探意涨浮。","胜观殊未已，往足讵能收。","下坂如浮舸，登崖剧上楼。","强行腰伛偻，困坐气嘘咻。","鸟语林峦静，花明涧谷幽。","濯溪惊野老，伐路骇他州。","中散探深去，文渊到处留。","听琴峰下寺，弄石水中洲。","溪冷泉冰脚，山高雾绕头。","石潭清照骨，瀑水溅成钩。","仙庙鸣钟磬，神官秉钺刘。","养生闻帝女，服气绝彭雠。","故宅犹传尹，先师不喜丘。","居人那识道，过客谩停驺。","岩谷诚深绝，神仙信有不。","云居无几杖，霞佩弃镌锼。","豹隐连山雾，龙潜百尺湫。","门开谁与叩，桃熟浪传偷。","绀发清无比，方瞳凛不侔。","会须林下见，乞取寿年修。","拔去和鸡犬，相随若旆旒。","乘风遗騕袅，长啸贱笙篌。","从骑衣皆羽，前驱鬣尽虬。","安能牵两足，暂得快双眸。","自昔辞乡树，南行上楚舟。","万江穷地脉，三峡束天沟。","云暗酆都晚，波吹木枥秋。","寻溪缘窈窕，入洞听飕飗。","空寺收黄栗，荒祠画伏彪。","登临虽永日，行迈肯停辀。","蓄缩今何事，攀跻昔已悠。","魏京饶士女，春服聚蜉蝣。","雷动车争陌，花摇树系鞦。","游人纷荡漾，野鸟自嘤呦。","平日曾经洛，闲居愿卜缑。","空言真比梦，久渴渐成愁。","早退尝相约，辞嚣痛自搂。","爱山心劫劫，从宦兴油油。","海宇都无碍，山林尽可投。","愿为云上鹄，莫作盎中鯈。","适性行随足，谋生富给喉。","今游虽不与，后会岂无由。","昼出同穿履，宵眠共覆裘。","弟兄真欲尔，朋好定谁俦。","试写长篇调，何人肯见酬。"]},{"t":"次韵子瞻宿南山蟠龙寺","f":"七言古诗","c":["谷中夜行不见月，上下不辨山与谷。","前呼后应行相从，山头谁家有遗烛。","跫跫深径马蹄响，落落稀星著疏木。","行投野寺僧已眠，叩门无人狗出缩。","号呼从者久嗔骂，老僧下床揉两目。","问知官吏冒夜来，扫床延客卧华屋。","釜中无羹甑实尽，愧客满盎惟脱粟。","客来已远睡忘觉，僧起开堂劝晨粥。","自嗟奔走闵僧闲，偶然来过何年复。","留诗满壁待重游，但恐尘埃难再读。"]},{"t":"次韵子瞻寄贺生日","f":"五言古诗","c":["弟兄本三人，怀抱丧其一。","颀然仲与叔，耆老天所骘。","师心每独往，可否辄自必。","折足非所恨，所恨覆鼎实。","上赖吾君仁，议止海滨黜。","凄酸念母氏，此恨何时毕。","平生贤孟博，苟生不谓吉。","归心天若许，定卜老泉室。","凄凉百年后，事付何人笔。","于今兄独知，言之泣生日。"]},{"t":"次韵子瞻寄黄子木杖","f":"五言古诗","c":["老至亦有渐，五十惟杖始。","行年日辰匝，幸免乡闾耻。","罪重疮难平，馀痂未脱疻。","登山足犹健，不用扶儿子。","我兄念辛勤，赠此携且倚。","他年赐环日，田舍尤须此。","早收藤节杯，旋缀乌皮几。","茅檐数间足，不用伐桐杞。"]},{"t":"次韵子瞻望湖楼上五绝 其一","f":"七言绝句","c":["欲看西湖两岸山，卧乘湖上木兰船。","湖山已自随船改，更值阴晴欲雨天。"]},{"t":"次韵子瞻梳头","f":"七言律诗","c":["水上有车车自翻，悬霤如线垂前轩。","霜蓬已枯不再绿，有客劝我抽其根。","枯根一去紫茸茁，珍重已试幽人言。","纷纷华发何足道，当返六十过去魂。"]},{"t":"次韵子瞻游甘露寺","f":"五言古诗","c":["去国日已远，涉江岁将阑。","东南富山水，跬步留清欢。","迁延废行迈，忽忘身在官。","清晨涉甘露，乘高弃征鞍。","超然脱阛阓，穿云抚朱栏。","下视万物微，惟觉沧海宽。","潮来声汹汹，望极空漫漫。","一一渡海舶，冉冉移樯竿。","水怪时出没，群嬉类豭羱。","幽阴自生火，青荧复谁钻。","石头古天险，凭恃分权瞒。","疑城曜远目，来骑惊新观。","聚散定王业，成毁犹月团。","金山百围石，岌岌随涛澜。","犹疑汉宫廷，屹立承露盘。","狂波恣吞噬，万古嗟独完。","凝眸厌滉漾，绕屋行盘跚。","此寺历今古，遗迹皆龙鸾。","孔明所坐石，牂䍽非人刊。","经霜众草短，积雨青苔寒。","萧翁嗜佛法，大福将力干。","坡陀故镬在，甲错苍龙蟠。","卫公秉节制，佛骨埋金棺。","长松看百尺，画像留三叹。","新诗语何丽，传读纸遂刓。","嗟我本渔钓，江湖心所安。","方为笼中闭，仰羡天际抟。","游观惜不与，赋咏嗟独难。","俸禄藉升斗，齑盐嗜咸酸。","何时扁舟去，不俟官长弹。"]},{"t":"次韵子瞻游孤山访惠勤惠思","f":"词","c":["鸟依山，鱼依湖，但有所有无所无。","轻舟沿溯穷远近，肩舆上下更传呼。","翩然独往不携孥，兼擅鱼鸟两所娱。","困依岩石坐巉绝，行牵翠蔓随缠纡。","道逢勤思访其庐，诵诗清切秋蝉孤。","隐居羞踏陌上土，何人起爱轮下蒲。","水南巷中罗百夫，鸡鸣朝谒至日晡。","人生变化安可料，怜汝久遁终无图。","凫鹥不足鹤有馀，一俯一仰戚与蘧。","嗟我久欲从逃逋，方圆不敢左右摹。"]},{"t":"次韵子瞻游径山","f":"七言古诗","c":["去年渡江爱吴山，忽忘蜀道轻秦川。","钱塘后到山最胜，下枕湖水相萦旋。","坐疑吴会无复有，扁舟屡出凌涛渊。","今秋复入径山寺，势压众岭皆摧颠。","连峰沓嶂不知数，重重相抱如青莲。","散为云雾翳星斗，聚作潭井藏蜿蜒。","钦翁未到人迹绝，千里受记来安禅。","荒榛野草置茅屋，坐令海贾输金钱。","至今传法破烦恼，饱食过客容安眠。","解装投锡不复去，纷纷四合来乌鸢。","或言此处犹未好，海上人少无烦煎。","天台雁荡最深秀，水惊石瘦尤清便。","青山独往无不可，论说好丑徒纷然。","终当直去无远近，藤鞋竹杖聊穷年。"]},{"t":"次韵子瞻游罗浮山","f":"七言古诗","c":["客迷堕涧逢玉京，云行夭乔风号鸣。","暗中过尽石髓滑，惊喜观阙朝霞明。","东坡南去类此客，挤者力尽非求生。","偶然濒海少氛气，复有福地容躬耕。","诸侯历聘谢鲁叟，茅檐燕坐师老彭。","天枢旋结日珠重，人寰下视鸿毛轻。","俗缘渐觉冰雪解，元气乍复蛟虬狞。","远游脱屣入盖竹，初怪长史留家庭。","后来玉斧小儿子，亦入真诰参仙经。","试令子弟学诸许，还家不用剑阁铭。","洞天闻亦有图籍，但恐未免如公卿。","此心愿与世无事，不愿与世平不平。"]},{"t":"次韵子瞻游道场山何山","f":"七言古诗","c":["两山相负为峰麓，流水重重注溪谷。","游人上寻流水源，未觉崎岖病双足。","山深下视云漫漫，径垂石底千屈盘。","松林阴森白日静，忽惊人世如奔湍。","客行不避苦寒出，僧定端居不下席。","人生嗟与草木同，置身所在由初植。","堂中白佛青髻鬟，气象冲淡非人间。","坐令远客厌奔走，径欲筑室依空山。","木鱼桹桹夜将旦，星斗攲斜挂山半。","行役有程未可留，将出山门复长叹。"]},{"t":"次韵子瞻渼陂鱼","f":"七言古诗","c":["渼陂霜落鱼可掩，枯芡破盘蒲折剑。","巨斧敲冰已暗知，长叉刺浪那容闪。","鲸孙蛟子谁复惜，朱鬣金鳞漫如染。","邂逅相遭已失津，偶然一掉犹思堑。","嗟君游宦久羊炙，有似远行安野店。","得鱼未熟口流涎，岂有哀矜自欺僭。","人生饱足百事已，美味那令一朝欠。","少年勿笑贪匕箸，老病行看费针砭。","羊生悬骨空自饥，伯夷食菜有不赡。","清名惊世不益身，何异饮醯徒酷酽。"]},{"t":"次韵子瞻赋雪二首 其一","f":"七言律诗","c":["麦苗出土正纤纤，春早寒官令尚严。","云覆南山初半岭，风乾东海尽成盐。","来时瞬息平吞野，积久攲危欲败檐。","强付酒樽判醉熟，更寻诗句斗新尖。"]},{"t":"次韵子瞻道中见寄","f":"七言古诗","c":["兄诗有味剧隽永，和者仅同如画影。","短篇泉冽不容挹，长韵风吹忽千顷。","经年淮海定成集，走书道路未遑请。","相思半夜发清唱，醉墨平明照东省。","南来应带蜀冈泉，西信近得蒙山茗。","出郊一饭欢有馀，去岁此时初到颍。"]},{"t":"次韵子瞻颍州留别二首 其一","f":"五言古诗","c":["托身游宦乡，终老羡箕颍。","隐居亦何乐，亲爱形随影。","念兄适吴越，霜降水初冷。","翩然事舟楫，弃此室庐静。","平明知当发，中夜抱虚警。","永怀江上宅，归计失不猛。","人生徇所役，有若鱼堕井。","远行岂易还，剧饮终难醒。","不如早自乞，闲日庶犹永。","世事非所忧，多忧亦谁省。"]},{"t":"次韵子瞻颍州留别二首 其二","f":"五言古诗","c":["放舟清淮上，荡潏洗心胸。","所遇日转胜，恨我不得同。","江淮忽中断，陂埭何重重。","紫蟹三寸筐，白凫五尺童。","赤鲤寒在汕，红粳满霜风。","西成百物贱，加餐慰贫穷。","胡为复相念，未肯安南东。","人生免饥寒，不受外物攻。","不见田野人，四壁编茅蓬。","有食辄自乐，谁知富家翁。"]},{"t":"次韵子瞻感旧","f":"五言古诗","c":["还朝正三伏，一再趋未央。","久从江海游，苦此剑佩长。","梦中惊和璞，起坐怜老房。","为我忝丞辖，置身愿并凉。","此心一自许，何暇忧陟冈。","早岁发归念，老来未尝忘。","渊明不久仕，黔娄足为康。","家有二顷田，岁办十口粮。","教敕诸子弟，编排旧文章。","辛勤养松竹，迟莫多风霜。","常恐先著鞭，独引社酒尝。","火急报君恩，会合心则降。"]},{"t":"次韵子瞻感旧见寄","f":"五言古诗","c":["少年耽世味，徘徊不能去。","老来悟前非，尚愧昔游处。","君才最高峙，鹤行鸡群中。","我虽非君对，顾以兄弟同。","结发皆读书，明月入我牖。","纵横万馀卷，临纸但挥手。","学成竟无用，掩卷空自疑。","却寻故山友，重赴幽居期。","秋风送馀热，冉冉如人老。","衣裘当及时，田庐亦须早。","种竹竹生笋，种稻稻亦成。","浩歌归来曲，曲终有遗声。"]},{"t":"次韵子瞻谪居三适 旦起理发","f":"五言古诗","c":["道人鸡鸣起，趺坐存九宫。","灵液流下田，伏苓抱长松。","颠毛得馀润，冉冉欺霜风。","俯就无数栉，九九为一通。","洗沐废已久，徐之勿匆匆。","气来自涌泉，至此知几重。","近闻西边将，袒裼拥马鬃。","归来建赤油，不复侪伍同。","笑我守寻尺，求与真源逢。","人生各有安，未肯易三公。"]},{"t":"次韵子瞻谪居三适 午窗坐睡","f":"五言古诗","c":["定中龙眠膝，定起柳生肘。","心无出入异，三昧亦何有。","晴窗午阴转，坐睡一何久。","颓然拥褐身，剥啄叩门手。","褰帷顾我笑，疑我困宿酒。","不知吾丧我，冰消不遗寿。","空虚无一物，彼物自枯朽。","梦中得灵药，此药从谁受。","侵寻入四支，欲洗自无垢。","从今百不欠，只欠归田叟。"]},{"t":"次韵子瞻谪居三适 夜卧濯足","f":"五言古诗","c":["海民慢寒备，不畜衾与裯。","虽苦地气泄，亦无徒跣忧。","逐客久未安，集舍占鸺鹠。","念昔使胡中，车驰卒不留。","貂裘溯北风，十袭犹飕飕。","中涂履冰河，马倒身自投。","宛足费冯翼，千里烦帣韝。","十年事汤剂，风雨气辄浮。","南来足忧虑，此病何时瘳。","名身孰亲疏，慎勿求封侯。"]},{"t":"次韵子瞻端午日与迟适远三子出游","f":"五言古诗","c":["人生逾四十，朝日已过午。","一违少壮乐，日迫老病苦。","丹心变为灰，白发粲可数。","惟当理锄耰，教子蓺稷黍。","谁令触网罗，展转在荆楚。","平生手足亲，但作十日语。","朝游隔提携，夜卧困烝煮。","未歌《棠棣》诗，已治刍灵祖。","士生际风云，富贵若骑虎。","奈何贫贱中，所欲空龃龉。"]},{"t":"次韵子瞻题孙莘老墨妙亭","f":"七言古诗","c":["高岸为谷谷为陵，一时豪杰空飞腾。","身随造化不复返，忽若野雀逢苍鹰。","当年碑刻最深固，风吹土蚀消无棱。","遗文漫灭雨中迹，翠石断裂春后冰。","古坟欲毁野庙废，行人不去征鞍凭。","书生耽玩立风雪，饥驴厌苦疲奴憎。","爱之欲取恨无力，旋揉翠墨濡黄缯。","不如好事孙太守，牛车徙置华堂登。","绕墙罗列耀圭璧，罢宴起读留宾朋。","却思遗迹本安在，原隰处处荒榛藤。","田夫野老谁复顾，鬼火夜照来寒灯。","废兴聚散一如此，反使涕泗沾人膺。"]},{"t":"次韵子瞻题岐山周公庙","f":"七言律诗","c":["周人尚记有周公，禾黍离离下有宫。","破豆烝豚非以报，野巫长跪若为通。","山围栋宇泉流近，凤去梧桐落叶濛。","有客赋诗题屋壁，二南犹自有遗风。"]},{"t":"次韵子瞻题张公诗卷后","f":"五言古诗","c":["世俗甘枉尺，所愿求直寻。","不知一律讹，大乐无完音。","见利心自摇，虑害安得深。","至人不妄言，淡如朱丝琴。","悲伤感旧俗，不类骚人淫。","又非避世翁，闵嘿遽阳瘖。","嘐嘐晨鸡鸣，岂问晴与阴。","世人积寸木，坐使高楼岑。","晚岁卧草庐，谁听梁甫吟。","它年楚倚相，傥能记愔愔。"]},{"t":"次韵子瞻题薛周逸老亭","f":"五言古诗","c":["飞鸟不知穴，山鹿不知流。","薛子善饮酒，口如汲水虬。","吾观肠胃间，何异族党州。","人满地已尽，一介不可留。","谓子试饮水，一酌不再求。","谓子饮醇酒，百釂岂待酬。","酒可水不可，其说亦已悠。","以我视夫子，胸腹百丈幽。","譬如田中人，视彼公与侯。","未省破颜饮，何况裸露头。","鸱夷谓大瓠，皆饱安用浮。","多少苟自适，岂害为朋游。"]},{"t":"次韵子瞻赠梁交左藏","f":"七言古诗","c":["彭城欲往台无檄，初喜东西合为一。","将军走马随春风，精锐千人森尺籍。","口占佳句惊众坐，手练强兵试鸣镝。","酒酣起舞花满地，醉倒不听人扶出。","归来相对如梦寐，虎踞熊经苦岑寂。","黄楼方就可同游，饮尽官厨三百石。"]},{"t":"次韵分司南京李诚之待制求酒二首 其二","f":"七言绝句","c":["春深风雨半相和，节物令人意绪多。","中酒何须问贤圣，和诗今尚许羊何。"]},{"t":"次韵孔平仲著作见寄四首 其四","f":"五言古诗","c":["治生非所长，儿女惊满屋。","作官又迂疏，不望载朱毂。","因缘挂罪罟，未许即潜伏。","空馀读书病，日与古人逐。","老妻怜眼昏，入夜屏灯烛。","上官念贫寠，时节馈醪肉。","衰年类蒲柳，世事剧麻粟。","数日望归田，寄语先栽竹。","文章亦细事，勤苦定何足。","君诗四相攻，欲看守陴哭。","愧无即墨巧，不解火牛触。","自非太学生，彫琢事干禄。","安心已近道，闭口岂非福。","胡为调狂词，玉石相落碌。","腹中抱丹砂，舌下漱白玉。","作诗虽云好，未免乱心目。","奕秋教二人，不取志鸿鹄。","摩诘非不言，遗韵寄终曲。"]},{"t":"次韵孔平仲著作见寄四首 其一","f":"五言古诗","c":["昔在京城南，成均对茅屋。","清晨屣履过，不顾车击毂。","时有江南生，能使多士服。","同侪畏锋锐，兄弟更驰逐。","文成剧翻水，赋罢有馀烛。","连收颔底髭，未耗髀中肉。","飞腾困中路，黾勉啄场粟。","归来九江上，家有十亩竹。","一官粗包裹，万卷中自足。","还如白司马，日听杜鹃哭。","我来万里外，命与江波触。","罪重惭故人，囊空仰微禄。","已为达士笑，尚谓愚者福。","米盐日草草，奔走常碌碌。","尺书慰贫病，佳句烂圭玉。","多难畏人知，胡为强题目。","徂年慕桑梓，归念寄鸿鹄。","但愿洗馀愆，躬耕江一曲。"]},{"t":"次韵孔平仲著作见寄四首 其三","f":"五言古诗","c":["百病侵形骸，渐老同破屋。","中有一寸空，能用辐与毂。","忽如丹砂走，不受凡火伏。","前瞻已不远，后蹑愈难逐。","将炊甑中饭，未悟窗下烛。","聪明役声形，口腹嗜鱼肉。","尘泥翳泉井，荆棘败禾粟。","未知按妙指，漫欲理丝竹。","庐山多名缁，过客礼白足。","达观等存亡，世俗强歌哭。","确然金石心，不畏蚊蚋触。","顺忍为裳衣，供施谢荣禄。","真人我自有，渡海笑徐福。","众皆指庸庸，自顾非碌碌。","愧君诗意厚，桃李报琼玉。","举网罗众禽，有获非一目。","喧啾定无用，要自取黄鹄。","君看大方家，慎勿留一曲。"]},{"t":"次韵孔平仲著作见寄四首 其二","f":"五言古诗","c":["共居天地间，大类一间屋。","推排出高下，何异车转毂。","死生本昼夜，祸福固倚伏。","谁令尘垢昏，浪与纷华逐。","譬如薪中火，外照不自烛。","感君探至道，劝我减粱肉。","虚心有遗味，实腹不须粟。","芬敷谢桃杏，清劲比松竹。","息微知气定，睡少验神足。","胡为嗜一饱，坐使百神哭。","要知丹砂异，不受腥腐触。","可怜山林姿，自缚斗升禄。","君看出世士，肯屑世间福。","宁从市井游，与众同碌碌。","不愿束冠裳，腰金佩鸣玉。","斯人今何在，未易识凡目。","恐在庐山中，飞翔逐黄鹄。","试用物色寻，应歌紫芝曲。"]},{"t":"次韵孔武仲三舍人省上","f":"词","c":["君不见西都校书宗室叟，东鲁高谈鼓瑟手。","偶然同我西掖垣，并立晓班分左右。","龙文百斛世无价，瓦釜枵然但升斗。","诸兄落落不可望，两季幸肯分馀光。","大孔奋飞自南乡，联翩群雁相追翔，渠家冠盖尤堂堂。"]},{"t":"次韵孔武仲学士见赠","f":"五言古诗","c":["羡君耽读书，日夜论今古。","虽复在家人，不见释手处。","意求五车尽，未惜双目苦。","蓬莱倚霄汉，简册充栋宇。","学成擅囷仓，笔落走风雨。","破笼闭野鹤，短草藏文虎。","鬓须忽半白，儿女无复乳。","知君不能荐，愧我终何补。","偶来相就谈，日落久未去。","归鞍得新诗，佳句烂如组。","古风弃雕琢，遗味比乐府。","且复调埙篪，泠然五音举。"]},{"t":"次韵文氏外孙骥以其祖父与可学士书卷还谢悰学士","f":"七言古诗","c":["西南自是贤俊府，衰老思归谩留许。","舂禾磨麦非平生，子孙便推我作古。","贤哉与可诗中杰，笔墨馀功散缯楮。","南阳诸谢世有人，此邦亦自非其土。","一时与我俱作客，白发苍颜愧非伍。","儒术真传汉太翁，风流未减晋诸庾。","两家尚有往还帖，旧集脱遗应可补。","明窗展卷清泪滴，恍然似与故人语。","欲锁空厨付长康，恐君讥我不与取。"]},{"t":"次韵文务光秀才游南湖","f":"七言律诗","c":["料峭东风助腊寒，汀滢白酒借衰颜。","满床书卷何曾读，数步湖光自不闲。","梦想绿杨垂后浦，眼看红杏照前山。","新春渐好君归速，不见游人暮不还。"]},{"t":"次韵毛君山房即事十首 其一","f":"七言绝句","c":["案牍稀疏意自开，夜阑幽梦晓方回。","青苔红叶骚人事，时见诗筒去又来。"]},{"t":"次韵毛君山房即事十首 其十","f":"七言绝句","c":["触事随缘不用多，华堂玉食奈忧何。","美人未厌山阿陋，薜荔为裳带女萝。"]},{"t":"次韵毛君绝句","f":"七言绝句","c":["中池有士闭重关，夜发天光走玉环。","白日对人人不识，幅巾破褐任尘漫。"]},{"t":"次韵毛君烧松花六绝 其一","f":"七言绝句","c":["茅庵纸帐学僧眠，炉爇松花取易然。","唯有未能忘酒在，手倾金盏斗垂莲。"]},{"t":"次韵毛国镇赵景仁唱和三首一赠毛一赠赵一自咏 其一","f":"七言律诗","c":["治剧从容缓策衔，铃轩无事日清谈。","隼旟画戟明千里，纸帐绳床自一庵。","金奏屡陈容客和，玉山不动看宾酣。","我来邂逅逢宽政，忘却漂流身在南。"]},{"t":"次韵王巩上元见寄三首 其一","f":"七言律诗","c":["弃掷良宵君谓何，清天流月鉴初磨。","莫辞病眼羞红烛，且试春衫剪薄罗。","莲艳参差明绣户，舞腰轻瘦飐惊鼍。","少年微服天街阔，何处相逢解佩珂。"]},{"t":"次韵王巩元日","f":"七言律诗","c":["庭鹊营巢初一枝，馀寒未便夹罗衣。","春风娜娜还吹霰，岁事骎骎已发机。","上国遨游谁信老，中年情味祇思归。","和诗应觉添新懒，过尽长空雁北飞。"]},{"t":"次韵王巩见赠","f":"五言古诗","c":["南都逢故人，共此一樽渌。","初来柳吹絮，再见风脱木。","我老欢意微，头垂腰背曲。","羡子方少年，健马走平陆。","狂歌手自拊，醉倒头相触。","人生比一瞬，世网张万目。","但取食场鸡，岂挂云飞鹄。","彭城久相迟，官舍虚东屋。","重阳试新酿，谓子当不速。","胡为听妇言，婉娈自相逐。","我舟得愁霖，牵挽脱坑谷。","风霜作初寒，病体欲生粟。","解子腰下龟，换酒不须赎。","照碧凝清光，相将饮萸菊。"]},{"t":"次韵王廷老寄子瞻","f":"七言律诗","c":["歌吹新成百尺台，青山临水巧崔嵬。","佳人解作回文语，狂客能鸣掺鼓雷。","撷菊传杯醒复醉，采菱荡桨去仍回。","新年闻欲相从饮，春酒还须剩作醅。"]},{"t":"次韵王适一百五日太平寺看花二绝 其一","f":"七言绝句","c":["遍入僧房花照眼，细寻芳径蝶随行。","归时不怕江波晚，新有桥虹水上横。"]},{"t":"次韵王适大水","f":"七言古诗","c":["高安昔到岁方闰，大水初去城如墟。","危谯堕地瓦破裂，长桥断缆船逃逋。","漂浮隙穴乱群蚁，奔走沙砾摧嘉蔬。","里闾破散兵火后，饮食敝陋鱼虾馀。","投荒岂复有便地，遇灾祗复伤羸躯。","人言西有蛟蜃穴，闰年每与风雷俱。","漫沟溢壑恣游荡，倾崖拔木曾须臾。","鸡豚浪走不复保，老稚裸泣空长吁。","滞留再与兹水会，沦胥未哂斯民愚。","人生所遇偶然耳，得失何用分锱铢。"]},{"t":"次韵王适元日并示曹焕二首 其一","f":"七言律诗","c":["井底屠酥浸旧方，床头冬酿压琼浆。","旧来喜与门前客，终日同为酒后狂。","老大心情今已尽，尘埃鬓发亦无光。","江南留滞归何日，万里逢春思故乡。"]},{"t":"次韵王适东轩即事三首 其一","f":"七言律诗","c":["新竹依墙未出寻，墙东桃李却成林。","池塘草长初饶梦，村落莺啼恰称心。","江满船头朝欲转，泥融屐齿莫尤深。","闭门怜子成书癖，试买村醪相伴斟。"]},{"t":"次韵王适兄弟送文务光还陈","f":"七言古诗","c":["三君皆亲非复客，执手河梁我心恻。","倚门耿耿夜不眠，挽袖匆匆有难色。","君归使我劳魂梦，落叶鸣阶自相拥。","君家西归在新岁，此行未远心先恐。","故山万里知何许，我欲因君亦归去。","清江彷佛钓鱼船，修竹平生读书处。","青衫白发我当归，咀噍式微惭古诗。","少年勿作老人调，被服荣名慰所思。"]},{"t":"次韵王适细鱼","f":"五言古诗","c":["群鱼一何微，仅比毛发大。","嬉游极草草，鬓鬣自个个。","造物赋群形，偶然如一唾。","吞舟虽云巨，其乐不相过。","若言无性灵，还知避船柂。"]},{"t":"次韵王适雪晴复雪二首 其一","f":"五言古诗","c":["骄阳得一雪，逾尺应更好。","晨兴视窗隙，惊见晴霞杲。","九衢无停迹，狼籍须一扫。","空馀浩然气，凛凛接清昊。","馀寒薄虚室，一静解群燥。","晨炊晚未供，客馈惭草草。","试脱身上衣，行问酒家保。","孤吟击槁木，大笑称有道。","人生但如此，富贵何用祷。","所思独未见，耿耿属怀抱。"]},{"t":"次韵王适雪晴复雪二首 其二","f":"五言古诗","c":["同云自成幄，飞雪来无根。","一为清风卷，坐见东方暾。","重阴偶复合，飞霰满南轩。","油然青春意，已见出土萱。","老病一不堪，惟恃浊酒温。","开户理松菊，扫荡无遗痕。","卷舒朝夕间，谁识造化元。","乾坤本何施，中有神怪奔。","万物极毫末，颠倒何足掀。","老农但知种，荷锄理南园。"]},{"t":"次韵王适游真如寺","f":"五言古诗","c":["江上春雨过，城中春草深。","扰扰市井尘，悠悠溪谷心。","东郊大愚山，自古薝卜林。","微言久不闻，坠绪谁当寻。","道俗数百人，请闻海潮音。","斋罢车马散，万籁俱消沉。","新亭面南山，积雾开重阴。","萧然偶有得，怀抱方愔愔。","我坐米盐间，日被尘垢侵。","不知山中趣，强作山中吟。"]},{"t":"次韵王适落日江上二首 其一","f":"五言律诗","c":["寒烟羃清江，渔唱扁舟上。","江转少人家，自此知安往。","维舟倚丛薄，明月独相向。","欲晓醉应醒，还逐轻鸥扬。"]},{"t":"次韵王适落日江上二首 其二","f":"五言律诗","c":["稍息南市喧，初上东山月。","潜鱼忽惊踊，饥雁时断绝。","落叶误投签，繁霜疑积雪。","苦寒良难久，爱此元气洁。"]},{"t":"次韵王适新燕","f":"七言律诗","c":["好雨纤纤润客衣，新来双燕力犹微。","似嫌春早无人见，故待帘开掠地飞。","南国花期知不远，中原寒剧未应归。","养雏不怕巢成早，记取朝朝为启扉。"]},{"t":"次韵石芝","f":"七言古诗","c":["鸡鸣东海朝日新，光蒙洲岛雾雨匀。","一晞石上遍生耳，幽子自食无来宾。","寄书乞取久未许，箬笼蕉囊海神户。","一掬谁令堕我前，无为知我超诸数。","此身不愿清庙瑚，但愿归去随樵苏。","龟龙百岁岂知道，养气千息存其胡。","尘中学仙定难脱，梦里食芝空酷烈。","中山军府得安闲，更试朝霞磨镜铁。"]},{"t":"次韵刘贡父和韩康公忆其弟持国二首 其一","f":"七言律诗","c":["霜风瑟瑟卷梧蕉，燕处超然夜寂寥。","羽客信来丹鼎具，石淙梦断水声遥。","赤松作伴谁当见，黄鹄高飞未易招。","剑履终身定何益，勤劳付与沛中萧。"]},{"t":"次韵刘贡甫学士画松石图歌","f":"七言古诗","c":["长松大石生长见，朅游尘土嗟空羡。","寒翠关心失旧交，荣华过眼惊流电。","破缯买得古画图，遗墨参差随断线。","蟉枝倒挂风自舞，直干孤生看面面。","故山旧物远莫致，爱此随人共流转。","物生真伪竟何有，适意一时宁复辨。","少年所好老成癖，傍人指笑嗟矜衒。","京城宅舍松石希，买费百金犹恐贱。"]},{"t":"次韵刘泾见寄","f":"七言古诗","c":["天之苍苍亦何有，亦有云汉为之章。","人生混沌一气耳，嘿嘿何用知肺肠。","孔公孟子巧言语，剖瓢插竹吹笙簧。","含宫吐角千万变，坐令隐伏皆形相。","我生禀赋本微薄，氤氲方寸不自藏。","譬如兰根在黄土，春风驱迫生繁香。","口占手写岂得已，此亦未免物所将。","方将寂寞自收敛，不受世俗斗尺量。","既知仍作未能止，纷纭竟亦类彼庄。","煎烹心脾擢胃肾，自令鬓发惊秋霜。","嗟子独未知此病，从横自恃觜爪刚。","少年一见非俗物，锵然修竹鸣孤凰。","近来直欲扛九鼎，令我畏见笔力强。","提携童子从冠者，揣摩五帝论三皇。","诗书近日贵新说，扫除旧学漫无光。","窃攘瞿昙剽李耳，牵挽性命推阴阳。","狂流滚滚去不返，长夜漫漫未遽央。","词锋俊发鲁连子，惭愧田巴称老苍。","是非得失子自了，一醉早醒余所望。"]},{"t":"次韵江法曹山间小酌","f":"七言律诗","c":["高情不奈簿书围，行揖青山肯见随。","绿野逢花将尽日，清樽迨我正闲时。","檐间双燕欲生子，叶底新梅初满枝。","笑杀华阳穷县令，床头酒尽只嚬眉。"]},{"t":"次韵邦直见答二首 其一","f":"七言律诗","c":["真能一醉逃烦暑，定胜三杯禦腊寒。","自有诗书供永日，莫将丝竹乱风滩。","舞雩何处归春莫，叩角谁人怨夜漫。","闻道丹砂近有术，锱铢称火共君看。"]},{"t":"次韵张刍谏议宴集","f":"七言古诗","c":["淮阳卧阁生清风，梁园坐啸囹圄空。","不知何术解髋髀，但觉羁客忘樊笼。","樽罍洒落谈笑地，尘埃脱去文书丛。","清心渐欲无一事，少年空记挥千钟。","近传移镇股肱郡，复恐入觐明光宫。","人生聚散不可料，一杯相属时方冬。","浮阳似欲作飞霰，想见观阙琼花中。","孝王会集犹可继，莫嫌作赋无枚翁。"]},{"t":"次韵张耒见寄","f":"七言古诗","c":["相逢十年惊我老，双鬓萧萧似秋草。","壶浆未洗两脚泥，南辕已向淮阳道。","我家初无负郭田，茅庐半破蜀江边。","生计长随五斗米，飘摇不定风中烟。","茹蔬饭糗不愿馀，茫茫海内无安居。","此身长似伏辕马，何日还为纵壑鱼。","怜君与我同一手，微官肮脏羞牛后。","请看插版趋府门，何似曲肱眠瓮牖。","中流千金买一壶，椟中美玉不须沽。","洛阳榷酒味如水，百钱一角空满盂。","县前女几翠欲滴，吏稀人少无晨集。","到官惟有懒相宜，卧看南山春雨湿。"]},{"t":"次韵张耒学士病中二首 其一","f":"七言律诗","c":["一卧怜君三十朝，呼医仍苦禁城遥。","灵根自逐新阳发，病蘖从经野火烧。","吻燥未须寻曲糵，囊空谁与典絺蕉。","何时匹马随街鼓，睡起频惊髀肉消。"]},{"t":"次韵李公择以惠泉答章子厚新茶二首 其一","f":"七言律诗","c":["无锡铜瓶手自持，新芽顾渚近相思。","故人赠答无千里，好事安排巧一时。","蟹眼煎成声未老，兔毛倾看色尤宜。","枪旗携到齐西境，更试城南金线奇。"]},{"t":"次韵李公朝著作见赠二首 其一","f":"五言律诗","c":["远客徒为尔，江边有故丘。","汀洲信广大，凫雁任漂浮。","好事时携酒，归心久倦游。","还乡定衰老，朋友肯相收。"]},{"t":"次韵侄过江涨","f":"五言古诗","c":["阴淫夏为秋，雨暴溪作渎。","缺防旧通市，流潦几入屋。","虽幸廪粟空，犹惜畦蔬绿。","鹿骇不择音，鸿羁分遵陆。","室诮曾子还，城讴华元衄。","中情久岑寂，外物竞排蹙。","设心等一慈，开怀受诸毒。","道力虽未究，游波偶然伏。","粮须三月聚，艾要七年蓄。","君恩许北还，从此当退缩。"]},{"t":"次韵和人丰岁","f":"七言律诗","c":["风雨迎寒欲劳农，今年真不负元丰。","盖藏共荷官无扰，眠食安知帝有功。","草笠黄冠将蜡祀，羔羊朋酒亦豳风。","请君早具跻堂饮，退食委蛇正自公。"]},{"t":"次韵和人咏酴醾","f":"七言古诗","c":["蜀中酴醾生如积，开落春风山寂寂。","已怜正发香晻暧，犹爱未开光的皪。","半垂野水弱如坠，直上长松勇无敌。","风中娜娜应数丈，月下煌煌真一色。","故园闻道开愈繁，老人自恨归无日。","百花已过春欲莫，燕坐绳床空数息。","朝来满把得幽香，案头乱插铜瓶湿。","一番花蕊转头空，谁能往问天台拾。"]},{"t":"次韵范郎中仰之咏雪","f":"五言古诗","c":["仓廪未应空，长天霰雪濛。","琼瑶布地净，组练出师雄。","云阔诸峰遍，花繁百草同。","农谣麦垄外，客兴酒杯中。","聚散占风力，消融验药功。","远游聊自喜，三见岁时丰。"]},{"t":"次韵转运使鲜于侁新堂月夜","f":"五言古诗","c":["长爱陶先生，闲居弃官后。","床上卧看书，门前自栽柳。","低徊顾微禄，毕竟谁挽袖。","索莫秋后蜂，青荧晓天宿。","惟将不系舟，托此春江溜。","尺书慰穷独，秀句惊枯朽。","遥知新堂夜，明月入杯酒。","千里共清光，照我茅檐漏。"]},{"t":"次韵侯宣城叠嶂楼双溪阁长篇","f":"五言古诗","c":["作官如负担，一负当且弛。","不知息肩处，妄问道远迩。","我乘章江流，却入宛溪水。","舍舟陟崔嵬，行路极句已。","名都便欲过，佳处赖公指。","仰攀叠嶂高，俯阅双溪美。","不悟身乘空，但觉风吹耳。","云烟变遥壑，歌吹闻近市。","倦游得清旷，行役有新喜。","公言顷榛秽，斩伐从我始。","堰水种蒲莲，开山莳梅李。","拥本待成阴，养花要食子。","遗风揖桓谢，父老邀黄绮。","邦人鱼依蒲，食客莪在芷。","春阴迫寒食，谓我姑且止。","嗟余去乡国，屡把刀环视。","感公鹄鹭修，怜我凫鸭庳。","异邦逢故人，宁复固辞理。","高谈云汉上，烂醉笙歌里。","落日尽公欢，推挽未应起。"]},{"t":"次韵南湖清饮二首 其一","f":"七言律诗","c":["翠箔红窗映大堤，远来清饮叹参差。","盈盈积水东西隔，脉脉幽怀彼此知。","渌酒谩传工破闷，主人何敢怪颦眉。","明朝看月云开未，试与詹家一问龟。"]},{"t":"次韵姚道人二首 其二","f":"五言古诗","c":["高人隐陋巷，至药初无方。","心知无生妙，运转开阴阳。","才如淩云松，岂受尺寸量。","气如幽谷兰，时送清风香。","嗟我本病肺，寒暑随翕张。","丹砂苦落落，青春去堂堂。","清诗堕云雾，至音叩琳琅。","山海信多士，世俗非所望。","远游居临安，间出从诸王。","他年解冠佩，共游无边疆。","仪麟既委照，永谢过隙光。"]},{"t":"次韵姚道人二首 其一","f":"五言古诗","c":["西山学采薇，东坡学煮羹。","昔在建城市，岂复衣冠情。","朋友日已疏，止接盲赵生。","啬智徇所安，元气赖以存。","时于星寂中，稍护乱与昏。","河流发九地，欲挽升天门。","枉用十年力，仅馀一灯温。","老病竟未除，惊呼欲狂奔。","何日新雨馀，得就季主论。"]},{"t":"次韵柳子玉谪官寿春舟过宛丘见寄二首 其一","f":"七言律诗","c":["局冷曾非簿领迷，幽居浑似未官时。","忽闻客至惊还喜，出见泥深笑不知。","谋拙未能忧岁计，身闲聊可饱晨炊。","行舟借问何匆草，淮口无潮月正亏。"]},{"t":"次韵秦观见寄","f":"五言古诗","c":["东家有贤人，西家苦相忽。","幽兰委冰霜，掩霭特未发。","春风限芳蕤，烂漫安可没。","东南信多士，人物世不阙。","考槃溪山间，自献耻干谒。","谁怜幽閒女，艳色比南越。","垂耳困盐车，捐金空买骨。","读书谢世事，闭门动论月。","予生亦羁旅，处世常卒卒。","谁令钓竿手，强复此持笏。","惟馀七尺躯，空洞中无物。","时蒙好事过，解榻聊一拂。","野情乐江海，梦想扁舟兀。","隐居便醉睡，世路多颠蹶。","荣华一朝事，毁誉百年歇。","相劝沐咸池，阳阿晞汝发。"]},{"t":"次韵秦观秀才携李公择书相访","f":"七言古诗","c":["济南三岁吾何求，史君后到消人忧。","君言有客轻公侯，扁舟相从古扬州。","致之匹马恨无力，千里相望同异域。","诵诗空使四座惊，隐居未易凡人测。","史君南归无限情，鸿飞携书堕我庭。","此书兼置昔年客，袖中秀句淮山青。","老夫强颜依府县，堆案文书本非愿。","清谈亹亹解人颐，安得坐右长相见。","狂客吾非贺季真，醉吟君似谪仙人。","末契长遭少年笑，白发应惭倾盖新。","都城酒贵谁当换，尘埃污面非良算。","归来泗上苦思君，莫待黄花秋烂漫。"]},{"t":"次韵秦观梅花","f":"七言古诗","c":["病夫毛骨日凋槁，愁见米盐惟醉倒。","忽传骚客赋寒梅，感物伤春同懊恼。","江边不识朔风劲，墙头亦有南枝早。","未开素质夜先明，半落清香春更好。","邻家小妇学闲媚，靓妆惟有长眉扫。","孤芳已与飞霰竞，结子仍先百花老。","苦遭横笛乱飞英，不见游人醉芳草。","可怜物性空自知，羞作繁华助芒昊。"]},{"t":"次韵钱协待制秋怀","f":"五言古诗","c":["壮心老自消，秋思悲不怨。","中怀不堪七，那用日食万。","朝阳净涂潦，白露沾草蔓。","夹衣搜故褚，酒债积新券。","狙猿便林薮，冠带愁槛圈。","梦追赤松游，食我青精饭。","归心久已尔，佳句聊复劝。","近闻洮东将，间出边马健。","裨王坐受缚，右袂行将献。","念此愧无功，归欤适吾愿。"]},{"t":"次韵顿起考试徐沂举人见寄二首 其一","f":"七言律诗","c":["齐楚诸生俨鞸绅，人人愿得出君门。","衔枚勇锐惊初合，弃甲须臾讶许奔。","细读未辞灯损目，久留终厌棘为藩。","定应亲刈翘中楚，把卷喧呼半夜言。"]},{"t":"次韵宿州教授刘泾见赠","f":"七言律诗","c":["此身虽复类潜夫，衰老无心强著书。","道路不知奔走贱，交游空怪往还疏。","弦歌更就三年学，簿领唯添一味愚。","它日相逢定何处，莫将文采笑空疏。"]},{"t":"次韵景仁丙辰除夜","f":"五言律诗","c":["数举除夜酒，稍消少年豪。","浮光寄流水，妙理付浊醪。","微阳未出土，大雪飞鹅毛。","试问冰霜劲，春来能久牢。"]},{"t":"次韵景仁正月十二日访吴缜寺丞二绝 其一","f":"七言绝句","c":["夜雪满庭鸡失晨，琼田早出不惊尘。","急须卷冻铺黄道，欲看灯山万万人。"]},{"t":"次韵答王巩","f":"五言古诗","c":["君家当盛时，画戟拥朱户。","中书十八年，清明日方午。","形容画云阁，功业载盟府。","中庭三槐在，遗迹百世睹。","子孙尽豪俊，岂类世寒寠。","胡为久邅厄，黾俛受侵侮。","往来两都间，奔走未安土。","愿言解缨绂，归去事农圃。","嘉禾根未拔，且忍俟甘雨。","拂衣走东皋，此语吾不取。","聊复放襟怀，清谈对僧麈。","躬耕未可言，知田顾乃父。"]},{"t":"次韵答张耒","f":"词","c":["客舟逝将西，日夜西北风。","维舟罢行役，坐令鬓如蓬。","偶从二三子，步上百尺台。","云烟遍原隰，?恍令人哀。","山中难久居，浮沉在城郭。","欲学扬子云，避世天禄阁。","浮木寄流水，行止非所期。","何须自为计，水当为我移。","外物不可必，惟此方寸心。","心中有乐事，手付瑟与琴。","夜吟感秋诗，惜此芳物零。","幽人亦多思，起坐再三听。","白驹在空林，瓶罄有耻罍。","尽我一杯酒，愁思如云颓。"]},{"t":"次韵答陈之方秘丞","f":"五言古诗","c":["南山李将军，疋马独行猎。","田中射虎豹，后骑不容蹑。","丈夫贵自遂，老大饶惊慑。","飘摇天地间，自视如一叶。","故人多东南，愿作扁舟涉。","忽蒙长篇赠，幸此倾盖接。","时世尚新奇，诗书存旧业。","南风吹清汴，西去无停楫。","恨不留君谈，一使众坐厌。","新诗苦清壮，欲和再三怯。","东都多名卿，投刺日盈笈。","一言苟合意，富贵出旬浃。","行看文石阶，高谈曳长衱。","辱赠但茫然，知君念疲薾。"]},{"t":"次韵蒋夔寒夜见过","f":"七言古诗","c":["都城广大漫如天，旅人骚屑谁与欢。","北风号怒屋无瓦，夜气凝冽冰生槃。","雪声旋下白玉片，灯花暗结丹砂丸。","叩门剥啄惊客至，吹火仓卒怜君寒。","明时未省有遗弃，高论自笑终汗漫。","识君太学嗟岁久，至今客舍犹泥蟠。","正如憔悴入笼鹤，坐见摧落凌风翰。","明朝尚肯过吾饮，有酒不尽行将酸。"]},{"t":"次韵鲜于子骏游九曲池","f":"五言律诗","c":["天高山近海，春尽草生池。","禾黍多新恨，川原自昔时。","花存故苑丽，樵出旧城隳。","莫望瓜洲渡，曾经驻佛狸。"]},{"t":"汝南迁居","f":"五言古诗","c":["病暑暑已退，思归未成归。","人事不可期，当受不当违。","客居汝南城，未觉吾庐非。","忽闻鹊反巢，坐使鸠惊飞。","三绕择所安，一枝粗得依。","我来众草生，渐见百卉腓。","天行若循环，物化如发机。","闭目内自观，此理良密微。"]},{"t":"江上早起","f":"五言古诗","c":["晨兴孤舟上，盥濯夜气清。","整巾未皇坐，双橹轧已鸣。","日出江雾散，江上山从横。","区区茅舍翁，晓出露气腥。","收筒得大鲤，爱惜不忍烹。","持之易斗粟，朝饭厌鱼羹。","萧萧远风起，泛泛野雁惊。","忽过百馀里，山水互变更。","逢舟问所如，彼此不知名。","超超江湖间，殊胜地上行。","旦游市井喧，莫宿无人声。","江上诚足乐，无怪陶朱生。"]},{"t":"江上看山","f":"七言律诗","c":["朝看江上枯崖山，憔悴荒榛赤如赭。","莫行百里一回头，落日孤云霭新画。","前山更远色更深，谁知可爱信如今。","唯有巫山最秾秀，依然不负远来心。"]},{"t":"江州五咏 其二 浪井","f":"五言律诗","c":["江波浮阵云，岸壁立青铁。","胡为井中泉，涌浪时惊发。","水性本无定，得止自澄澈。","谁为女娲手，补此天地裂。"]},{"t":"江州五咏 其五 琵琶亭","f":"五言律诗","c":["湓江莫雨晴，孤舟暝将发。","夜闻胡琴语，展转不成别。","草堂寄东林，雅意存北阙。","潸然涕泗下，安用无生说。"]},{"t":"江州周寺丞泳夷亭","f":"七言古诗","c":["行过庐山不得上，湓江城边一惆怅。","羡君山下有夷亭，千岩万壑长相向。","山中李生好读书，出山作郡山前居。","手开平湖浸山脚，未肯即与庐山疏。","道州一去应嫌远，千里思山梦中见。","青山长见恐君嫌，要须罢郡归来看。"]},{"t":"江涨","f":"五言古诗","c":["山中三日雨，江水一丈高。","崩腾没洲渚，淫溢浸蓬蒿。","凌晨我有适，出门舟自操。","中廛已易肆，下道先容舠。","鸡犬萃坟冢，牛羊逾圈牢。","厨薪散流蘖，囷米为浮糟。","卧席不遑卷，剥茧仍未缫。","老弱但坐视，闾里将安逃。","徙居共扰扰，来势方滔滔。","嗟余偶同病，哀尔为生劳。","晴日慰人愿，寒风送惊涛。","藩篱出旧趾，蠃蚌遗平皋。","流窜非择地，艰难理宜遭。","胡为苦戚戚，一夕生二毛。"]},{"t":"汲阳阻风","f":"五言古诗","c":["钟陵距池阳，相望千里内。","江神欺我贫，屡作风雨碍。","欲投皖公宿，三日逢一噫。","孤篷面空山，朝食淡无菜。","白醪幸馀沥，黄卷漫相对。","饥吟非吾病，疾走老所戒。","焦先近不远，蜗舍闻尚在。","区区问养生，借我一帆快。"]},{"t":"竹枝歌 其二","f":"七言绝句","c":["扁舟日落驻平沙，茅屋竹篱三四家。","连舂并汲各无语，齐唱竹枝如有嗟。"]},{"t":"约洞山文老夜话","f":"七言律诗","c":["山中十月定多寒，才过开炉便出山。","堂众久参缘自熟，郡人迎请怪忙还。","问公胜法须时见，要我清谈有夜阑。","今夕客房应不睡，欲随明月到林间。"]},{"t":"老史","f":"五言古诗","c":["口食阳翟粟，身衣阳谷丝。","二物不相即，饱暖常不时。","老史知我穷，一岁一奔驰。","方暑劝脂车，苦寒伺来归。","嗟我垂老年，未免忧寒饥。","老史甚忠信，但恨性重迟。","事我三十年，闵闵不相离。","我门了无求，辛苦终不辞。","平生金石交，至此或已携。","老史未易得，试复养其儿。"]},{"t":"老柏","f":"五言古诗","c":["柏根可合抱，柏身长百尺。","我年类汝老，我心同汝直。","我贫初无居，爱汝买此宅。","索居怀旧友，开轩得三益。","风中有馀劲，雪后不改色。","我贫不栽花，绕屋多种竹。","全家谬闻道，举目无他物。","晨兴辄相对，知我有惭德。"]},{"t":"自陈适齐戏题","f":"七言律诗","c":["庠斋三岁最无功，羞愧宣王禄万钟。","犹欲谈经谁复信，相招执籥更须从。","陈风清净眠真足，齐俗强梁懒不容。","久尔安闲长自怪，此行磨折信天工。"]},{"t":"舟中风雪五绝 其一","f":"七言绝句","c":["北风吹雪密还稀，雪势渐多风力微。","孤棹独依银世界，山川路绝欲安归。"]},{"t":"舟中听琴","f":"七言古诗","c":["江流浩浩群动息，琴声琅琅中夜鸣。","水深天阔音响远，仰视牛斗皆从横。","昔有至人爱奇曲，学之三岁终无成。","一朝随师过沧海，留置绝岛不复迎。","终年见怪心自感，海水震掉鱼龙惊。","翻回荡潏有遗韵，琴意忽忽从此生。","师来迎笑问所得，抚手无言心已明。","世人嚣嚣好丝竹，撞钟击鼓浪谓荣。","安知江琴韵超绝，摆耳大笑不肯听。"]},{"t":"舟次大云仓回寄孔武仲","f":"五言古诗","c":["一风失前期，十日不相见。","君帆一何驶，去若乘风箭。","我舟一何迟，出没蔽葭薍。","瓮中有白糟，床上有黄卷。","妻孥不足共，思子但长叹。","池阳重相遇，抚手成一粲。","先行复草草，回首空眷眷。","人生类如此，迟速亦何算。","一见诚偶然，四海良独远。","相期庐山阴，把臂上云巘。"]},{"t":"舟次磁湖以风浪留二日不得进子瞻以诗见寄作二篇答之前篇自赋后篇次韵 其一","f":"七言律诗","c":["惭愧江淮南北风，扁舟千里得相从。","黄州不到六十里，白浪俄生百万重。","自笑一生浑类此，可怜万事不由侬。","夜深魂梦先飞去，风雨对床闻晓钟。"]},{"t":"舟过严陵滩将谒祠登台舟人夜解及明已远至桐庐望桐君山寺缥缈可爱遂以小舟游之二绝 其一","f":"七言绝句","c":["扁舟匆草出山来，惭愧严公旧钓台。","舟子未应知此恨，梦中飞楫定谁催。"]},{"t":"西轩画枯木怪石","f":"七言古诗","c":["西轩素屏开白云，婆娑老桂依霜轮。","顾兔出走蟾蜍奔，河汉卷海机石蹲。","牵牛自载倚桂根，清风飒然吹四邻。","东坡妙思传子孙，作诗仿佛追前人。","笔墨堕地称奇珍，闭藏不听落泥尘。","老人读书眼病昏，一看落笔生精神。"]},{"t":"西轩种山丹","f":"五言古诗","c":["淮阳千叶花，到此三百里。","城中众名园，栽接比桃李。","吾庐适新成，西有数畦地。","乘秋种山丹，得雨生可喜。","山丹非佳花，老圃有深意。","宿根已得土，绝品皆可寄。","明年春阳升，盈尺烂如绮。","居然盗天功，信矣斯人智。","根苗相因依，非真亦非伪。","客来但一笑，勿问所从致。"]},{"t":"西湖二咏 其一 观捕鱼","f":"七言古诗","c":["西湖不放长竿入，群鱼空作淘河食。","渔人攘臂下前汀，荡漾清波浮两腋。","藕梢菱蔓不容网，箔作长围徒手得。","逡巡小舟十斛重，踊跃长鱼一夫力。","柳条穿颊洗黄金，鲙缕堆盘雪花积。","烧薤香橙巧相与，白饭青蔬甘莫逆。","食罢相携堤上步，将散重煎叶家白。","人生此事最便身，金印垂腰定何益。"]},{"t":"西湖二咏 其二 食鸡头","f":"七言古诗","c":["芡叶初生绉如縠，南风吹开轮脱毂。","紫苞青刺攒猬毛，水面放花波底熟。","森然赤手初莫近，谁料明珠藏满腹。","剖开膏液尚模糊，大盎磨声风雨速。","清泉活火曾未久，满堂坐客分升掬。","纷然咀噍惟恐迟，势若群雏方脱粟。","东都每忆会灵沼，南国陂塘种尤足。","东游尘土未应嫌，此物秋来日尝食。"]},{"t":"迁居汝南","f":"五言古诗","c":["我昔还自南，从此适旧许。","再岁常杜门，壁观无与语。","何人自惊顾，未听即安处。","亟逃颍州籍，来贯汝南户。","妻孥不及将，童仆具樽俎。","身如孤栖鹊，夜起三绕树。","故人乐安生，风节似其父。","忻然暂一笑，舍我西南去。","去已还闭门，时作野田步。","萧条古僧舍，遗像得颜鲁。","精神凛如生，今昔吾与女。","已同羁穷厄，但脱生死怖。","幸世方和平，有土非寇虏。","春寒烧黄茅，昼饭煮青茹。","何必潩上田，幸此足粳稌。","归心念狂简，裁制时已莫。"]},{"t":"过九华山","f":"五言古诗","c":["南迁私自喜，看尽江南山。","孤舟少僮仆，此志还复难。","局促守破窗，联翩过重峦。","忽惊九华峰，高拱立我前。","萧然九仙人，缥缈淩云烟。","碧霞为裳衣，首冠青琅玕。","挥手谢世人，可望不可攀。","我行竟草草，安能拍其肩。","但闻有高士，卧听松风眠。","松根得茯苓，状若千岁鼋。","煮食一朝尽，终身弃腥膻。","腹背生绿毛，轻举如翔鸾。","相逢欲借问，已在长松端。","何年脱罪罟，出处良自便。","芒鞋拄藤杖，逢山即盘桓。","斯人未可求，岩室傥复存。"]},{"t":"过张天骥山人郊居","f":"五言古诗","c":["南山莫将归，下访张夫子。","黍稷满秋风，蓬麻翳邻里。","君年三十八，三十有归意。","躬耕奉慈亲，未觉锄耰鄙。","读书北窗竹，酿酒南园水。","松菊半成阴，日有幽居喜。","客来时借问，问子何年起。","新求西溪石，更筑茆堂址。","但令三岁熟，此计行亦遂。","堂成不出门，清名满朝市。"]},{"t":"过龟山","f":"五言古诗","c":["再涉长淮水，惊呼十四年。","龟山老僧在，相见一茫然。","僧老不自知，我老私自怜。","驱驰定何获，少壮空已捐。","掉头不见答，笑指岸下船。","人生何足云，陵谷自变迁。","当年此山下，莫测千仞渊。","渊中械神物，自昔尧禹传。","帆樯避石壁，风雨随香烟。","尔来放冬汴，冷沙涨成田。","褰裳六月渡，中流一带牵。","俯首见砂砾，群渔捕鲂鳣。","父老但惊叹，此理未易原。","何况七尺躯，不为物所旋。","众形要同尽，独有无生全。","百年争夺中，扰扰谁相贤。"]},{"t":"过宜宾见夷中乱山","f":"五言古诗","c":["江流日益深，民语渐已变。","岸阔山尽平，连峰远非汉。","惨惨瘴气青，薄薄寒日暖。","峰峦若崖石，草木条干短。","遥想彼居人，状类麇鹿窜。","何时遂平定，戍卒从此返。"]},{"t":"那吒","f":"七言古诗","c":["北方天王有狂子，只知拜佛不拜父。","佛知其愚难教语，宝塔令父左手举。","儿来见佛头辄俯，且与拜父略相似。","佛如优昙难值遇，见者闻道出生死。","嗟尔何为独如此，业果已定磨不去。","佛灭到今千万祀，只在江湖挽船处。"]},{"t":"闭门","f":"五言古诗","c":["闭门颍昌市，不识颍昌人。","身闲未易过，闲久生暗尘。","我念作闲计，欲与黄卷亲。","少年病书史，未老目先昏。","掩卷默无言，闭目中自存。","心光定中发，廓然四无邻。","不知心已空，不见外物纷。","瞿昙昔尝云，咄哉不肯信。","一见勿复失，愈久当愈真。"]},{"t":"闲居五咏 其一 杜门","f":"五言古诗","c":["可怜杜门久，不觉杜门非。","床锐日日销，髀肉年年肥。","眼暗书罢读，肺病酒亦稀。","经年客不至，不冠仍不衣。","视听了不昧，色声久已微。","终然浑为一，谁言我无归。"]},{"t":"闲居五咏 其二 坐忘","f":"五言古诗","c":["少年常病肺，纳息肺自敛。","灵液洗昏烦，百药无此验。","尔来观坐忘，一语顿非渐。","道妙有至力，端能破诸暗。","跏趺百无营，纯白乃受染。","至人不妄言，此说岂吾僭。"]},{"t":"闲居五咏 其三 读书","f":"五言古诗","c":["习气不易除，书魔閒即至。","图史纷满前，展卷辄忘睡。","古今浩无垠，得失同一轨。","前人已不悟，今人复如此。","悯然嫠妇忧，嗟哉肉食鄙。","掩卷勿重陈，恸哭伤人气。"]},{"t":"闲居五咏 其五 移竹","f":"五言古诗","c":["前年买南园，本为一亩竹。","稍去千百竿，欲广西南屋。","本心初不尔，百口居未足。","黾勉斤斧馀，惭愧琅玕绿。","东园有馀地，补种何年复。","凛凛岁寒姿，馀木非此族。"]},{"t":"闲居五咏 其四 买宅","f":"五言古诗","c":["我老未有宅，诸子以为言。","东家欲迁去，馀积尚可捐。","一费岂不病，百口傥获安。","田家伐榆枣，赋役输缗钱。","长大可双栋，琐细堪尺椽。","生理付儿曹，老幸食且眠。"]},{"t":"问黄檗长老疾","f":"七言绝句","c":["四大俱非五蕴空，身心河岳尽消镕。","病根何处容他住，日夜还将药石攻。"]},{"t":"严颜碑","f":"七言古诗","c":["古碑残缺不可读，远人爱惜未忍磨。","相传昔者严太守，刻石千岁字已讹。","严颜平生吾不记，独忆城破节最高。","被擒不辱古亦有，吾爱善折张飞豪。","军中生死何足怪，乘胜使气可若何。","斫头徐死子无怒，我岂畏死如儿曹。","匹夫受戮或不避，所重壮气吞黄河。","临危闲暇有如此，览碑慷慨思横戈。"]},{"t":"佛池口遇风雨","f":"七言古诗","c":["长江五月多风暴，欲行先看风日好。","此风忽作东南来，阴云如涌拨不开。","惊雷往还转车毂，狂波低昂起坑谷。","中流一叶那复持，卷舒已副天公知。","解帆转柁不容语，佛池口中幸可住。","须臾急雨变昏霾，柁师喜贺风已回。","澄溪不动萦白练，老木苍崖蔚葱茜。","系舟茅屋得青蔬，试问钓船还有鱼。","开樽引满向妻子，明日复行未须怖。","阴阳开阖良等闲，扁舟谁令乘险艰。"]},{"t":"初发彭城有感寄子瞻","f":"五言古诗","c":["秋晴卷流潦，古汴日向乾。","扁舟久不解，畏此行路难。","此行亦不远，世故方如山。","我持一寸刃，巉绝何由刊。","念昔各年少，松筠閟南轩。","闭门书史丛，开口治乱根。","文章风云起，胸胆渤澥宽。","不知身安危，俯仰道所存。","横流一倾溃，万类争崩奔。","孔融汉儒者，本自轻曹瞒。","誓将贫贱身，一悟世俗昏。","岂意十年内，日夜增涛澜。","生民竟憔悴，游宦岂复安。","水深火益热，人知蹈忧患。","甄丰且自叛，刘歆苟盘桓。","而况我与兄，饱食顾依然。","上愿天地仁，止此祸乱源。","岁月一徂逝，尚能反丘园。"]},{"t":"初发嘉州","f":"五言古诗","c":["放舟沫江滨，往意念荆楚。","击鼓树两旗，势如远征戍。","纷纷上船人，橹急不容语。","余生虽江阳，未省至嘉树。","巉巉九顶峰，可爱不可住。","飞舟过山足，佛脚见江浒。","舟人尽敛容，竞欲揖其拇。","俄顷已不见，乌牛在中渚。","移舟近山阴，壁峭上无路。","云有古郭生，此地苦笺注。","区区辨虫鱼，尔雅细分缕。","洗砚去残墨，遍水如黑雾。","至今江上鱼，顶有遗墨处。","览物悲古人，嗟此空自苦。","余今方南行，朝夕事鸣橹。","至楚不复留，上马千里去。","谁能居深山，永与禽兽伍。","此事谁是非，行行重回顾。"]},{"t":"初到陈州二首 其一","f":"五言律诗","c":["谋拙身无向，归田久未成。","来陈为懒计，传道愧虚名。","俎豆终难合，诗书强欲明。","斯文吾已试，深恐误诸生。"]}]};